fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("text.txt")?;
    let mut words: Vec<Str> = Vec::new();
    let mut counts: Vec<i64> = Vec::new();
    let mut cur = String::new();
    for c in text.chars() {
        if c.is_ascii_alphabetic() {
            cur.push(c.to_ascii_lowercase());
        } else if cur.len() > 0 {
            let mut found = false;
            let mut i = 0;
            while i < words.len() {
                if words[i] == cur {
                    counts[i] = counts[i] + 1;
                    found = true;
                    break;
                }
                i = i + 1;
            }
            if !found {
                words.push(cur.clone());
                counts.push(1);
            }
            cur = String::new();
        }
    }
    if cur.len() > 0 {
        let mut found = false;
        let mut i = 0;
        while i < words.len() {
            if words[i] == cur {
                counts[i] = counts[i] + 1;
                found = true;
                break;
            }
            i = i + 1;
        }
        if !found {
            words.push(cur.clone());
            counts.push(1);
        }
    }

    let mut out = String::new();
    let mut used: Vec<bool> = Vec::new();
    let mut k = 0;
    while k < words.len() {
        used.push(false);
        k = k + 1;
    }
    let mut n = 0;
    while n < 5 {
        let mut best: i64 = -1;
        let mut j = 0;
        while j < words.len() {
            if !used[j] {
                if best < 0 || counts[j] > counts[best] || (counts[j] == counts[best] && words[j] < words[best]) {
                    best = j;
                }
            }
            j = j + 1;
        }
        if best < 0 {
            break;
        }
        used[best] = true;
        out.push_str(&words[best]);
        out.push_str(" ");
        out.push_str(&counts[best].to_string());
        out.push_str("\n");
        n = n + 1;
    }
    Ok(out)
}

