fn fmt_money(cents: i64) -> Str {
    let neg = cents < 0;
    let c = if neg { -cents } else { cents };
    let body = format!("{}.{:02}", c / 100, c % 100);
    if neg { format!("-{}", body) } else { body }
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("sales.csv")?;
    let mut names: Vec<Str> = Vec::new();
    let mut qtys: Vec<i64> = Vec::new();
    let mut revs: Vec<i64> = Vec::new();
    let mut skipped: i64 = 0;
    let mut first = true;

    for raw in text.split("\n") {
        let line = raw.trim();
        if line.len() == 0 {
            continue;
        }
        if first {
            first = false;
            continue;
        }
        let fields: Vec<Str> = line.split(",").map(|f| f.trim()).collect();
        if fields.len() != 5 {
            skipped += 1;
            continue;
        }
        let q = fields[3].parse::<i64>();
        let u = fields[4].parse::<i64>();
        if q.is_err() || u.is_err() {
            skipped += 1;
            continue;
        }
        let q = q.unwrap();
        let u = u.unwrap();
        let region = fields[1].clone();
        let mut idx: i64 = -1;
        let mut i: usize = 0;
        while i < names.len() {
            if names[i] == region {
                idx = i as i64;
            }
            i += 1;
        }
        if idx < 0 {
            names.push(region);
            qtys.push(q);
            revs.push(q * u);
        } else {
            let k = idx as usize;
            qtys[k] += q;
            revs[k] += q * u;
        }
    }

    // order indices: revenue desc, then name asc
    let mut order: Vec<usize> = Vec::new();
    let mut i: usize = 0;
    while i < names.len() {
        order.push(i);
        i += 1;
    }
    let n = order.len();
    let mut a: usize = 1;
    while a < n {
        let mut b = a;
        while b > 0 {
            let x = order[b - 1];
            let y = order[b];
            let swap = if revs[x] != revs[y] {
                revs[y] > revs[x]
            } else {
                names[y] < names[x]
            };
            if swap {
                order[b - 1] = y;
                order[b] = x;
                b -= 1;
            } else {
                break;
            }
        }
        a += 1;
    }

    let mut out = String::new();
    for k in order {
        out.push_str(&format!("{} {} {}\n", names[k], qtys[k], fmt_money(revs[k])));
    }
    out.push_str(&format!("skipped {}", skipped));
    Ok(out)
}

