                order[b] = x;
                b -= 1;
            } else {
                break;
            }
        }
        a += 1;
    }

    let mut out: Str = "";
    for k in order {
        out = out + names[k] + " " + qtys[k].to_str() + " " + fmt_money(revs[k]) + "\n";
    }
    out = out + "skipped " + skipped.to_str();
    Ok(out)
}

