            total += qty * price;
        }
        if status == "paid" {
            let customer = order.get("customer")?.as_str()?.to_string();
            let entry = paid.entry(customer).or_insert((0, 0));
            entry.0 += 1;
            entry.1 += total;
        } else if status == "refunded" {
            refunded_n += 1;
            refunded_total += total;
        } else if status == "pending" {
            pending_n += 1;
        }
    }

    let mut out = String::new();
    for (customer, (n, total)) in paid.iter() {
        out.push_str(&format!("{} {} {}\n", customer, n, total));
    }
    out.push_str(&format!("refunded {} {}\n", refunded_n, refunded_total));
    out.push_str(&format!("pending {}\n", pending_n));
    Ok(out)
}

