fn normalize(line: &Str) -> Option<Str> {
    let s = line.trim().to_lowercase();
    if s.is_empty() {
        return None;
    }
    let parts: Vec<Str> = s.split("@").collect();
    if parts.len() != 2 {
        return None;
    }
    let local = parts[0].clone();
    let domain = parts[1].clone();
    if local.is_empty() {
        return None;
    }
    if domain.is_empty() || !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
        return None;
    }
    let mut l = local;
    if domain == "gmail.com" {
        let pieces: Vec<Str> = l.split("+").collect();
        l = pieces[0].clone();
        l = l.replace(".", "");
    }
    Some(l + "@" + &domain)
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("emails.txt")?;
    let mut good: Vec<Str> = Vec::new();
    let mut invalid = 0;
    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        match normalize(&line) {
            Some(addr) => good.push(addr),
            None => invalid += 1,
        }
    }
    good.sort();
    good.dedup();
    let mut out = Str::new();
    for a in good.iter() {
        out = out + a + "\n";
    }
    out = out + "invalid " + &invalid.to_string();
    Ok(out)
}

