fn check(line: &Str) -> Str {
    let mut stack: Vec<char> = Vec::new();
    let mut col: i64 = 0;
    for c in line.chars() {
        col += 1;
        if c == '(' {
            stack.push(')');
        } else if c == '[' {
            stack.push(']');
        } else if c == '{' {
            stack.push('}');
        } else if c == ')' || c == ']' || c == '}' {
            match stack.pop() {
                None => {
                    return format("col {}: unexpected {}", col, c);
                }
                Some(e) => {
                    if e != c {
                        return format("col {}: expected {}, found {}", col, e, c);
                    }
                }
            }
        }
    }
    match stack.pop() {
        None => "ok".to_string(),
        Some(e) => format("unclosed {}", e),
    }
}

