fn idx(names: &mut Vec<Str>, s: Str) -> usize {
    let mut i = 0;
    while i < names.len() {
        if names[i] == s {
            return i;
        }
        i += 1;
    }
    names.push(s);
    return names.len() - 1;
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read("routes.txt")?;
    let mut names: Vec<Str> = Vec::new();
    let mut ea: Vec<usize> = Vec::new();
    let mut eb: Vec<usize> = Vec::new();
    let mut ew: Vec<i64> = Vec::new();
    let mut ta: Vec<usize> = Vec::new();
    let mut tb: Vec<usize> = Vec::new();

    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() || t.starts_with("#") {
            continue;
        }
        let parts: Vec<Str> = t.split_whitespace().collect();
        if parts.len() == 4 && parts[0] == "road" {
            let a = idx(&mut names, parts[1]);
            let b = idx(&mut names, parts[2]);
            let w: i64 = parts[3].parse()?;
            ea.push(a);
            eb.push(b);
            ew.push(w);
        } else if parts.len() == 3 && parts[0] == "trip" {
            let a = idx(&mut names, parts[1]);
            let b = idx(&mut names, parts[2]);
            ta.push(a);
            tb.push(b);
        }
    }

    let inf: i64 = 4000000000000000000;
    let n = names.len();
    let mut out: Vec<Str> = Vec::new();

    let mut k = 0;
    while k < ta.len() {
        let src = ta[k];
        let dst = tb[k];
        k += 1;

        let mut dist: Vec<i64> = Vec::new();
        let mut i = 0;
        while i < n {
            dist.push(inf);
            i += 1;
        }
        dist[dst] = 0;
        let mut changed = true;
        while changed {
            changed = false;
            let mut e = 0;
            while e < ea.len() {
                let a = ea[e];
                let b = eb[e];
                let w = ew[e];
                if dist[a] < inf && dist[a] + w < dist[b] {
                    dist[b] = dist[a] + w;
                    changed = true;
                }
                if dist[b] < inf && dist[b] + w < dist[a] {
                    dist[a] = dist[b] + w;
                    changed = true;
                }
                e += 1;
            }
        }

        if dist[src] >= inf {
            out.push(format!("{} {} unreachable", names[src], names[dst]));
            continue;
        }
        if src == dst {
            out.push(format!("{} 0", names[src]));
            continue;
        }

        let mut route = names[src].clone();
        let mut cur = src;
        while cur != dst {
            let mut best: usize = n;
            let mut e = 0;
            while e < ea.len() {
                let a = ea[e];
                let b = eb[e];
                let w = ew[e];
                if a == cur && dist[b] < inf && dist[b] + w == dist[cur] {
                    if best == n || names[b] < names[best] {
                        best = b;
                    }
                }
                if b == cur && dist[a] < inf && dist[a] + w == dist[cur] {
                    if best == n || names[a] < names[best] {
                        best = a;
                    }
                }
                e += 1;
            }
            route = format!("{} -> {}", route, names[best]);
            cur = best;
        }
        out.push(format!("{} {}", route, dist[src]));
    }

    Ok(out.join("\n"))
}

