        let dst = tb[k];
        k += 1;

        let mut dist: List<Int> = [];
        let mut i = 0;
        while i < n {
            dist.push(inf);
            i += 1;
        }
        dist[dst] = 0;
        let mut changed = true;
        while changed {
            changed = false;
            let mut e = 0;
            while e < ea.len() {
                let a = ea[e];
                let b = eb[e];
                let w = ew[e];
                if dist[a] < inf && dist[a] + w < dist[b] {
                    dist[b] = dist[a] + w;
                    changed = true;
                }
                if dist[b] < inf && dist[b] + w < dist[a] {
                    dist[a] = dist[b] + w;
                    changed = true;
                }
                e += 1;
            }
        }

        if dist[src] >= inf {
            out.push(names[src].clone() + " " + names[dst].clone() + " unreachable");
            continue;
        }
        if src == dst {
            out.push(names[src].clone() + " 0");
            continue;
        }

        let mut route = names[src].clone();
        let mut cur = src;
        while cur != dst {
            let mut best: Int = n;
            let mut e = 0;
            while e < ea.len() {
                let a = ea[e];
                let b = eb[e];
                let w = ew[e];
                if a == cur && dist[b] < inf && dist[b] + w == dist[cur] {
                    if best == n || names[b] < names[best] {
                        best = b;
                    }
                }
                if b == cur && dist[a] < inf && dist[a] + w == dist[cur] {
                    if best == n || names[a] < names[best] {
                        best = a;
                    }
                }
                e += 1;
            }
            route = route + " -> " + names[best].clone();
            cur = best;
        }
        out.push(route + " " + dist[src].to_str());
    }

    Ok(out.join("\n"))
}

enum J {
    Null,
    Bool(bool),
    Num(i64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

fn skip_ws(s: &Vec<u8>, i: &mut usize) {
    while *i < s.len() && (s[*i] == 32 || s[*i] == 10 || s[*i] == 13 || s[*i] == 9) {
        *i += 1;
    }
}

fn parse_str(s: &Vec<u8>, i: &mut usize) -> String {
    // assumes s[*i] == '"'
    *i += 1;
    let mut out: Vec<u8> = Vec::new();
    while *i < s.len() && s[*i] != 34 {
        if s[*i] == 92 {
            *i += 1;
            let c = s[*i];
            if c == 110 {
                out.push(10);
            } else if c == 116 {
                out.push(9);
            } else if c == 114 {
                out.push(13);
            } else if c == 98 {
                out.push(8);
            } else if c == 102 {
                out.push(12);
            } else if c == 117 {
                let mut v: u32 = 0;
                let mut k = 0;
                while k < 4 {
                    *i += 1;
                    let h = s[*i];
                    let d: u32 = if h >= 48 && h <= 57 {
                        (h - 48) as u32
                    } else if h >= 97 && h <= 102 {
                        (h - 97 + 10) as u32
                    } else {
                        (h - 65 + 10) as u32
                    };
                    v = v * 16 + d;
                    k += 1;
                }
                let ch = char::from_u32(v).unwrap_or('?');
                let mut buf = String::new();
                buf.push(ch);
                for b in buf.as_bytes() {
                    out.push(*b);
                }
            } else {
                out.push(c);
            }
        } else {
            out.push(s[*i]);
        }
        *i += 1;
    }
    *i += 1;
    String::from_utf8(out).unwrap_or(String::new())
}

fn parse(s: &Vec<u8>, i: &mut usize) -> J {
    skip_ws(s, i);
    let c = s[*i];
    if c == 123 {
        *i += 1;
        let mut items: Vec<(String, J)> = Vec::new();
        skip_ws(s, i);
        if s[*i] == 125 {
            *i += 1;
            return J::Obj(items);
        }
        loop {
            skip_ws(s, i);
            let k = parse_str(s, i);
            skip_ws(s, i);
            *i += 1; // colon
            let v = parse(s, i);
            items.push((k, v));
            skip_ws(s, i);
            if s[*i] == 44 {
                *i += 1;
            } else {
                *i += 1; // closing brace
                break;
            }
        }
        return J::Obj(items);
    }
    if c == 91 {
        *i += 1;
        let mut items: Vec<J> = Vec::new();
        skip_ws(s, i);
        if s[*i] == 93 {
            *i += 1;
            return J::Arr(items);
        }
        loop {
            let v = parse(s, i);
            items.push(v);
            skip_ws(s, i);
            if s[*i] == 44 {
                *i += 1;
            } else {
                *i += 1;
                break;
            }
        }
        return J::Arr(items);
    }
    if c == 34 {
        return J::Str(parse_str(s, i));
    }
    if c == 116 {
        *i += 4;
        return J::Bool(true);
    }
    if c == 102 {
        *i += 5;
        return J::Bool(false);
    }
    if c == 110 {
        *i += 4;
        return J::Null;
    }
    let mut neg = false;
    if s[*i] == 45 {
        neg = true;
        *i += 1;
    }
    let mut v: i64 = 0;
    while *i < s.len() && s[*i] >= 48 && s[*i] <= 57 {
        v = v * 10 + (s[*i] - 48) as i64;
        *i += 1;
    }
    if neg {
        v = -v;
    }
    J::Num(v)
}

fn is_obj(j: &J) -> bool {
    match j {
        J::Obj(_) => true,
        _ => false,
    }
}

fn is_null(j: &J) -> bool {
    match j {
        J::Null => true,
        _ => false,
    }
}

fn merge(base: J, ov: J) -> J {
    match (base, ov) {
        (J::Obj(mut items), J::Obj(oitems)) => {
            for (k, v) in oitems {
                let mut pos: usize = items.len();
                let mut idx = 0;
                while idx < items.len() {
                    if items[idx].0 == k {
                        pos = idx;
                        break;
                    }
                    idx += 1;
                }
                if is_null(&v) {
                    if pos < items.len() {
                        items.remove(pos);
                    }
                } else if pos < items.len() {
                    let (_, old) = items.remove(pos);
                    let nv = if is_obj(&old) && is_obj(&v) {
                        merge(old, v)
                    } else if is_obj(&v) {
                        merge(J::Obj(Vec::new()), v)
                    } else {
                        v
                    };
                    items.insert(pos, (k, nv));
                } else {
                    let nv = if is_obj(&v) {
                        merge(J::Obj(Vec::new()), v)
                    } else {
                        v
                    };
                    items.push((k, nv));
                }
            }
            J::Obj(items)
        }
        (_, o) => o,
    }
}

fn quote(s: &String) -> String {
    let mut out = String::new();
    out.push('"');
    for ch in s.chars() {
        if ch == '"' {
            out.push('\\');
            out.push('"');
        } else if ch == '\\' {
            out.push('\\');
            out.push('\\');
        } else if ch == '\n' {
            out.push('\\');
            out.push('n');
        } else if ch == '\t' {
            out.push('\\');
            out.push('t');
        } else if ch == '\r' {
            out.push('\\');
            out.push('r');
        } else {
            out.push(ch);
        }
    }
    out.push('"');
    out
}

fn flatten(j: &J, path: String, out: &mut Vec<(String, String)>) {
    match j {
        J::Null => {
            out.push((path, String::from("null")));
        }
        J::Bool(b) => {
            let t = if *b { "true" } else { "false" };
            out.push((path, String::from(t)));
        }
        J::Num(n) => {
            out.push((path, n.to_string()));
        }
        J::Str(s) => {
            out.push((path, quote(s)));
        }
        J::Arr(items) => {
            if items.len() == 0 {
                out.push((path, String::from("[]")));
            } else {
                let mut idx = 0;
                while idx < items.len() {
                    let mut p = path.clone();
                    if p.len() > 0 {
                        p.push('.');
                    }
                    p.push_str(&idx.to_string());
                    flatten(&items[idx], p, out);
                    idx += 1;
                }
            }
        }
        J::Obj(items) => {
            if items.len() == 0 {
                out.push((path, String::from("{}")));
            } else {
                for (k, v) in items {
                    let mut p = path.clone();
                    if p.len() > 0 {
                        p.push('.');
                    }
                    p.push_str(k);
                    flatten(v, p, out);
                }
            }
        }
    }
}

