fn skip_ws(s: Vec<u8>, start: usize) -> usize {
    let mut i = start;
    while i < s.len() && (s[i] == 32 || s[i] == 10 || s[i] == 13 || s[i] == 9) {
        i += 1;
    }
    i
}

fn parse_str(s: Vec<u8>, start: usize) -> PStr {
    let mut i = start + 1;
    let mut out: Vec<u8> = Vec::new();
    while i < s.len() && s[i] != 34 {
        if s[i] == 92 {
            i += 1;
            let c = s[i];
            if c == 110 {
                out.push(10);
            } else if c == 116 {
                out.push(9);
            } else if c == 114 {
                out.push(13);
            } else if c == 98 {
                out.push(8);
            } else if c == 102 {
                out.push(12);
            } else if c == 117 {
                let mut v: u32 = 0;
                let mut k = 0;
                while k < 4 {
                    i += 1;
                    let h = s[i];
                    let d: u32 = if h >= 48 && h <= 57 {
                        (h - 48) as u32
                    } else if h >= 97 && h <= 102 {
                        (h - 97 + 10) as u32
                    } else {
                        (h - 65 + 10) as u32
                    };
                    v = v * 16 + d;
                    k += 1;
                }
                if v < 128 {
                    out.push(v as u8);
                } else if v < 2048 {
                    out.push((192 + v / 64) as u8);
                    out.push((128 + v % 64) as u8);
                } else {
                    out.push((224 + v / 4096) as u8);
                    out.push((128 + (v / 64) % 64) as u8);
                    out.push((128 + v % 64) as u8);
                }
            } else {
                out.push(c);
            }
        } else {
            out.push(s[i]);
        }
        i += 1;
    }
    i += 1;
    PStr { s: Str::from_utf8(out).unwrap_or(Str::new()), pos: i }
}

fn parse(s: Vec<u8>, start: usize) -> PJ {
    let mut i = skip_ws(s.clone(), start);
    let c = s[i];
    if c == 123 {
        i += 1;
        let mut items: Vec<Entry> = Vec::new();
        i = skip_ws(s.clone(), i);
        if s[i] == 125 {
            return PJ { j: J::Obj(items), pos: i + 1 };
        }
        loop {
            i = skip_ws(s.clone(), i);
            let ks = parse_str(s.clone(), i);
            i = skip_ws(s.clone(), ks.pos);
            i += 1;
            let pv = parse(s.clone(), i);
            i = pv.pos;
            items.push(Entry { key: ks.s, val: pv.j });
            i = skip_ws(s.clone(), i);
            if s[i] == 44 {
                i += 1;
            } else {
                i += 1;
                break;
            }
        }
        return PJ { j: J::Obj(items), pos: i };
    }
    if c == 91 {
        i += 1;
        let mut items: Vec<J> = Vec::new();
        i = skip_ws(s.clone(), i);
        if s[i] == 93 {
            return PJ { j: J::Arr(items), pos: i + 1 };
        }
        loop {
            let pv = parse(s.clone(), i);
            i = pv.pos;
            items.push(pv.j);
            i = skip_ws(s.clone(), i);
            if s[i] == 44 {
                i += 1;
            } else {
                i += 1;
                break;
            }
        }
        return PJ { j: J::Arr(items), pos: i };
    }
    if c == 34 {
        let ps = parse_str(s.clone(), i);
        return PJ { j: J::Str(ps.s), pos: ps.pos };
    }
    if c == 116 {
        return PJ { j: J::Bool(true), pos: i + 4 };
    }
    if c == 102 {
        return PJ { j: J::Bool(false), pos: i + 5 };
    }
    if c == 110 {
        return PJ { j: J::Null, pos: i + 4 };
    }
    let mut neg = false;
    if s[i] == 45 {
        neg = true;
        i += 1;
    }
    let mut v: i64 = 0;
    while i < s.len() && s[i] >= 48 && s[i] <= 57 {
        v = v * 10 + (s[i] - 48) as i64;
        i += 1;
    }
    if neg {
        v = 0 - v;
    }
    PJ { j: J::Num(v), pos: i }
}

fn is_obj(j: J) -> bool {
