fn walk(dir: Dir, prefix: Str, acc: Vec<(Str, Int, Int)>) -> Result<Vec<(Str, Int, Int)>, Str> {
    let mut acc = acc;
    let entries = dir.list()?;
    for e in entries {
        let path = if prefix.len() == 0 { e.name() } else { prefix + "/" + e.name() };
        if e.is_dir() {
            let sub = dir.open_dir(e.name())?;
            acc = walk(sub, path, acc)?;
        } else {
            let text = dir.read_text(e.name())?;
            let bytes = text.len();
            let mut nl = 0;
            for b in text.bytes() {
                if b == 10 {
                    nl = nl + 1;
                }
            }
            let mut lines = nl;
            if bytes > 0 && text.bytes().last() != Some(10) {
                lines = lines + 1;
            }
            acc.push((path, bytes, lines));
        }
    }
    Ok(acc)
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let mut files = walk(input, "", Vec::new())?;
