fn parse_line(line: &str) -> Vec<String> {
    let mut fields: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut in_q = false;
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut i = 0;
    while i < n {
        let c = chars[i];
        if in_q {
            if c == '"' {
                if i + 1 < n && chars[i + 1] == '"' {
                    cur.push('"');
                    i += 1;
                } else {
                    in_q = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_q = true;
        } else if c == ',' {
            fields.push(cur);
            cur = String::new();
        } else {
            cur.push(c);
        }
        i += 1;
    }
    fields.push(cur);
    fields
}

fn json_escape(s: &str) -> String {
    let mut r = String::new();
    r.push('"');
    for c in s.chars() {
        if c == '"' {
            r.push('\\');
            r.push('"');
        } else if c == '\\' {
            r.push('\\');
            r.push('\\');
        } else if c == '\n' {
            r.push('\\');
            r.push('n');
        } else if c == '\r' {
            r.push('\\');
            r.push('r');
        } else if c == '\t' {
            r.push('\\');
            r.push('t');
        } else if (c as u32) < 32 {
            let code = c as u32;
            let hex = "0123456789abcdef";
            let hc: Vec<char> = hex.chars().collect();
            r.push('\\');
            r.push('u');
            r.push('0');
            r.push('0');
            r.push(hc[((code / 16) % 16) as usize]);
            r.push(hc[(code % 16) as usize]);
        } else {
            r.push(c);
        }
    }
    r.push('"');
    r
}

// Returns normalized integer text, or empty string if not an integer.
fn norm_int(s: &str) -> String {
    let t = s.trim();
    let chars: Vec<char> = t.chars().collect();
    let n = chars.len();
    let mut i = 0;
    let mut neg = false;
    if n > 0 && (chars[0] == '-' || chars[0] == '+') {
        neg = chars[0] == '-';
        i = 1;
    }
    if i >= n {
        return String::new();
    }
    let mut digits = String::new();
    let mut j = i;
    while j < n {
        let c = chars[j];
        if c < '0' || c > '9' {
            return String::new();
        }
        digits.push(c);
        j += 1;
    }
    let dc: Vec<char> = digits.chars().collect();
    let mut k = 0;
    while k + 1 < dc.len() && dc[k] == '0' {
        k += 1;
    }
    let mut out = String::new();
    let mut m = k;
    while m < dc.len() {
        out.push(dc[m]);
        m += 1;
    }
    if out == "0" {
        return out;
    }
    if neg {
        let mut r = String::from("-");
        r.push_str(&out);
        return r;
    }
    out
}

