fn normalize(name: Str) -> Str {
    let mut res = String::new();
    let mut last_dash = false;
    for c in name.chars() {
        let l = c.to_ascii_lowercase();
        if (l >= 'a' && l <= 'z') || (l >= '0' && l <= '9') || l == '.' {
            res.push(l);
            last_dash = false;
        } else if !last_dash {
            res.push('-');
            last_dash = true;
        }
    }
    res.trim_matches('-').to_string()
}

