fn is_part(name: &Str) -> bool {
    if !name.starts_with("part-") || !name.ends_with(".txt") {
        return false;
    }
    let chars: Vec<char> = name.chars().collect();
    // "part-" (5) + 4 digits + ".txt" (4) = 13
    if chars.len() != 13 {
        return false;
    }
    let mut i = 5;
    while i < 9 {
        if !chars[i].is_ascii_digit() {
            return false;
        }
        i += 1;
    }
    true
}

fn main(input: Dir, out: Dir) -> Result<Str, Error> {
    let names = input.list()?;
    let mut all: Vec<i64> = Vec::new();
    let mut parts: i64 = 0;
    let mut corrupt: i64 = 0;

    for name in names {
        if !is_part(&name) {
            continue;
        }
        parts += 1;
        let text = input.read_to_string(&name)?;
        let mut vals: Vec<i64> = Vec::new();
        let mut ok = true;
        for line in text.lines() {
            let t = line.trim();
            if t.is_empty() {
                continue;
            }
            match t.parse::<i64>() {
                Ok(v) => vals.push(v),
                Err(_) => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            for v in vals {
                all.push(v);
            }
        } else {
            corrupt += 1;
        }
    }

    all.sort();
    all.dedup();

    let mut body = Str::new();
    for v in all.iter() {
        body.push_str(&v.to_string());
        body.push_str("\n");
    }
    out.write("merged.txt", &body)?;

    let count = all.len();
    Ok(format!("parts {} corrupt {} values {}", parts, corrupt, count))
}

