fn main(src: Dir, dst: Dir) -> Result<Str, Error> {
    let mut src_names = src.list()?;
    src_names.sort();
    let dst_names = dst.list()?;

    let mut out = String::new();
    for name in src_names.iter() {
        let data = src.read(name)?;
        if dst_names.contains(name) {
            let existing = dst.read(name)?;
            if existing == data {
                out.push_str("same ");
            } else {
                dst.write(name, data)?;
                out.push_str("updated ");
            }
        } else {
            dst.write(name, data)?;
            out.push_str("added ");
        }
        out.push_str(name);
        out.push_str("\n");
    }

    let mut kept = 0;
    for name in dst_names.iter() {
        if !src_names.contains(name) {
            kept += 1;
        }
    }
    out.push_str("kept ");
    out.push_str(&kept.to_string());
    out.push_str("\n");
    Ok(out)
}

