fn main(input: Dir, counts: Kv) -> Result<Str, Error> {
    let text = input.read_to_string("visits.txt")?;

    // Tally this run's visits per page.
    let mut pages: Vec<Str> = Vec::new();
    let mut added: Vec<i64> = Vec::new();
    for line in text.lines() {
        let page = line.trim();
        if page.is_empty() {
            continue;
        }
        let mut found = false;
        let mut i = 0;
        while i < pages.len() {
            if pages[i] == page {
                added[i] = added[i] + 1;
                found = true;
                break;
            }
            i = i + 1;
        }
        if !found {
            pages.push(page.to_string());
            added.push(1);
        }
    }

    // Merge into the persistent totals.
    let mut i = 0;
    while i < pages.len() {
        let prev = match counts.get(&pages[i])? {
            Some(v) => v.parse::<i64>().unwrap_or(0),
            None => 0,
        };
        counts.set(&pages[i], (prev + added[i]).to_string())?;
        i = i + 1;
    }

    // Read back every page ever seen.
    let mut all: Vec<(Str, i64)> = Vec::new();
    for key in counts.keys()? {
        let total = match counts.get(&key)? {
            Some(v) => v.parse::<i64>().unwrap_or(0),
            None => 0,
        };
        all.push((key, total));
    }

    all.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));

    let mut out = String::new();
    for (page, total) in all {
        out.push_str(&page);
        out.push_str(" ");
        out.push_str(&total.to_string());
        out.push_str("\n");
    }
    Ok(out)
}

