fn main(input: Dir, users: Kv) -> Result<Str, Str> {
    let text = input.read_to_string("commands.txt")?;
    let mut out = String::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let parts: Vec<Str> = line.split_whitespace().collect();
        let cmd = parts[0];
        if cmd == "put" && parts.len() == 4 {
            let id = parts[1];
            users.set(id, format!("{} {}", parts[2], parts[3]));
            out.push_str(&format!("ok {}\n", id));
        } else if cmd == "rename" && parts.len() == 3 {
            let id = parts[1];
            match users.get(id) {
                Some(v) => {
                    let f: Vec<Str> = v.split(" ").collect();
                    users.set(id, format!("{} {}", parts[2], f[1]));
                    out.push_str(&format!("ok {}\n", id));
                }
                None => {
                    out.push_str(&format!("missing {}\n", id));
                }
            }
        } else if cmd == "get" && parts.len() == 2 {
            let id = parts[1];
            match users.get(id) {
                Some(v) => {
                    let f: Vec<Str> = v.split(" ").collect();
                    out.push_str(&format!(
                        "{{\"id\":\"{}\",\"name\":\"{}\",\"email\":\"{}\"}}\n",
                        id, f[0], f[1]
                    ));
                }
                None => {
                    out.push_str(&format!("missing {}\n", id));
                }
            }
        } else if cmd == "del" && parts.len() == 2 {
            let id = parts[1];
            match users.get(id) {
                Some(_) => {
                    users.delete(id);
                    out.push_str(&format!("ok {}\n", id));
                }
                None => {
                    out.push_str(&format!("missing {}\n", id));
                }
            }
        } else if cmd == "count" && parts.len() == 1 {
            out.push_str(&format!("count {}\n", users.keys().len()));
        } else {
            out.push_str(&format!("bad {}\n", line));
        }
    }
    Ok(out)
}

