fn main(input: Dir, state: Kv) -> Result<Str, Error> {
    let text = input.read_to_string("events.jsonl")?;
    let mut applied: i64 = 0;
    let mut duplicate: i64 = 0;
    let mut rejected: i64 = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parsed = json::parse(line);
        let v = match parsed {
            Ok(v) => v,
            Err(_) => {
                rejected += 1;
                continue;
            }
        };
        if !v.is_object() {
            rejected += 1;
            continue;
        }
        let id = match v.get("id").and_then(|x| x.as_str()) {
            Some(s) => s,
            None => {
                rejected += 1;
                continue;
            }
        };
        let account = match v.get("account").and_then(|x| x.as_str()) {
            Some(s) => s,
            None => {
                rejected += 1;
                continue;
            }
        };
        let cents = match v.get("cents").and_then(|x| x.as_i64()) {
            Some(n) => n,
            None => {
                rejected += 1;
                continue;
            }
        };

        let seen_key = "seen:" + id;
        if state.get(seen_key).is_some() {
            duplicate += 1;
            continue;
        }

        let bal_key = "bal:" + account;
        let current: i64 = match state.get(bal_key) {
            Some(s) => s.parse_i64().unwrap_or(0),
            None => 0,
        };
        state.set(bal_key, (current + cents).to_string());
        state.set(seen_key, "1");
        applied += 1;
    }

    let mut out = "applied " + applied.to_string()
        + " duplicate " + duplicate.to_string()
        + " rejected " + rejected.to_string() + "\n";

    let mut keys = state.keys("bal:");
    keys.sort();
    for k in keys {
        let account = k.strip_prefix("bal:").unwrap_or(k);
        let bal = state.get(k).unwrap_or("0");
        out = out + account + " " + bal + "\n";
    }
    Ok(out)
}

