fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
    let text = input.read("requests.txt")?;
    let mut out = String::new();
    for line in text.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 2 {
            continue;
        }
        let secs = match parts[0].parse::<i64>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let client = parts[1];
        let window = secs / 60;
        let key = format!("{}:{}", client, window);
        let count: i64 = match limits.get(&key) {
            Some(v) => match v.parse::<i64>() {
                Ok(n) => n,
                Err(_) => 0,
            },
            None => 0,
        };
        if count < 3 {
            limits.set(&key, &format!("{}", count + 1));
            out.push_str(&format!("{} {} allow\n", secs, client));
        } else {
            out.push_str(&format!("{} {} deny\n", secs, client));
        }
    }
    Ok(out)
}

