fn main(input: Dir, shop: Db) -> Result<Str, Str> {
    shop.execute(
        "CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)",
        [],
    )?;

    let text = input.read_to_string("orders.csv")?;
    let mut imported: i64 = 0;
    let mut skipped: i64 = 0;
    let mut rejected: i64 = 0;
    let mut first = true;

    for raw in text.split("\n") {
        if first {
            first = false;
            continue;
        }
        let line = raw.trim_end_matches("\r");
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<Str> = line.split(",").collect();
        if fields.len() != 5 {
            rejected += 1;
            continue;
        }
        let id = fields[0].trim().parse::<i64>();
        let qty = fields[3].trim().parse::<i64>();
        let unit = fields[4].trim().parse::<i64>();
        match (id, qty, unit) {
            (Ok(i), Ok(q), Ok(u)) => {
                let n = shop.execute(
                    "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
                    [i.into(), fields[1].into(), fields[2].into(), q.into(), u.into()],
                )?;
                if n > 0 {
                    imported += 1;
                } else {
                    skipped += 1;
                }
            }
            _ => {
                rejected += 1;
            }
        }
    }

    let mut out = format!("imported {} skipped {} rejected {}", imported, skipped, rejected);
    let rows = shop.query(
        "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
        [],
    )?;
    for row in rows {
        let product: Str = row.get(0)?;
        let rev: i64 = row.get(1)?;
        let cnt: i64 = row.get(2)?;
        out = format!("{}\n{} {} {}", out, product, rev, cnt);
    }
    Ok(out)
}

