fn parse_move(line: &Str) -> Option<(Str, i64)> {
    let parts = line.split_whitespace();
    if parts.len() != 2 {
        return None;
    }
    let sku = parts[0].clone();
    let amt = parts[1].clone();
    let sign = amt.slice(0, 1);
    let digits = amt.slice(1, amt.len());
    if sign != "+" && sign != "-" {
        return None;
    }
    if digits.len() == 0 {
        return None;
    }
    for c in digits.chars() {
        if c < '0' || c > '9' {
            return None;
        }
    }
    let n = digits.parse_i64();
    match n {
        Some(v) => {
            if v <= 0 {
                return None;
            }
            if sign == "-" {
                Some((sku, 0 - v))
            } else {
                Some((sku, v))
            }
        }
        None => None,
    }
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
    stock.execute("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", [])?;
    stock.execute("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", [])?;

    let text = input.read_to_string("moves.txt")?;

    // batches: (name, moves, ok)
    let mut names: Vec<Str> = Vec::new();
    let mut batch_moves: Vec<Vec<(Str, i64)>> = Vec::new();
    let mut batch_ok: Vec<bool> = Vec::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.len() == 0 {
            continue;
        }
        let parts = line.split_whitespace();
        if parts.len() == 2 && parts[0] == "batch" {
            names.push(parts[1].clone());
            batch_moves.push(Vec::new());
            batch_ok.push(true);
            continue;
        }
        if names.len() == 0 {
            continue;
        }
        let idx = names.len() - 1;
        match parse_move(&line) {
            Some(m) => {
                batch_moves[idx].push(m);
            }
            None => {
                batch_ok[idx] = false;
            }
        }
    }

    // load current stock
    let mut qty: Map<Str, i64> = Map::new();
    let rows = stock.query("SELECT sku, qty FROM stock", [])?;
    for r in rows {
        qty.insert(r.get_str(0)?, r.get_i64(1)?);
    }

    let mut seen: Set<Str> = Set::new();
    let mut out = String::new();

    let mut i = 0;
    while i < names.len() {
        let name = names[i].clone();
        let mut status = "applied";
        let mut is_seen = seen.contains(&name);
        if !is_seen {
            let rows = stock.query("SELECT name FROM applied WHERE name = ?", [name.clone()])?;
            if rows.len() > 0 {
                is_seen = true;
            }
        }
        seen.insert(name.clone());

        if is_seen {
            status = "skipped";
        } else if !batch_ok[i] {
            status = "rejected";
        } else {
            let mut tmp: Map<Str, i64> = Map::new();
            let mut good = true;
            for m in batch_moves[i].iter() {
                let cur = match tmp.get(&m.0) {
                    Some(v) => v,
                    None => match qty.get(&m.0) {
                        Some(v) => v,
                        None => 0,
                    },
                };
                let next = cur + m.1;
                if next < 0 {
                    good = false;
                    break;
                }
                tmp.insert(m.0.clone(), next);
            }
            if good {
                stock.execute("BEGIN", [])?;
                for (sku, v) in tmp.iter() {
                    stock.execute(
                        "INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty",
                        [sku.clone(), v],
                    )?;
                    qty.insert(sku.clone(), v);
                }
                stock.execute("INSERT INTO applied (name) VALUES (?)", [name.clone()])?;
                stock.execute("COMMIT", [])?;
            } else {
                status = "rejected";
            }
        }
        out.push_str(&name);
        out.push_str(" ");
        out.push_str(status);
        out.push_str("\n");
        i += 1;
    }

    let mut skus: Vec<Str> = Vec::new();
    for (k, v) in qty.iter() {
        if v != 0 {
            skus.push(k.clone());
        }
    }
    skus.sort();
    for k in skus.iter() {
        let v = qty.get(k).unwrap();
        out.push_str(k);
        out.push_str(" ");
        out.push_str(&v.to_string());
        out.push_str("\n");
    }

    Ok(out)
}

