        let idx = names.len() - 1;
        match parse_move(line.clone()) {
            Some(m) => {
                batch_moves[idx].push(m);
            }
            None => {
                batch_ok[idx] = false;
            }
        }
    }

    let mut qty: Map<Str, i64> = Map::new();
    let mut known: Vec<Str> = Vec::new();
    let rows = stock.query("SELECT sku, qty FROM stock", [])?;
    for r in rows {
        let k = r.get_str(0)?;
        qty.insert(k.clone(), r.get_i64(1)?);
        known.push(k);
    }

