            let mut tmp: Map<Str, i64> = Map::new();
            let mut touched: Vec<Str> = Vec::new();
            let mut good = true;
            for m in batch_moves[i].iter() {
                let cur = match tmp.get(m.sku.clone()) {
                    Some(v) => v,
