                        touched.push(m.sku.clone());
                        match qty.get(m.sku.clone()) {
                            Some(v) => v,
                            None => 0,
                        }
                    }
                };
                let next = cur + m.amt;
                if next < 0 {
                    good = false;
                    break;
                }
                tmp.insert(m.sku.clone(), next);
            }
            if good {
                stock.execute("BEGIN", [])?;
                for sku in touched.iter() {
                    let v = tmp.get(sku.clone()).unwrap();
                    stock.execute(
                        "INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty",
                        [sku.clone(), v],
                    )?;
                    let existed = match qty.get(sku.clone()) {
                        Some(_) => true,
                        None => false,
                    };
                    if !existed {
