}

struct Move {
    sku: Str,
    amt: Int,
}

fn parse_move(line: Str) -> Option<Move> {
    let parts = line.split_whitespace();
    if parts.len() != 2 {
        return None;
    }
    let sku = parts[0].clone();
    let amt = parts[1].clone();
    let sign = amt.slice(0, 1);
    let digits = amt.slice(1, amt.len());
    if sign != "+" && sign != "-" {
        return None;
    }
    if digits.len() == 0 {
        return None;
    }
    let first = digits.slice(0, 1);
    if first == "+" || first == "-" {
        return None;
    }
    let n = digits.parse_i64();
    match n {
        Some(v) => {
            if v <= 0 {
                return None;
            }
            if sign == "-" {
                Some(Move { sku: sku, amt: 0 - v })
            } else {
                Some(Move { sku: sku, amt: v })
            }
        }
        None => None,
    }
}

