fn valid(name: Str) -> bool {
    let n = name.len();
    if n < 1 || n > 32 {
        return false;
    }
    for c in name.chars() {
        let ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-';
        if !ok {
            return false;
        }
    }
    true
}

fn get_count(counts: Kv, name: Str) -> i64 {
    match counts.get(name) {
        Some(v) => v.parse::<i64>().unwrap_or(0),
        None => 0,
    }
}

fn reply(res: Outgoing, status: i64, body: Str) -> Result<Str, Str> {
    res.status(status);
    res.header("content-type", "application/json");
    res.body(body.clone());
    Ok(body)
}

fn counter_json(name: Str, count: i64) -> Str {
    format!("{{\"name\": \"{}\", \"count\": {}}}", name, count)
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, Str> {
    let method = req.method();
    let path = req.path();

    if method == "POST" && path.starts_with("/hit/") {
        let name = path[5..].to_string();
        if !valid(name.clone()) {
            return reply(res, 400, "{\"error\": \"bad name\"}".to_string());
        }
        let n = get_count(counts, name.clone()) + 1;
        counts.set(name.clone(), n.to_string());
        return reply(res, 200, counter_json(name, n));
    }

    if method == "GET" && path.starts_with("/count/") {
        let name = path[7..].to_string();
        if !valid(name.clone()) {
            return reply(res, 400, "{\"error\": \"bad name\"}".to_string());
        }
        let n = get_count(counts, name.clone());
        return reply(res, 200, counter_json(name, n));
    }

    if method == "GET" && path == "/top" {
        let keys = counts.keys();
        let mut items: Vec<(i64, Str)> = Vec::new();
        for k in keys {
            let c = get_count(counts, k.clone());
            items.push((c, k));
        }
        // selection of top three: higher count first, then name ascending
        let mut out = "[".to_string();
        let mut taken = 0;
        while taken < 3 && items.len() > 0 {
            let mut best = 0;
            let mut i = 1;
            while i < items.len() {
                let a = items[i].clone();
                let b = items[best].clone();
                if a.0 > b.0 || (a.0 == b.0 && a.1 < b.1) {
                    best = i;
                }
                i += 1;
            }
            let it = items.remove(best);
            if taken > 0 {
                out = format!("{}, ", out);
            }
            out = format!("{}{}", out, counter_json(it.1, it.0));
            taken += 1;
        }
        out = format!("{}]", out);
        return reply(res, 200, out);
    }

    reply(res, 404, "{\"error\": \"not found\"}".to_string())
}

fn valid(name: Str) -> bool {
    let n = name.len();
    if n < 1 || n > 32 {
        return false;
    }
    let allowed = "abcdefghijklmnopqrstuvwxyz0123456789-".to_string();
    let mut rest = name.clone();
    let mut i = 0;
    while i < 37 {
        let ch = allowed[i..i + 1].to_string();
        rest = rest.replace(ch, "".to_string());
        i += 1;
    }
    rest.len() == 0
}

