// Todo JSON API in kio.
// Store layout: "next" -> last assigned id (as text); "todo:ID" -> todo as JSON text.

fn reply(res: Outgoing, code: Int, body: Str) -> Str {
    res.status(code);
    res.header("content-type", "application/json");
    body
}

fn err(res: Outgoing, code: Int, msg: Str) -> Str {
    let mut o = Json::object();
    o.set("error", Json::str(msg));
    reply(res, code, o.to_string())
}

fn todo_json(id: Int, title: Str, done: Bool) -> Json {
    let mut o = Json::object();
    o.set("id", Json::int(id));
    o.set("title", Json::str(title));
    o.set("done", Json::bool(done));
    o
}

fn parse_id(seg: Str) -> Option<Int> {
    match seg.parse_int() {
        Some(n) => {
            if n.to_string() == seg && n >= 1 { Some(n) } else { None }
        }
        None => None,
    }
}

fn load(store: Kv, id: Int) -> Option<Json> {
    match store.get("todo:" + id.to_string()) {
        Some(s) => match Json::parse(s) {
            Ok(j) => Some(j),
            Err(_) => None,
        },
        None => None,
    }
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
    let method = req.method();
    let path = req.path();
    let parts = path.split("/");
    // "/todos" -> ["", "todos"]; "/todos/5" -> ["", "todos", "5"]
    let n = parts.len();
    if n < 2 || n > 3 || parts[0] != "" || parts[1] != "todos" {
        return err(res, 404, "not found");
    }

    let next: Int = match store.get("next") {
        Some(s) => match s.parse_int() {
            Some(v) => v,
            None => 0,
        },
        None => 0,
    };

    if n == 2 {
        if method == "POST" {
            let parsed = Json::parse(req.body());
            let mut title = "";
            let mut ok = false;
            match parsed {
                Ok(j) => {
                    if j.is_object() {
                        match j.get("title") {
                            Some(t) => match t.as_str() {
                                Some(s) => {
                                    let tr = s.trim();
                                    if tr.len() > 0 {
                                        title = tr;
                                        ok = true;
                                    }
                                }
                                None => {}
                            },
                            None => {}
                        }
                    }
                }
                Err(_) => {}
            }
            if !ok {
                return err(res, 400, "title required");
            }
            let id = next + 1;
            store.set("next", id.to_string());
            let t = todo_json(id, title, false);
            store.set("todo:" + id.to_string(), t.to_string());
            return reply(res, 201, t.to_string());
        }
        if method == "GET" {
            let filter = req.query("done");
            let mut out = Json::array();
            let mut i = 1;
            while i <= next {
                match load(store, i) {
                    Some(t) => {
                        let d = match t.get("done") {
                            Some(x) => match x.as_bool() {
                                Some(b) => b,
                                None => false,
                            },
                            None => false,
                        };
                        let include = match filter {
                            Some(f) => {
                                if f == "true" { d } else if f == "false" { !d } else { true }
                            }
                            None => true,
                        };
                        if include {
                            out.push(t);
                        }
                    }
                    None => {}
                }
                i = i + 1;
            }
            return reply(res, 200, out.to_string());
        }
        return err(res, 404, "not found");
    }

    // n == 3: /todos/ID
    let id = match parse_id(parts[2]) {
        Some(v) => v,
        None => return err(res, 404, "not found"),
    };
    let cur = match load(store, id) {
        Some(t) => t,
        None => return err(res, 404, "not found"),
    };

    if method == "GET" {
        return reply(res, 200, cur.to_string());
    }

    if method == "DELETE" {
        store.delete("todo:" + id.to_string());
        res.status(204);
        return "";
    }

    if method == "PATCH" {
        let mut new_title: Option<Str> = None;
        let mut new_done: Option<Bool> = None;
        let mut ok = false;
        match Json::parse(req.body()) {
            Ok(j) => {
                if j.is_object() {
                    ok = true;
                    match j.get("title") {
                        Some(t) => match t.as_str() {
                            Some(s) => {
                                let tr = s.trim();
                                if tr.len() > 0 {
                                    new_title = Some(tr);
                                } else {
                                    ok = false;
                                }
                            }
                            None => { ok = false; }
                        },
                        None => {}
                    }
                    match j.get("done") {
                        Some(d) => match d.as_bool() {
                            Some(b) => { new_done = Some(b); }
                            None => { ok = false; }
                        },
                        None => {}
                    }
                }
            }
            Err(_) => {}
        }
        if !ok {
            return err(res, 400, "bad update");
        }
        let old_title = match cur.get("title") {
            Some(t) => match t.as_str() {
                Some(s) => s,
                None => "",
            },
            None => "",
        };
        let old_done = match cur.get("done") {
            Some(d) => match d.as_bool() {
                Some(b) => b,
                None => false,
            },
            None => false,
        };
        let title = match new_title {
            Some(t) => t,
            None => old_title,
        };
        let done = match new_done {
            Some(d) => d,
            None => old_done,
        };
        let t = todo_json(id, title, done);
        store.set("todo:" + id.to_string(), t.to_string());
        return reply(res, 200, t.to_string());
    }

    err(res, 404, "not found")
}

// Todo JSON API in kio.
// Store layout: "next" -> last assigned id (as text);
// "todo:ID" -> "1" (exists); "title:ID" -> title; "done:ID" -> "1" or "0".

fn reply(res: Outgoing, code: Int, body: Str) -> Str {
    res.send(code, ["content-type"], ["application/json"], body);
    body
}

fn quote(s: Str) -> Str {
    Json::Str(s).to_str()
}

fn err(res: Outgoing, code: Int, msg: Str) -> Str {
    reply(res, code, "{\"error\":" + quote(msg) + "}")
}

fn todo_text(id: Int, title: Str, done: Bool) -> Str {
    let d = if done { "true" } else { "false" };
    "{\"id\":" + id.to_str() + ",\"title\":" + quote(title) + ",\"done\":" + d + "}"
}

fn parse_id(seg: Str) -> Option<Int> {
    match seg.parse_int() {
        Some(n) => {
            if n.to_str() == seg && n >= 1 { Some(n) } else { None }
        }
        None => None,
    }
}

fn exists(store: Kv, id: Int) -> Bool {
    match store.get("todo:" + id.to_str()) {
        Some(_) => true,
        None => false,
    }
}

fn get_title(store: Kv, id: Int) -> Str {
    match store.get("title:" + id.to_str()) {
        Some(s) => s,
        None => "",
    }
}

fn get_done(store: Kv, id: Int) -> Bool {
    match store.get("done:" + id.to_str()) {
        Some(s) => s == "1",
        None => false,
    }
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
    let method = req.method();
    let target = req.target();
    let tq = target.split("?");
    let path = tq[0];
    let query = if tq.len() > 1 { tq[1] } else { "" };
    let parts = path.split("/");
    // "/todos" -> ["", "todos"]; "/todos/5" -> ["", "todos", "5"]
    let n = parts.len();
    if n < 2 || n > 3 || parts[0] != "" || parts[1] != "todos" {
        return err(res, 404, "not found");
    }

    let next: Int = match store.get("next") {
        Some(s) => match s.parse_int() {
            Some(v) => v,
            None => 0,
        },
        None => 0,
    };

    if n == 2 {
        if method == "POST" {
            let parsed = Json::parse(req.body());
            let mut title = "";
            let mut ok = false;
            match parsed {
                Ok(j) => {
                    if j.is_object() {
                        match j.get("title") {
                            Some(t) => match t.as_str() {
                                Some(s) => {
                                    let tr = s.trim();
                                    if tr.len() > 0 {
                                        title = tr;
                                        ok = true;
                                    }
                                }
                                None => {}
                            },
                            None => {}
                        }
                    }
                }
                Err(_) => {}
            }
            if !ok {
                return err(res, 400, "title required");
            }
            let id = next + 1;
            store.set("next", id.to_str());
            store.set("todo:" + id.to_str(), "1");
            store.set("title:" + id.to_str(), title);
            store.set("done:" + id.to_str(), "0");
            return reply(res, 201, todo_text(id, title, false));
        }
        if method == "GET" {
            let mut out = "[";
            let mut first = true;
            let mut i = 1;
            while i <= next {
                if exists(store, i) {
                    let d = get_done(store, i);
                    let include = if query == "done=true" {
                        d
                    } else if query == "done=false" {
                        !d
                    } else {
                        true
                    };
                    if include {
                        if !first {
                            out = out + ",";
                        }
                        first = false;
                        out = out + todo_text(i, get_title(store, i), d);
                    }
                }
                i = i + 1;
            }
            out = out + "]";
            return reply(res, 200, out);
        }
        return err(res, 404, "not found");
    }

    // n == 3: /todos/ID
    let id = match parse_id(parts[2]) {
        Some(v) => v,
        None => return err(res, 404, "not found"),
    };
    if !exists(store, id) {
        return err(res, 404, "not found");
    }

    if method == "GET" {
        return reply(res, 200, todo_text(id, get_title(store, id), get_done(store, id)));
    }

    if method == "DELETE" {
        store.delete("todo:" + id.to_str());
        store.delete("title:" + id.to_str());
        store.delete("done:" + id.to_str());
        res.send(204, [], [], "");
        return "";
    }

    if method == "PATCH" {
        let mut new_title: Option<Str> = None;
        let mut new_done: Option<Bool> = None;
        let mut ok = false;
        match Json::parse(req.body()) {
            Ok(j) => {
                if j.is_object() {
                    ok = true;
                    match j.get("title") {
                        Some(t) => match t.as_str() {
                            Some(s) => {
                                let tr = s.trim();
                                if tr.len() > 0 {
                                    new_title = Some(tr);
                                } else {
                                    ok = false;
                                }
                            }
                            None => { ok = false; }
                        },
                        None => {}
                    }
                    match j.get("done") {
                        Some(d) => match d.as_bool() {
                            Some(b) => { new_done = Some(b); }
                            None => { ok = false; }
                        },
                        None => {}
                    }
                }
            }
            Err(_) => {}
        }
        if !ok {
            return err(res, 400, "bad update");
        }
        let title = match new_title {
            Some(t) => t,
            None => get_title(store, id),
        };
        let done = match new_done {
            Some(d) => d,
            None => get_done(store, id),
        };
        store.set("title:" + id.to_str(), title);
        store.set("done:" + id.to_str(), if done { "1" } else { "0" });
        return reply(res, 200, todo_text(id, title, done));
    }

    err(res, 404, "not found")
}

