    res.header("content-type", "application/json");
    res.send(body.clone());
    Ok(body)
}

fn not_found(res: Outgoing) -> Result<Str, Str> {
    respond(res, 404, "{\"error\": \"not found\"}")
}

fn all_digits(s: Str) -> Bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

fn tags_of(db: Db, id: Int) -> Json {
    let rows = db.query("SELECT tag FROM tags WHERE note_id = ? ORDER BY pos", [Json::int(id)]);
    let mut out = Json::array();
    for r in rows {
        out.push(Json::str(r.get_str("tag")));
    }
    out
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)", []);
    db.exec("CREATE TABLE IF NOT EXISTS tags (note_id INTEGER NOT NULL, pos INTEGER NOT NULL, tag TEXT NOT NULL)", []);

    let method = req.method();
    let path = req.path();
    let parts: Vec<Str> = path.split("/").filter(|p| p.len() > 0).collect();

    if parts.len() == 0 || parts[0] != "notes" || parts.len() > 2 {
        return not_found(res);
    }

    if parts.len() == 1 {
        if method == "POST" {
            let parsed = Json::parse(req.body());
            if parsed.is_err() {
                return respond(res, 400, "{\"error\": \"invalid note\"}");
            }
            let j = parsed.unwrap();
            if !j.is_object() {
                return respond(res, 400, "{\"error\": \"invalid note\"}");
            }
            let title = j.get("title");
            let body = j.get("body");
            let tags = j.get("tags");
            if !title.is_str() || title.as_str().len() == 0 || !body.is_str() {
                return respond(res, 400, "{\"error\": \"invalid note\"}");
            }
            let mut clean: Vec<Str> = Vec::new();
            if !tags.is_null() {
                if !tags.is_array() {
                    return respond(res, 400, "{\"error\": \"invalid note\"}");
                }
                for t in tags.items() {
                    if !t.is_str() {
                        return respond(res, 400, "{\"error\": \"invalid note\"}");
                    }
                    let low = t.as_str().to_lowercase();
                    if !clean.contains(&low) {
                        clean.push(low);
                    }
                }
            }
            db.exec("INSERT INTO notes (title, body) VALUES (?, ?)", [Json::str(title.as_str()), Json::str(body.as_str())]);
            let id = db.query("SELECT last_insert_rowid() AS id", [])[0].get_int("id");
            let mut pos = 0;
            for t in clean {
                db.exec("INSERT INTO tags (note_id, pos, tag) VALUES (?, ?, ?)", [Json::int(id), Json::int(pos), Json::str(t)]);
                pos += 1;
            }
            return respond(res, 201, "{\"id\": " + id.to_string() + "}");
        }
        if method == "GET" {
            let mut sql = "SELECT id, title FROM notes WHERE 1 = 1".to_string();
            let mut args: Vec<Json> = Vec::new();
            let tag = req.query("tag");
            if tag.is_some() {
                sql = sql + " AND id IN (SELECT note_id FROM tags WHERE tag = ?)";
                args.push(Json::str(tag.unwrap().to_lowercase()));
            }
            let q = req.query("q");
            if q.is_some() {
                sql = sql + " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
                let w = q.unwrap();
                args.push(Json::str(w.clone()));
                args.push(Json::str(w));
            }
            sql = sql + " ORDER BY id DESC";
            let rows = db.query(sql, args);
            let mut out = Json::array();
            for r in rows {
                let mut o = Json::object();
                o.set("id", Json::int(r.get_int("id")));
                o.set("title", Json::str(r.get_str("title")));
                out.push(o);
            }
            return respond(res, 200, out.to_string());
        }
        return not_found(res);
    }

    if !all_digits(parts[1].clone()) {
        return not_found(res);
    }
    let id = parts[1].parse_int().unwrap();
    let rows = db.query("SELECT id, title, body FROM notes WHERE id = ?", [Json::int(id)]);
    if rows.len() == 0 {
        return not_found(res);
    }

    if method == "GET" {
        let r = rows[0].clone();
