        return not_found(res);
    }

    if !is_num(parts[1]) {
        return not_found(res);
    }
    let id = parts[1].parse_int().unwrap_or(0);
    let rows = db.query("SELECT id, title, body FROM notes WHERE id = ?", [SqlValue::Int(id)]).unwrap();
    if rows.len() == 0 {
        return not_found(res);
    }

    if method == "GET" {
        let r = rows[0];
        let o = "{\"id\": " + id.to_string() + ", \"title\": \"" + esc(as_str(r[1])) + "\", \"body\": \"" + esc(as_str(r[2])) + "\", \"tags\": " + tags_json(db, id) + "}";
        return respond(res, 200, o);
    }
    if method == "DELETE" {
        let _ = db.exec("DELETE FROM tags WHERE note_id = ?", [SqlValue::Int(id)]);
        let _ = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)]);
        return respond(res, 200, "{\"deleted\": " + id.to_string() + "}");
    }
    not_found(res)
}

