    for s in list {
        items.push((s["name"].as_str(), s["id"].as_str()));
    }

    // Insertion sort by name (byte order)
    let mut i = 1;
    while i < items.len() {
        let mut j = i;
        while j > 0 && items[j - 1].0 > items[j].0 {
            let tmp = items[j - 1].clone();
            items[j - 1] = items[j].clone();
            items[j] = tmp;
            j = j - 1;
