    let mut largest_cents: i64 = -1;
    let mut more = true;

    while more {
        let resp = api.get(format!("/orders?page={}", page))?;
        let body = resp.json()?;
        for o in body["orders"].as_array()? {
            count += 1;
            let status = o["status"].as_str()?;
            let id = o["id"].as_i64()?;
            let cents = o["cents"].as_i64()?;
            let cur = o["currency"].as_str()?;
            if status == "refunded" {
                refunded += 1;
            }
            if status == "paid" {
                if cur == "EUR" {
                    eur += cents;
                    has_eur = true;
                } else if cur == "USD" {
                    usd += cents;
                    has_usd = true;
                }
                if cents > largest_cents || (cents == largest_cents && id < largest_id) {
                    largest_cents = cents;
                    largest_id = id;
                }
            }
        }
        let next = body["next"];
        if next.is_null() {
            more = false;
        } else {
            page = next.as_i64()?;
        }
    }

    let mut paid = String::new();
    if has_eur {
        paid.push_str(&format!("\"EUR\": {}", eur));
    }
    if has_usd {
        if has_eur {
            paid.push_str(", ");
        }
        paid.push_str(&format!("\"USD\": {}", usd));
    }

    let payload = format!(
        "{{\"orders\": {}, \"paid_cents\": {{{}}}, \"refunded\": {}, \"largest\": {}}}",
        count, paid, refunded, largest_id
    );

