        }
    }

    let mut paid = "";
    if has_eur {
        paid = paid + "\"EUR\": " + eur.to_str();
    }
    if has_usd {
        if has_eur {
            paid = paid + ", ";
        }
        paid = paid + "\"USD\": " + usd.to_str();
    }

    let payload = "{\"orders\": " + count.to_str()
        + ", \"paid_cents\": {" + paid
        + "}, \"refunded\": " + refunded.to_str()
        + ", \"largest\": " + largest_id.to_str() + "}";

    let headers = [Header { name: "content-type", value: "application/json" }];
    let r = api.post("/summaries", payload, headers)?;
    if r.status() != 201 {
        return Err("unexpected status " + r.status().to_str());
