}

fn parse_state(s: Str) -> Vec<(Str, Str)> {
    // MRU last. Each line: "key value"
    let mut out: Vec<(Str, Str)> = Vec::new();
    for line in s.split("\n") {
        if line.len() == 0 {
            continue;
        }
        match line.find(" ") {
            Some(i) => {
                out.push((line[0..i].to_string(), line[i + 1..].to_string()));
            }
            None => {}
        }
    }
    out
}

fn pos_of(items: &Vec<(Str, Str)>, key: &Str) -> Option<usize> {
    let mut i = 0;
    while i < items.len() {
        if items[i].0 == *key {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
    let text = input.read("ops.txt")?;
    let mut items: Vec<(Str, Str)> = match cache.get("state") {
        Some(s) => parse_state(s),
        None => Vec::new(),
    };
    let mut hits: i64 = 0;
    let mut misses: i64 = 0;
    let mut evictions: i64 = 0;
    match cache.get("stats") {
        Some(s) => {
            let parts: Vec<Str> = s.split(" ").collect();
            if parts.len() == 3 {
                hits = parts[0].parse::<i64>().unwrap_or(0);
                misses = parts[1].parse::<i64>().unwrap_or(0);
                evictions = parts[2].parse::<i64>().unwrap_or(0);
            }
        }
        None => {}
    }

    let mut out = String::new();
    let lines: Vec<Str> = text.split("\n").collect();
    let mut cap: usize = 1;
    if lines.len() > 0 {
        let first = lines[0].trim_end_matches("\r");
        let w: Vec<Str> = first.split(" ").collect();
        if w.len() == 2 && w[0] == "capacity" {
            cap = w[1].parse::<usize>().unwrap_or(1);
            if cap < 1 {
                cap = 1;
            }
        }
    }

    while items.len() > cap {
        let e = items.remove(0);
        evictions += 1;
        out.push_str("evict ");
        out.push_str(&e.0);
        out.push_str("\n");
    }

    let mut n = 1;
    while n < lines.len() {
        let line = lines[n].trim_end_matches("\r");
        let lineno = n + 1;
        n += 1;
        if line.trim().len() == 0 {
            continue;
        }
        let w: Vec<Str> = line.split(" ").collect();
        let op = w[0].clone();
        let mut ok = false;
        if op == "get" && w.len() == 2 && w[1].len() > 0 {
            ok = true;
            let key = w[1].clone();
            match pos_of(&items, &key) {
                Some(i) => {
                    let it = items.remove(i);
                    hits += 1;
                    out.push_str(&key);
                    out.push_str("=");
                    out.push_str(&it.1);
                    out.push_str("\n");
                    items.push(it);
                }
                None => {
                    misses += 1;
                    out.push_str(&key);
                    out.push_str(" miss\n");
                }
            }
        } else if op == "del" && w.len() == 2 && w[1].len() > 0 {
            ok = true;
            let key = w[1].clone();
            match pos_of(&items, &key) {
                Some(i) => {
                    items.remove(i);
                }
                None => {}
            }
        } else if op == "put" && w.len() >= 3 && w[1].len() > 0 {
            let key = w[1].clone();
            let prefix_len = 4 + key.len() + 1;
            if line.len() > prefix_len {
                let value = line[prefix_len..].to_string();
                if value.len() > 0 {
                    ok = true;
                    match pos_of(&items, &key) {
                        Some(i) => {
                            items.remove(i);
                        }
                        None => {
                            if items.len() >= cap {
                                let e = items.remove(0);
                                evictions += 1;
                                out.push_str("evict ");
                                out.push_str(&e.0);
                                out.push_str("\n");
                            }
                        }
                    }
                    items.push((key, value));
                }
            }
        }
        if !ok {
            out.push_str("bad line ");
            out.push_str(&lineno.to_string());
            out.push_str("\n");
        }
    }

    // persist
    let mut state = String::new();
    for it in items.iter() {
        state.push_str(&it.0);
        state.push_str(" ");
        state.push_str(&it.1);
        state.push_str("\n");
    }
    cache.set("state", &state)?;
    let stats = format!("{} {} {}", hits, misses, evictions);
    cache.set("stats", &stats)?;

    out.push_str("cache:");
    let mut k = items.len();
    let mut first = true;
    while k > 0 {
        k -= 1;
        if first {
            out.push_str(" ");
            first = false;
        } else {
            out.push_str(",");
        }
        out.push_str(&items[k].0);
    }
    out.push_str("\n");
    out.push_str(&format!("stats hits {} misses {} evictions {}", hits, misses, evictions));
    Ok(out)
}

