    while items.len() > cap {
        let e = items.remove(0);
        evictions += 1;
        out.push_str("evict ");
        out.push_str(e.key);
        out.push_str("\n");
    }

    let mut n = 1;
    while n < lines.len() {
        let line = lines[n].trim_end_matches("\r");
        let lineno = n + 1;
        n += 1;
        if line.len() == 0 {
            continue;
        }
        let w: Vec<Str> = line.split(" ").collect();
        let op = w[0].clone();
        let mut ok = false;
        if op == "get" && w.len() == 2 && w[1].len() > 0 {
            ok = true;
            let key = w[1].clone();
            match pos_of(items.clone(), key.clone()) {
                Some(i) => {
                    let it = items.remove(i);
                    hits += 1;
                    out.push_str(key);
                    out.push_str("=");
                    out.push_str(it.val.clone());
                    out.push_str("\n");
                    items.push(it);
                }
                None => {
                    misses += 1;
                    out.push_str(key);
                    out.push_str(" miss\n");
                }
            }
        } else if op == "del" && w.len() == 2 && w[1].len() > 0 {
            ok = true;
            let key = w[1].clone();
            match pos_of(items.clone(), key) {
                Some(i) => {
                    items.remove(i);
                }
                None => {}
            }
        } else if op == "put" && w.len() >= 3 && w[1].len() > 0 {
            let key = w[1].clone();
            let value = join_from(w.clone(), 2);
            if value.len() > 0 {
                ok = true;
                match pos_of(items.clone(), key.clone()) {
                    Some(i) => {
                        items.remove(i);
                    }
                    None => {
                        if items.len() >= cap {
                            let e = items.remove(0);
                            evictions += 1;
                            out.push_str("evict ");
                            out.push_str(e.key);
                            out.push_str("\n");
                        }
                    }
                }
                items.push(Item { key: key, val: value });
            }
        }
        if !ok {
            out.push_str("bad line ");
            out.push_str(lineno.to_string());
            out.push_str("\n");
        }
    }

    let mut state = String::new();
    for it in items.clone() {
        state.push_str(it.key);
        state.push_str(" ");
        state.push_str(it.val);
        state.push_str("\n");
    }
    cache.set("state", state)?;
    let stats = format!("{} {} {}", hits, misses, evictions);
    cache.set("stats", stats)?;

    out.push_str("cache:");
    let mut k = items.len();
    let mut is_first = true;
    while k > 0 {
        k -= 1;
        if is_first {
            out.push_str(" ");
            is_first = false;
        } else {
            out.push_str(",");
        }
        out.push_str(items[k].key.clone());
    }
    out.push_str("\n");
    out.push_str(format!("stats hits {} misses {} evictions {}", hits, misses, evictions));
    Ok(out)
}

enum Json {
    Obj(Vec<(String, Json)>),
    Arr(Vec<Json>),
    Text(String),
    Other,
}

struct P {
    b: Vec<u8>,
    i: usize,
    ok: bool,
}

fn ws(p: &mut P) {
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 10 || c == 13 || c == 9 {
            p.i += 1;
        } else {
            break;
        }
    }
}

fn hexv(c: u8) -> u32 {
    if c >= 48 && c <= 57 {
        (c - 48) as u32
    } else if c >= 97 && c <= 102 {
        (c - 97) as u32 + 10
    } else if c >= 65 && c <= 70 {
        (c - 65) as u32 + 10
    } else {
        0
    }
}

fn parse_str(p: &mut P) -> String {
    let mut out: Vec<u8> = Vec::new();
    p.i += 1;
    loop {
        if p.i >= p.b.len() {
            p.ok = false;
            break;
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        }
        if c == 92 {
            if p.i >= p.b.len() {
                p.ok = false;
                break;
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 110 {
                out.push(10);
            } else if e == 116 {
                out.push(9);
            } else if e == 114 {
                out.push(13);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 117 {
                let mut v: u32 = 0;
                let mut k = 0;
                while k < 4 && p.i < p.b.len() {
                    v = v * 16 + hexv(p.b[p.i]);
                    p.i += 1;
                    k += 1;
                }
                let ch = char::from_u32(v).unwrap_or('?');
                let mut s = String::new();
                s.push(ch);
                for x in s.as_bytes() {
                    out.push(*x);
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
        }
    }
    String::from_utf8_lossy(&out).to_string()
}

fn parse_val(p: &mut P) -> Json {
    ws(p);
    if p.i >= p.b.len() {
        p.ok = false;
        return Json::Other;
    }
    let c = p.b[p.i];
    if c == 123 {
        p.i += 1;
        let mut items: Vec<(String, Json)> = Vec::new();
        ws(p);
        if p.i < p.b.len() && p.b[p.i] == 125 {
            p.i += 1;
            return Json::Obj(items);
        }
        loop {
            ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 34 {
                p.ok = false;
                return Json::Other;
            }
            let k = parse_str(p);
            ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 58 {
                p.ok = false;
                return Json::Other;
            }
            p.i += 1;
            let v = parse_val(p);
            if !p.ok {
                return Json::Other;
            }
            items.push((k, v));
            ws(p);
            if p.i >= p.b.len() {
                p.ok = false;
                return Json::Other;
            }
            let d = p.b[p.i];
            p.i += 1;
            if d == 44 {
                continue;
            } else if d == 125 {
                break;
            } else {
                p.ok = false;
                return Json::Other;
            }
        }
        Json::Obj(items)
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return Json::Arr(items);
        }
        loop {
            let v = parse_val(p);
            if !p.ok {
                return Json::Other;
            }
            items.push(v);
            ws(p);
            if p.i >= p.b.len() {
                p.ok = false;
                return Json::Other;
            }
            let d = p.b[p.i];
            p.i += 1;
            if d == 44 {
                continue;
            } else if d == 93 {
                break;
            } else {
                p.ok = false;
                return Json::Other;
            }
        }
        Json::Arr(items)
    } else if c == 34 {
        Json::Text(parse_str(p))
    } else {
        let start = p.i;
        while p.i < p.b.len() {
            let d = p.b[p.i];
            if d == 44 || d == 93 || d == 125 || d == 32 || d == 10 || d == 13 || d == 9 {
                break;
            }
            p.i += 1;
        }
        if p.i == start {
            p.ok = false;
        } else {
            let t = String::from_utf8_lossy(&p.b[start..p.i]).to_string();
            let good = t == "true" || t == "false" || t == "null" || t.parse::<f64>().is_ok();
            if !good {
                p.ok = false;
            }
        }
        Json::Other
    }
}

struct G {
    adj: Vec<Vec<usize>>,
    index: Vec<i64>,
    low: Vec<i64>,
    on: Vec<bool>,
    stack: Vec<usize>,
    counter: i64,
    comps: Vec<Vec<usize>>,
}

fn strong(g: &mut G, v: usize) {
    g.index[v] = g.counter;
    g.low[v] = g.counter;
    g.counter += 1;
    g.stack.push(v);
    g.on[v] = true;
    let nbrs = g.adj[v].clone();
    for w in nbrs {
        if g.index[w] < 0 {
            strong(g, w);
            if g.low[w] < g.low[v] {
                g.low[v] = g.low[w];
            }
        } else if g.on[w] {
            if g.index[w] < g.low[v] {
                g.low[v] = g.index[w];
            }
        }
    }
    if g.low[v] == g.index[v] {
        let mut comp: Vec<usize> = Vec::new();
        loop {
            let w = g.stack.pop().unwrap();
            g.on[w] = false;
            comp.push(w);
            if w == v {
                break;
            }
        }
        g.comps.push(comp);
    }
}

fn stage_of(
    v: usize,
    adj: &Vec<Vec<usize>>,
    bad: &Vec<bool>,
    memo: &mut Vec<i64>,
) -> i64 {
    // memo: -2 unknown, -1 not built, >=1 stage
    if memo[v] != -2 {
        return memo[v];
    }
    if bad[v] {
        memo[v] = -1;
        return -1;
    }
    let mut best: i64 = 1;
    let mut ok = true;
    for &w in adj[v].iter() {
        let s = stage_of(w, adj, bad, memo);
        if s < 0 {
            ok = false;
        } else if s + 1 > best {
            best = s + 1;
        }
    }
    let r = if ok { best } else { -1 };
    memo[v] = r;
    r
}

fn join(v: &Vec<String>) -> String {
    let mut s = String::new();
    let mut first = true;
    for x in v.iter() {
        if !first {
            s.push_str(", ");
        }
        first = false;
        s.push_str(x);
    }
    s
}

fn main(input: Dir) -> Str {
    let text = input.read_text("packages.json").unwrap_or(String::new());
    let mut p = P { b: text.as_bytes().to_vec(), i: 0, ok: true };
    let root = parse_val(&mut p);
    ws(&mut p);
    if !p.ok || p.i < p.b.len() {
        return "error: not an object".to_string();
    }
    let items = match root {
        Json::Obj(items) => items,
        _ => {
            return "error: not an object".to_string();
        }
    };
    // last duplicate key wins
    let mut valid: std::collections::BTreeMap<String, Vec<String>> =
        std::collections::BTreeMap::new();
    let mut invalid: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for (k, v) in items {
        let mut deps: Vec<String> = Vec::new();
        let mut good = false;
        if let Json::Arr(a) = v {
            good = true;
            for e in a {
                match e {
                    Json::Text(t) => deps.push(t),
                    _ => {
                        good = false;
                    }
                }
            }
        }
        if good {
            invalid.remove(&k);
            deps.sort();
            deps.dedup();
            valid.insert(k, deps);
        } else {
            valid.remove(&k);
            invalid.insert(k);
        }
    }
    let names: Vec<String> = valid.keys().cloned().collect();
    let n = names.len();
    let mut idx: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for (i, nm) in names.iter().enumerate() {
        idx.insert(nm.clone(), i);
    }
    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing: std::collections::BTreeMap<String, Vec<String>> =
        std::collections::BTreeMap::new();
    for nm in names.iter() {
        let mut a: Vec<usize> = Vec::new();
        let mut hm = false;
        for d in valid.get(nm).unwrap().iter() {
            match idx.get(d) {
                Some(&j) => a.push(j),
                None => {
                    hm = true;
                    missing.entry(d.clone()).or_insert(Vec::new()).push(nm.clone());
                }
            }
        }
        adj.push(a);
        has_missing.push(hm);
    }
    let mut g = G {
        adj: adj.clone(),
        index: vec![-1; n],
        low: vec![0; n],
        on: vec![false; n],
        stack: Vec::new(),
        counter: 0,
        comps: Vec::new(),
    };
    for v in 0..n {
        if g.index[v] < 0 {
            strong(&mut g, v);
        }
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut groups: Vec<Vec<String>> = Vec::new();
    for comp in g.comps.iter() {
        let cyc = if comp.len() >= 2 {
            true
        } else {
            let v = comp[0];
            adj[v].contains(&v)
        };
        if cyc {
            let mut names_c: Vec<String> = Vec::new();
            for &v in comp.iter() {
                in_cycle[v] = true;
                names_c.push(names[v].clone());
            }
            names_c.sort();
            groups.push(names_c);
        }
    }
    groups.sort();
    let mut bad: Vec<bool> = vec![false; n];
    for v in 0..n {
        bad[v] = in_cycle[v] || has_missing[v];
    }
    let mut memo: Vec<i64> = vec![-2; n];
    let mut stages: Vec<i64> = vec![-1; n];
    let mut maxs: i64 = 0;
    for v in 0..n {
        let s = stage_of(v, &adj, &bad, &mut memo);
        stages[v] = s;
        if s > maxs {
            maxs = s;
        }
    }
    let mut out = String::new();
    let mut built = 0;
    for s in 1..=maxs {
        let mut ps: Vec<String> = Vec::new();
        for v in 0..n {
            if stages[v] == s {
                ps.push(names[v].clone());
            }
        }
        if !ps.is_empty() {
            built += ps.len();
            out.push_str(&format!("stage {}: {}\n", s, join(&ps)));
        }
    }
    for gr in groups.iter() {
        out.push_str(&format!("cycle: {}\n", join(gr)));
    }
    for (m, by) in missing.iter() {
        let mut b = by.clone();
        b.sort();
        out.push_str(&format!("missing: {} (needed by {})\n", m, join(&b)));
    }
    if !invalid.is_empty() {
        let v: Vec<String> = invalid.iter().cloned().collect();
        out.push_str(&format!("invalid: {}\n", join(&v)));
    }
    let mut blocked: Vec<String> = Vec::new();
    for v in 0..n {
        if stages[v] < 0 && !in_cycle[v] {
            blocked.push(names[v].clone());
        }
    }
    if !blocked.is_empty() {
        out.push_str(&format!("blocked: {}\n", join(&blocked)));
    }
    out.push_str(&format!("built {} of {}", built, n));
    out
}

