struct S {
    adj: Vec<Vec<usize>>,
    bad: Vec<bool>,
    memo: Vec<i64>,
}

fn stage_of(mut st: S, v: usize) -> (i64, S) {
    if st.memo[v] != -2 {
        let r = st.memo[v];
        return (r, st);
    }
    if st.bad[v] {
        st.memo[v] = -1;
        return (-1, st);
    }
    let mut best: i64 = 1;
    let mut ok = true;
    let nb = st.adj[v].clone();
    for w in nb {
        let rr = stage_of(st, w);
        let s = rr.0;
        st = rr.1;
        if s < 0 {
            ok = false;
        } else if s + 1 > best {
            best = s + 1;
        }
    }
    let r = if ok { best } else { -1 };
    st.memo[v] = r;
    (r, st)
}

