enum Json {
    Obj(Vec<Entry>),
    Arr(Vec<Json>),
    Text(Str),
    Other,
}

struct Entry {
    key: Str,
    val: Json,
}

struct P {
    b: Vec<u8>,
    i: usize,
    ok: bool,
}

struct StrR {
    s: Str,
    p: P,
}

struct ValR {
    v: Json,
    p: P,
}

fn ws(mut p: P) -> P {
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 10 || c == 13 || c == 9 {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexv(c: u8) -> u32 {
    if c >= 48 && c <= 57 {
        (c - 48) as u32
    } else if c >= 97 && c <= 102 {
        (c - 97) as u32 + 10
    } else if c >= 65 && c <= 70 {
        (c - 65) as u32 + 10
    } else {
        0
    }
}

fn parse_str(mut p: P) -> StrR {
    let mut out: Vec<u8> = Vec::new();
    p.i += 1;
    loop {
        if p.i >= p.b.len() {
            p.ok = false;
            break;
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        }
        if c == 92 {
            if p.i >= p.b.len() {
                p.ok = false;
                break;
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 110 {
                out.push(10);
            } else if e == 116 {
                out.push(9);
            } else if e == 114 {
                out.push(13);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 117 {
                let mut v: u32 = 0;
                let mut k = 0;
                while k < 4 && p.i < p.b.len() {
                    v = v * 16 + hexv(p.b[p.i]);
                    p.i += 1;
                    k += 1;
                }
                if v < 128 {
                    out.push(v as u8);
                } else if v < 2048 {
                    out.push((192 + v / 64) as u8);
                    out.push((128 + v % 64) as u8);
                } else {
                    out.push((224 + v / 4096) as u8);
                    out.push((128 + (v / 64) % 64) as u8);
                    out.push((128 + v % 64) as u8);
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
        }
    }
    let s = Str::from_utf8_lossy(out).to_string();
    StrR { s: s, p: p }
}

fn parse_val(mut p: P) -> ValR {
    p = ws(p);
    if p.i >= p.b.len() {
        p.ok = false;
        return ValR { v: Json::Other, p: p };
    }
    let c = p.b[p.i];
    if c == 123 {
        p.i += 1;
        let mut items: Vec<Entry> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 125 {
            p.i += 1;
            return ValR { v: Json::Obj(items), p: p };
        }
        loop {
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 34 {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
            let kr = parse_str(p);
            let k = kr.s;
            p = kr.p;
            p = ws(p);
            if p.i >= p.b.len() || p.b[p.i] != 58 {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
            p.i += 1;
            let vr = parse_val(p);
            let v = vr.v;
            p = vr.p;
            if !p.ok {
                return ValR { v: Json::Other, p: p };
            }
            items.push(Entry { key: k, val: v });
            p = ws(p);
            if p.i >= p.b.len() {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
            let d = p.b[p.i];
            p.i += 1;
            if d == 44 {
                continue;
            } else if d == 125 {
                break;
            } else {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
        }
        ValR { v: Json::Obj(items), p: p }
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return ValR { v: Json::Arr(items), p: p };
        }
        loop {
            let vr = parse_val(p);
            let v = vr.v;
            p = vr.p;
            if !p.ok {
                return ValR { v: Json::Other, p: p };
            }
            items.push(v);
            p = ws(p);
            if p.i >= p.b.len() {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
            let d = p.b[p.i];
            p.i += 1;
            if d == 44 {
                continue;
            } else if d == 93 {
                break;
            } else {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
        }
        ValR { v: Json::Arr(items), p: p }
    } else if c == 34 {
        let sr = parse_str(p);
        ValR { v: Json::Text(sr.s), p: sr.p }
    } else {
        let start = p.i;
        while p.i < p.b.len() {
            let d = p.b[p.i];
            if d == 44 || d == 93 || d == 125 || d == 32 || d == 10 || d == 13 || d == 9 {
                break;
            }
            p.i += 1;
        }
        if p.i == start {
            p.ok = false;
        } else {
            let mut tb: Vec<u8> = Vec::new();
            let mut k = start;
            while k < p.i {
                tb.push(p.b[k]);
                k += 1;
            }
            let t = Str::from_utf8_lossy(tb).to_string();
            let good = t == "true" || t == "false" || t == "null" || t.parse::<f64>().is_ok();
            if !good {
                p.ok = false;
            }
        }
        ValR { v: Json::Other, p: p }
    }
}

struct G {
    adj: Vec<Vec<usize>>,
    index: Vec<i64>,
    low: Vec<i64>,
    on: Vec<bool>,
    stack: Vec<usize>,
    counter: i64,
    comps: Vec<Vec<usize>>,
}

fn strong(mut g: G, v: usize) -> G {
    g.index[v] = g.counter;
    g.low[v] = g.counter;
    g.counter += 1;
    g.stack.push(v);
    g.on[v] = true;
    let nbrs = g.adj[v].clone();
    for w in nbrs {
        if g.index[w] < 0 {
            g = strong(g, w);
            if g.low[w] < g.low[v] {
                g.low[v] = g.low[w];
            }
        } else if g.on[w] {
            if g.index[w] < g.low[v] {
                g.low[v] = g.index[w];
            }
        }
    }
    if g.low[v] == g.index[v] {
        let mut comp: Vec<usize> = Vec::new();
        loop {
            let w = g.stack.pop().unwrap();
            g.on[w] = false;
            comp.push(w);
            if w == v {
                break;
            }
        }
        g.comps.push(comp);
    }
    g
}

struct S {
    adj: Vec<Vec<usize>>,
    bad: Vec<bool>,
    memo: Vec<i64>,
}

struct StageR {
    n: i64,
    st: S,
}

fn stage_of(mut st: S, v: usize) -> StageR {
    if st.memo[v] != -2 {
        let r = st.memo[v];
        return StageR { n: r, st: st };
    }
    if st.bad[v] {
        st.memo[v] = -1;
        return StageR { n: -1, st: st };
    }
    let mut best: i64 = 1;
    let mut ok = true;
    let nb = st.adj[v].clone();
    for w in nb {
        let rr = stage_of(st, w);
        let s = rr.n;
        st = rr.st;
        if s < 0 {
            ok = false;
        } else if s + 1 > best {
            best = s + 1;
        }
    }
    let r = if ok { best } else { -1 };
    st.memo[v] = r;
    StageR { n: r, st: st }
}

fn join(v: Vec<Str>) -> Str {
    let mut s = Str::new();
    let mut first = true;
    for x in v {
        if !first {
            s.push_str(", ");
        }
        first = false;
        s.push_str(x);
    }
    s
}

fn main(input: Dir) -> Str {
    let text = input.read_text("packages.json").unwrap_or(Str::new());
    let p0 = P { b: text.as_bytes().to_vec(), i: 0, ok: true };
    let pr = parse_val(p0);
    let root = pr.v;
    let p = ws(pr.p);
    if !p.ok || p.i < p.b.len() {
        return "error: not an object".to_string();
    }
    let items = match root {
        Json::Obj(items) => items,
        _ => {
            return "error: not an object".to_string();
        }
    };
    let mut valid: std::collections::BTreeMap<Str, Vec<Str>> =
        std::collections::BTreeMap::new();
    let mut invalid: std::collections::BTreeSet<Str> = std::collections::BTreeSet::new();
    for e0 in items {
        let k = e0.key;
        let v = e0.val;
        let mut deps: Vec<Str> = Vec::new();
        let mut good = false;
        if let Json::Arr(a) = v {
            good = true;
            for e in a {
                match e {
                    Json::Text(t) => deps.push(t),
                    _ => {
                        good = false;
                    }
                }
            }
        }
        if good {
            invalid.remove(k.clone());
            deps.sort();
            deps.dedup();
            valid.insert(k, deps);
        } else {
            valid.remove(k.clone());
            invalid.insert(k);
        }
    }
    let names: Vec<Str> = valid.keys().cloned().collect();
    let n = names.len();
    let mut idx: std::collections::BTreeMap<Str, usize> = std::collections::BTreeMap::new();
    for i in 0..n {
        idx.insert(names[i].clone(), i);
    }
    let mut adj: Vec<Vec<usize>> = Vec::new();
    let mut has_missing: Vec<bool> = Vec::new();
    let mut missing: std::collections::BTreeMap<Str, Vec<Str>> =
        std::collections::BTreeMap::new();
    for i in 0..n {
        let nm = names[i].clone();
        let mut a: Vec<usize> = Vec::new();
        let mut hm = false;
        let ds = valid.get(nm.clone()).unwrap().clone();
        for d in ds {
            match idx.get(d.clone()) {
                Some(j) => a.push(j),
                None => {
                    hm = true;
                    let mut cur = match missing.get(d.clone()) {
                        Some(x) => x.clone(),
                        None => Vec::new(),
                    };
                    cur.push(nm.clone());
                    missing.insert(d.clone(), cur);
                }
            }
        }
        adj.push(a);
        has_missing.push(hm);
    }
    let mut g = G {
        adj: adj.clone(),
        index: vec![-1; n],
        low: vec![0; n],
        on: vec![false; n],
        stack: Vec::new(),
        counter: 0,
        comps: Vec::new(),
    };
    for v in 0..n {
        if g.index[v] < 0 {
            g = strong(g, v);
        }
    }
    let mut in_cycle: Vec<bool> = vec![false; n];
    let mut groups: Vec<Vec<Str>> = Vec::new();
    for comp in g.comps.clone() {
        let mut cyc = false;
        if comp.len() >= 2 {
            cyc = true;
        } else {
            let v = comp[0];
            for w in adj[v].clone() {
                if w == v {
                    cyc = true;
                }
            }
        }
        if cyc {
            let mut names_c: Vec<Str> = Vec::new();
            for v in comp {
                in_cycle[v] = true;
                names_c.push(names[v].clone());
            }
            names_c.sort();
            groups.push(names_c);
        }
    }
    groups.sort();
    let mut bad: Vec<bool> = vec![false; n];
    for v in 0..n {
        bad[v] = in_cycle[v] || has_missing[v];
    }
    let mut st = S { adj: adj.clone(), bad: bad, memo: vec![-2; n] };
    let mut stages: Vec<i64> = vec![-1; n];
    let mut maxs: i64 = 0;
    for v in 0..n {
        let rr = stage_of(st, v);
        let s = rr.n;
        st = rr.st;
        stages[v] = s;
        if s > maxs {
            maxs = s;
        }
    }
    let mut out = Str::new();
    let mut built = 0;
    for s in 1..=maxs {
        let mut ps: Vec<Str> = Vec::new();
        for v in 0..n {
            if stages[v] == s {
                ps.push(names[v].clone());
            }
        }
        if !ps.is_empty() {
            built += ps.len();
            out.push_str(format!("stage {}: {}\n", s, join(ps)));
        }
    }
    for gr in groups {
        out.push_str(format!("cycle: {}\n", join(gr)));
    }
    let mkeys: Vec<Str> = missing.keys().cloned().collect();
    for m in mkeys {
        let mut b = missing.get(m.clone()).unwrap().clone();
        b.sort();
        out.push_str(format!("missing: {} (needed by {})\n", m, join(b)));
    }
    if !invalid.is_empty() {
        let v: Vec<Str> = invalid.iter().cloned().collect();
        out.push_str(format!("invalid: {}\n", join(v)));
    }
    let mut blocked: Vec<Str> = Vec::new();
    for v in 0..n {
        if stages[v] < 0 && !in_cycle[v] {
            blocked.push(names[v].clone());
        }
    }
    if !blocked.is_empty() {
        out.push_str(format!("blocked: {}\n", join(blocked)));
    }
    out.push_str(format!("built {} of {}", built, n));
    out
}

enum Json {
    Obj(Vec<Entry>),
    Arr(Vec<Json>),
    Text(Str),
    Other,
}

struct Entry {
    key: Str,
    val: Json,
}

struct P {
    b: Vec<u8>,
    i: usize,
    ok: bool,
}

struct StrR {
    s: Str,
    p: P,
}

struct ValR {
    v: Json,
    p: P,
}

fn ws(p0: P) -> P {
    let mut p = p0;
    while p.i < p.b.len() {
        let c = p.b[p.i];
        if c == 32 || c == 10 || c == 13 || c == 9 {
            p.i += 1;
        } else {
            break;
        }
    }
    p
}

fn hexv(c: u8) -> u32 {
    if c >= 48 && c <= 57 {
        (c - 48) as u32
    } else if c >= 97 && c <= 102 {
        (c - 97) as u32 + 10
    } else if c >= 65 && c <= 70 {
        (c - 65) as u32 + 10
    } else {
        0
    }
}

fn parse_str(p0: P) -> StrR {
    let mut p = p0;
    let mut out: Vec<u8> = Vec::new();
    p.i += 1;
    loop {
        if p.i >= p.b.len() {
            p.ok = false;
            break;
        }
        let c = p.b[p.i];
        p.i += 1;
        if c == 34 {
            break;
        }
        if c == 92 {
            if p.i >= p.b.len() {
                p.ok = false;
                break;
            }
            let e = p.b[p.i];
            p.i += 1;
            if e == 110 {
                out.push(10);
            } else if e == 116 {
                out.push(9);
            } else if e == 114 {
                out.push(13);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else if e == 117 {
                let mut v: u32 = 0;
                let mut k = 0;
                while k < 4 && p.i < p.b.len() {
                    v = v * 16 + hexv(p.b[p.i]);
                    p.i += 1;
                    k += 1;
                }
                if v < 128 {
                    out.push(v as u8);
                } else if v < 2048 {
                    out.push((192 + v / 64) as u8);
                    out.push((128 + v % 64) as u8);
                } else {
                    out.push((224 + v / 4096) as u8);
                    out.push((128 + (v / 64) % 64) as u8);
                    out.push((128 + v % 64) as u8);
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
        }
    }
    let s = Str::from_utf8_lossy(out).to_string();
    StrR { s: s, p: p }
}

fn parse_val(p0: P) -> ValR {
    let mut p = ws(p0);
    if p.i >= p.b.len() {
        p.ok = false;
        return ValR { v: Json::Other, p: p };
