            p = ws(p);
            if p.i >= p.b.len() {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
            let d = p.b[p.i];
            p.i += 1;
            if d == 44 {
                continue;
            } else if d == 125 {
                break;
            } else {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
        }
        ValR { v: Json::Obj(items), p: p }
    } else if c == 91 {
        p.i += 1;
        let mut items: Vec<Json> = Vec::new();
        p = ws(p);
        if p.i < p.b.len() && p.b[p.i] == 93 {
            p.i += 1;
            return ValR { v: Json::Arr(items), p: p };
        }
        loop {
            let vr = parse_val(p);
            let v = vr.v;
            p = vr.p;
            if !p.ok {
