            } else if d == 93 {
                break;
            } else {
                p.ok = false;
                return ValR { v: Json::Other, p: p };
            }
        }
        ValR { v: Json::Arr(items), p: p }
    } else if c == 34 {
        let sr = parse_str(p);
        ValR { v: Json::Text(sr.s), p: sr.p }
    } else {
        let start = p.i;
        while p.i < p.b.len() {
            let d = p.b[p.i];
            if d == 44 || d == 93 || d == 125 || d == 32 || d == 10 || d == 13 || d == 9 {
                break;
            }
            p.i += 1;
        }
        if p.i == start {
            p.ok = false;
        } else {
            let mut tb: Vec<u8> = Vec::new();
            let mut k = start;
            while k < p.i {
                tb.push(p.b[k]);
                k += 1;
            }
            let t = Str::from_utf8_lossy(tb).to_string();
            let good = t == "true" || t == "false" || t == "null" || t.parse::<f64>().is_ok();
            if !good {
                p.ok = false;
            }
        }
        ValR { v: Json::Other, p: p }
    }
}

struct G {
