}

fn strong(g0: G, v: usize) -> G {
    let mut g = g0;
    g.index[v] = g.counter;
    g.low[v] = g.counter;
    g.counter += 1;
    g.stack.push(v);
    g.on[v] = true;
    let nbrs = g.adj[v].clone();
    for w in nbrs {
        if g.index[w] < 0 {
            g = strong(g, w);
            if g.low[w] < g.low[v] {
                g.low[v] = g.low[w];
            }
        } else if g.on[w] {
            if g.index[w] < g.low[v] {
                g.low[v] = g.index[w];
            }
        }
    }
    if g.low[v] == g.index[v] {
        let mut comp: Vec<usize> = Vec::new();
        loop {
            let w = g.stack.pop().unwrap();
            g.on[w] = false;
            comp.push(w);
            if w == v {
                break;
            }
        }
        g.comps.push(comp);
    }
    g
}

struct S {
    adj: Vec<Vec<usize>>,
    bad: Vec<bool>,
    memo: Vec<i64>,
}

struct StageR {
    n: i64,
    st: S,
}

fn stage_of(st0: S, v: usize) -> StageR {
    let mut st = st0;
    if st.memo[v] != -2 {
        let r = st.memo[v];
        return StageR { n: r, st: st };
    }
    if st.bad[v] {
        st.memo[v] = -1;
        return StageR { n: -1, st: st };
    }
    let mut best: i64 = 1;
    let mut ok = true;
    let nb = st.adj[v].clone();
    for w in nb {
        let rr = stage_of(st, w);
        let s = rr.n;
        st = rr.st;
        if s < 0 {
            ok = false;
        } else if s + 1 > best {
            best = s + 1;
        }
    }
    let r = if ok { best } else { -1 };
    st.memo[v] = r;
    StageR { n: r, st: st }
}

fn join(v: Vec<Str>) -> Str {
    let mut s = Str::new();
    let mut first = true;
    for x in v {
        if !first {
            s.push_str(", ");
        }
        first = false;
        s.push_str(x);
    }
    s
}

