fn parse_time(s: &str) -> i64 {
    let b = s.as_bytes();
    if b.len() != 5 || b[2] != 58 {
        return -1;
    }
    let mut i = 0;
    while i < 5 {
        if i != 2 && (b[i] < 48 || b[i] > 57) {
            return -1;
        }
        i += 1;
    }
    let h = ((b[0] - 48) as i64) * 10 + ((b[1] - 48) as i64);
    let m = ((b[3] - 48) as i64) * 10 + ((b[4] - 48) as i64);
    if m > 59 || h > 24 || (h == 24 && m != 0) {
        return -1;
    }
    h * 60 + m
}

