fn digit(c: char) -> i64 {
    if c >= '0' && c <= '9' {
        return (c as i64) - 48;
    }
    -1
}

fn num2(s: Str) -> i64 {
    if s.len() != 2 {
        return -1;
    }
    let mut v: i64 = 0;
    for c in s.chars() {
        let d = digit(c);
        if d < 0 {
            return -1;
        }
        v = v * 10 + d;
    }
    v
}

