        }
        out.push_str(format!("{} {}\n", recs[i].0, recs[i].1));
        let mut merged: Vec<(i64, i64)> = Vec::new();
        let mut x = i;
        while x < j {
            let rs = recs[x].2;
            let re = recs[x].3;
            let k = merged.len();
            if k > 0 && rs <= merged[k - 1].1 {
                if re > merged[k - 1].1 {
                    let last = merged[k - 1];
                    merged.pop();
                    merged.push((last.0, re));
                }
            } else {
                merged.push((rs, re));
            }
            x += 1;
        }
        let mut parts: Vec<String> = Vec::new();
        for m in merged.clone() {
            parts.push(format!("{}-{}", fmt(m.0), fmt(m.1)));
        }
        out.push_str(format!("  busy {}\n", parts.join(", ")));
        let mut free: Vec<String> = Vec::new();
        let mut cur: i64 = 540;
        for m in merged.clone() {
            if m.0 > cur {
                let e = if m.0 < 1080 { m.0 } else { 1080 };
                if e - cur >= 30 {
                    free.push(format!("{}-{}", fmt(cur), fmt(e)));
                }
            }
            if m.1 > cur {
                cur = m.1;
            }
        }
        if cur < 1080 && 1080 - cur >= 30 {
            free.push(format!("{}-{}", fmt(cur), fmt(1080)));
        }
        if free.is_empty() {
            out.push_str("  free none\n");
        } else {
            out.push_str(format!("  free {}\n", free.join(", ")));
        }
        let mut conf: Vec<(i64, String)> = Vec::new();
        let mut a = i;
        while a < j {
            let mut b = a + 1;
            while b < j {
                let os = if recs[a].2 > recs[b].2 { recs[a].2 } else { recs[b].2 };
                let oe = if recs[a].3 < recs[b].3 { recs[a].3 } else { recs[b].3 };
                if os < oe {
                    let wa = recs[a].4.clone();
                    let wb = recs[b].4.clone();
                    let w1 = if wa <= wb { wa.clone() } else { wb.clone() };
                    let w2 = if wa <= wb { wb.clone() } else { wa.clone() };
                    conf.push((os, format!("  conflict {}/{} {}-{}", w1, w2, fmt(os), fmt(oe))));
                }
                b += 1;
            }
            a += 1;
        }
        conf.sort();
        for c in conf.clone() {
            out.push_str(c.1);
            out.push_str("\n");
        }
        i = j;
    }
    if skipped.is_empty() {
        out.push_str("skipped: none\n");
    } else {
        out.push_str(format!("skipped: {}\n", skipped.join(", ")));
    }
    Ok(out)
}

enum J {
    Null,
    Bool(bool),
    Num(bool, f64, i64),
    S(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

struct P {
    c: Vec<char>,
    i: usize,
}

fn ws(p: &mut P) {
    while p.i < p.c.len() && (p.c[p.i] == ' ' || p.c[p.i] == '\t' || p.c[p.i] == '\n' || p.c[p.i] == '\r') {
        p.i += 1;
    }
}

fn hex4(p: &mut P) -> Option<u32> {
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        if p.i >= p.c.len() {
            return None;
        }
        let d = p.c[p.i].to_digit(16)?;
        v = v * 16 + d;
        p.i += 1;
        k += 1;
    }
    Some(v)
}

fn parse_str(p: &mut P) -> Option<String> {
    // assumes current is '"'
    p.i += 1;
    let mut out = String::new();
    loop {
        if p.i >= p.c.len() {
            return None;
        }
        let ch = p.c[p.i];
        p.i += 1;
        if ch == '"' {
            return Some(out);
        }
        if (ch as u32) < 0x20 {
            return None;
        }
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        if p.i >= p.c.len() {
            return None;
        }
        let e = p.c[p.i];
        p.i += 1;
        match e {
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            '/' => out.push('/'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            'u' => {
                let a = hex4(p)?;
                if a >= 0xD800 && a < 0xDC00 {
                    if p.i + 1 < p.c.len() && p.c[p.i] == '\\' && p.c[p.i + 1] == 'u' {
                        p.i += 2;
                        let b = hex4(p)?;
                        if b >= 0xDC00 && b < 0xE000 {
                            let cp = 0x10000 + ((a - 0xD800) << 10) + (b - 0xDC00);
                            out.push(char::from_u32(cp)?);
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if a >= 0xDC00 && a < 0xE000 {
                    return None;
                } else {
                    out.push(char::from_u32(a)?);
                }
            }
            _ => return None,
        }
    }
}

fn is_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn parse_num(p: &mut P) -> Option<J> {
    let start = p.i;
    let mut is_int = true;
    if p.i < p.c.len() && p.c[p.i] == '-' {
        p.i += 1;
    }
    if p.i >= p.c.len() {
        return None;
    }
    if p.c[p.i] == '0' {
        p.i += 1;
    } else if is_digit(p.c[p.i]) {
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
    } else {
        return None;
    }
    if p.i < p.c.len() && p.c[p.i] == '.' {
        is_int = false;
        p.i += 1;
        let s = p.i;
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
        if p.i == s {
            return None;
        }
    }
    if p.i < p.c.len() && (p.c[p.i] == 'e' || p.c[p.i] == 'E') {
        is_int = false;
        p.i += 1;
        if p.i < p.c.len() && (p.c[p.i] == '+' || p.c[p.i] == '-') {
            p.i += 1;
        }
        let s = p.i;
        while p.i < p.c.len() && is_digit(p.c[p.i]) {
            p.i += 1;
        }
        if p.i == s {
            return None;
        }
    }
    let mut text = String::new();
    let mut k = start;
    while k < p.i {
        text.push(p.c[k]);
        k += 1;
    }
    let f: f64 = text.parse::<f64>().ok()?;
    let mut iv: i64 = 0;
    if is_int {
        match text.parse::<i64>() {
            Ok(v) => {
                iv = v;
            }
            Err(_) => {
                is_int = true;
                iv = if f < 0.0 { i64::MIN } else { i64::MAX };
            }
        }
    }
    Some(J::Num(is_int, f, iv))
}

fn lit(p: &mut P, w: &str) -> bool {
    for ch in w.chars() {
        if p.i >= p.c.len() || p.c[p.i] != ch {
            return false;
        }
        p.i += 1;
    }
    true
}

fn parse_val(p: &mut P, depth: usize) -> Option<J> {
    if depth > 200 {
        return None;
    }
    ws(p);
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i];
    if ch == '{' {
        p.i += 1;
        let mut items: Vec<(String, J)> = Vec::new();
        ws(p);
        if p.i < p.c.len() && p.c[p.i] == '}' {
            p.i += 1;
            return Some(J::Obj(items));
        }
        loop {
            ws(p);
            if p.i >= p.c.len() || p.c[p.i] != '"' {
                return None;
            }
            let k = parse_str(p)?;
            ws(p);
            if p.i >= p.c.len() || p.c[p.i] != ':' {
                return None;
            }
            p.i += 1;
            let v = parse_val(p, depth + 1)?;
            let mut found = false;
            let mut idx = 0;
            while idx < items.len() {
                if items[idx].0 == k {
                    items[idx].1 = J::Null;
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                items[idx].1 = v;
            } else {
                items.push((k, v));
            }
            ws(p);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
                continue;
            }
            if p.c[p.i] == '}' {
                p.i += 1;
                return Some(J::Obj(items));
            }
            return None;
        }
    }
    if ch == '[' {
        p.i += 1;
        let mut items: Vec<J> = Vec::new();
        ws(p);
        if p.i < p.c.len() && p.c[p.i] == ']' {
            p.i += 1;
            return Some(J::Arr(items));
        }
        loop {
            let v = parse_val(p, depth + 1)?;
            items.push(v);
            ws(p);
            if p.i >= p.c.len() {
                return None;
            }
            if p.c[p.i] == ',' {
                p.i += 1;
                continue;
            }
            if p.c[p.i] == ']' {
                p.i += 1;
                return Some(J::Arr(items));
            }
            return None;
        }
    }
    if ch == '"' {
        let s = parse_str(p)?;
        return Some(J::S(s));
    }
    if ch == 't' {
        if lit(p, "true") {
            return Some(J::Bool(true));
        }
        return None;
    }
    if ch == 'f' {
        if lit(p, "false") {
            return Some(J::Bool(false));
        }
        return None;
    }
    if ch == 'n' {
        if lit(p, "null") {
            return Some(J::Null);
        }
        return None;
    }
    parse_num(p)
}

fn parse(text: &str) -> Option<J> {
    let mut p = P { c: text.chars().collect(), i: 0 };
    let v = parse_val(&mut p, 0)?;
    ws(&mut p);
    if p.i != p.c.len() {
        return None;
    }
    Some(v)
}

fn get<'a>(o: &'a J, key: &str) -> Option<&'a J> {
    if let J::Obj(items) = o {
        for (k, v) in items.iter() {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

fn bound(s: &J, key: &str) -> Option<i64> {
    match get(s, key) {
        Some(J::Num(_, f, i)) => {
            let _ = f;
            Some(*i)
        }
        _ => None,
    }
}

// compare number to integer bound: returns -1,0,1
fn cmp_num(is_int: bool, f: f64, i: i64, b: i64) -> i32 {
    if is_int && i != i64::MAX && i != i64::MIN {
        if i < b {
            return -1;
        }
        if i > b {
            return 1;
        }
        return 0;
    }
    let bf = b as f64;
    if f < bf {
        return -1;
    }
    if f > bf {
        return 1;
    }
    0
}

fn validate(v: &J, s: &J, path: &str, errs: &mut Vec<(String, String)>) {
    let t = match get(s, "type") {
        Some(J::S(t)) => t.clone(),
        _ => return,
    };
    let ok = match (t.as_str(), v) {
        ("object", J::Obj(_)) => true,
        ("array", J::Arr(_)) => true,
        ("string", J::S(_)) => true,
        ("integer", J::Num(true, _, _)) => true,
        ("number", J::Num(_, _, _)) => true,
        ("boolean", J::Bool(_)) => true,
        ("null", J::Null) => true,
        _ => false,
    };
    if !ok {
        errs.push((path.to_string(), format!("expected {}", t)));
        return;
    }
    match v {
        J::Obj(fields) => {
            let props = get(s, "properties");
            if let Some(J::Obj(ps)) = props {
                for (k, sub) in ps.iter() {
                    if let Some(fv) = get(v, k) {
                        let np = format!("{}.{}", path, k);
                        validate(fv, sub, &np, errs);
                    }
                }
            }
            if let Some(J::Arr(req)) = get(s, "required") {
                for r in req.iter() {
                    if let J::S(name) = r {
                        if get(v, name).is_none() {
                            errs.push((format!("{}.{}", path, name), "missing required field".to_string()));
                        }
                    }
                }
            }
            if let Some(J::Bool(false)) = get(s, "additional") {
                for (k, _) in fields.iter() {
                    let mut inp = false;
                    if let Some(J::Obj(ps)) = props {
                        for (pk, _) in ps.iter() {
                            if pk == k {
                                inp = true;
                            }
                        }
                    }
                    if !inp {
                        errs.push((format!("{}.{}", path, k), "unexpected field".to_string()));
                    }
                }
            }
        }
        J::Arr(items) => {
            if let Some(m) = bound(s, "min_items") {
                if (items.len() as i64) < m {
                    errs.push((path.to_string(), format!("fewer than {} items", m)));
                }
            }
            if let Some(sub) = get(s, "items") {
                let mut idx = 0;
                while idx < items.len() {
                    let np = format!("{}[{}]", path, idx);
                    validate(&items[idx], sub, &np, errs);
                    idx += 1;
                }
            }
        }
        J::S(st) => {
            let n = st.chars().count() as i64;
            if let Some(m) = bound(s, "min_length") {
                if n < m {
                    errs.push((path.to_string(), format!("shorter than {}", m)));
                    return;
                }
            }
            if let Some(m) = bound(s, "max_length") {
                if n > m {
                    errs.push((path.to_string(), format!("longer than {}", m)));
                    return;
                }
            }
            if let Some(J::Arr(en)) = get(s, "enum") {
                let mut found = false;
                for e in en.iter() {
                    if let J::S(x) = e {
                        if x == st {
                            found = true;
                        }
                    }
                }
                if !found {
                    errs.push((path.to_string(), "not in enum".to_string()));
                }
            }
        }
        J::Num(is_int, f, i) => {
            if let Some(m) = bound(s, "minimum") {
                if cmp_num(*is_int, *f, *i, m) < 0 {
                    errs.push((path.to_string(), format!("less than {}", m)));
                    return;
                }
            }
            if let Some(m) = bound(s, "maximum") {
                if cmp_num(*is_int, *f, *i, m) > 0 {
                    errs.push((path.to_string(), format!("greater than {}", m)));
                    return;
                }
            }
        }
        _ => {}
    }
}

fn main(input: Dir) -> Result<Str, Error> {
    let schema_text = input.read_text("schema.json")?;
    let records = input.read_text("records.jsonl")?;
    let schema = match parse(&schema_text) {
        Some(s) => s,
        None => J::Null,
    };
    let mut out = String::new();
    let mut total = 0;
    let mut valid = 0;
    let mut n = 0;
    for line in records.split('\n') {
        n += 1;
        if line.trim().is_empty() {
            continue;
        }
        total += 1;
        match parse(line) {
            None => {
                out.push_str(&format!("line {}: invalid JSON\n", n));
            }
            Some(v) => {
                let mut errs: Vec<(String, String)> = Vec::new();
                validate(&v, &schema, "$", &mut errs);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(&format!("line {}: ok\n", n));
                } else {
                    errs.sort();
                    for (p, m) in errs.iter() {
                        out.push_str(&format!("line {}: {}: {}\n", n, p, m));
                    }
                }
            }
        }
    }
    out.push_str(&format!("valid {} of {}\n", valid, total));
    Ok(out)
}

enum J {
    Null,
    Bool(bool),
    Num(bool, f64, i64),
    S(Str),
    Arr(Vec<J>),
    Obj(Vec<(Str, J)>),
}

fn ws(c: Vec<char>, i0: usize) -> usize {
    let mut i = i0;
    while i < c.len() && (c[i] == ' ' || c[i] == '\t' || c[i] == '\n' || c[i] == '\r') {
        i += 1;
    }
    i
}

fn hex4(c: Vec<char>, i0: usize) -> Option<(u32, usize)> {
    let mut i = i0;
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        if i >= c.len() {
            return None;
        }
        let d = c[i].to_digit(16)?;
        v = v * 16 + d;
        i += 1;
        k += 1;
    }
    Some((v, i))
}

fn parse_str(c: Vec<char>, i0: usize) -> Option<(Str, usize)> {
    let mut i = i0 + 1;
    let mut out = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        let ch = c[i];
        i += 1;
        if ch == '"' {
            return Some((out, i));
        }
        if (ch as u32) < 0x20 {
            return None;
        }
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        if i >= c.len() {
            return None;
        }
        let e = c[i];
        i += 1;
        match e {
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            '/' => out.push('/'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            'u' => {
                let (a, j) = hex4(c, i)?;
                i = j;
                if a >= 0xD800 && a < 0xDC00 {
                    if i + 1 < c.len() && c[i] == '\\' && c[i + 1] == 'u' {
                        let (b, j2) = hex4(c, i + 2)?;
                        i = j2;
                        if b >= 0xDC00 && b < 0xE000 {
                            let cp = 0x10000 + ((a - 0xD800) << 10) + (b - 0xDC00);
                            out.push(char::from_u32(cp)?);
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if a >= 0xDC00 && a < 0xE000 {
                    return None;
                } else {
                    out.push(char::from_u32(a)?);
                }
            }
            _ => return None,
        }
    }
}

fn is_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn parse_num(c: Vec<char>, i0: usize) -> Option<(J, usize)> {
    let mut i = i0;
    let mut is_int = true;
    if i < c.len() && c[i] == '-' {
        i += 1;
    }
    if i >= c.len() {
        return None;
    }
    if c[i] == '0' {
        i += 1;
    } else if is_digit(c[i]) {
        while i < c.len() && is_digit(c[i]) {
            i += 1;
        }
    } else {
        return None;
    }
    if i < c.len() && c[i] == '.' {
        is_int = false;
        i += 1;
        let s = i;
        while i < c.len() && is_digit(c[i]) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    if i < c.len() && (c[i] == 'e' || c[i] == 'E') {
        is_int = false;
        i += 1;
        if i < c.len() && (c[i] == '+' || c[i] == '-') {
            i += 1;
        }
        let s = i;
        while i < c.len() && is_digit(c[i]) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    let mut text = String::new();
    let mut k = i0;
    while k < i {
        text.push(c[k]);
        k += 1;
    }
    let f: f64 = text.parse::<f64>().ok()?;
    let mut iv: i64 = 0;
    if is_int {
        match text.parse::<i64>() {
            Ok(v) => {
                iv = v;
            }
            Err(_) => {
                iv = if f < 0.0 { i64::MIN } else { i64::MAX };
            }
        }
    }
    Some((J::Num(is_int, f, iv), i))
}

fn lit(c: Vec<char>, i0: usize, w: Str) -> Option<usize> {
    let mut i = i0;
    for ch in w.chars() {
        if i >= c.len() || c[i] != ch {
            return None;
        }
        i += 1;
    }
    Some(i)
}

fn parse_val(c: Vec<char>, i0: usize, depth: usize) -> Option<(J, usize)> {
    if depth > 200 {
        return None;
    }
    let mut i = ws(c, i0);
    if i >= c.len() {
        return None;
    }
    let ch = c[i];
    if ch == '{' {
        i += 1;
        let mut items: Vec<(Str, J)> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == '}' {
            return Some((J::Obj(items), i + 1));
        }
        loop {
            i = ws(c, i);
            if i >= c.len() || c[i] != '"' {
                return None;
            }
            let (k, j) = parse_str(c, i)?;
            i = ws(c, j);
            if i >= c.len() || c[i] != ':' {
                return None;
            }
            i += 1;
            let (v, j2) = parse_val(c, i, depth + 1)?;
            i = j2;
            let mut found = false;
            let mut idx = 0;
            while idx < items.len() {
                if items[idx].0 == k {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                items[idx] = (k, v);
            } else {
                items.push((k, v));
            }
            i = ws(c, i);
            if i >= c.len() {
                return None;
            }
            if c[i] == ',' {
                i += 1;
                continue;
            }
            if c[i] == '}' {
                return Some((J::Obj(items), i + 1));
            }
            return None;
        }
    }
    if ch == '[' {
        i += 1;
        let mut items: Vec<J> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == ']' {
            return Some((J::Arr(items), i + 1));
        }
        loop {
            let (v, j) = parse_val(c, i, depth + 1)?;
            items.push(v);
            i = ws(c, j);
            if i >= c.len() {
                return None;
            }
            if c[i] == ',' {
                i += 1;
                continue;
            }
            if c[i] == ']' {
                return Some((J::Arr(items), i + 1));
            }
            return None;
        }
    }
    if ch == '"' {
        let (s, j) = parse_str(c, i)?;
        return Some((J::S(s), j));
    }
    if ch == 't' {
        let j = lit(c, i, "true")?;
        return Some((J::Bool(true), j));
    }
    if ch == 'f' {
        let j = lit(c, i, "false")?;
        return Some((J::Bool(false), j));
    }
    if ch == 'n' {
        let j = lit(c, i, "null")?;
        return Some((J::Null, j));
    }
    parse_num(c, i)
}

fn parse(text: Str) -> Option<J> {
    let c: Vec<char> = text.chars().collect();
    let (v, i) = parse_val(c, 0, 0)?;
    let j = ws(c, i);
    if j != c.len() {
        return None;
    }
    Some(v)
}

fn get(o: J, key: Str) -> Option<J> {
