fn cmp_num(is_int: bool, f: f64, i: i64, b: i64) -> i32 {
    if is_int && i != i64::MAX && i != i64::MIN {
        if i < b {
            return -1;
        }
        if i > b {
            return 1;
        }
        return 0;
    }
    let bf = b as f64;
    if f < bf {
        return -1;
    }
    if f > bf {
        return 1;
    }
    0
}

fn validate(v: J, s: J, path: Str, errs0: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs0;
    let t = match get(s, "type") {
        Some(J::S(t)) => t,
        _ => return errs,
    };
    let ok = match (t.as_str(), v) {
        ("object", J::Obj(_)) => true,
        ("array", J::Arr(_)) => true,
        ("string", J::S(_)) => true,
        ("integer", J::Num(true, _, _)) => true,
        ("number", J::Num(_, _, _)) => true,
        ("boolean", J::Bool(_)) => true,
        ("null", J::Null) => true,
        _ => false,
    };
    if !ok {
        errs.push((path, format!("expected {}", t)));
        return errs;
    }
    match v {
        J::Obj(fields) => {
            let props = get(s, "properties");
            if let Some(J::Obj(ps)) = props {
                for (k, sub) in ps {
                    if let Some(fv) = get(v, k) {
                        let np = format!("{}.{}", path, k);
                        errs = validate(fv, sub, np, errs);
                    }
                }
            }
            if let Some(J::Arr(req)) = get(s, "required") {
                for r in req {
                    if let J::S(name) = r {
                        if get(v, name).is_none() {
                            errs.push((format!("{}.{}", path, name), "missing required field".to_string()));
                        }
                    }
                }
            }
            if let Some(J::Bool(false)) = get(s, "additional") {
                for (k, _) in fields {
                    let mut inp = false;
                    if let Some(J::Obj(ps)) = props {
                        for (pk, _) in ps {
                            if pk == k {
                                inp = true;
                            }
                        }
                    }
                    if !inp {
                        errs.push((format!("{}.{}", path, k), "unexpected field".to_string()));
                    }
                }
            }
        }
        J::Arr(items) => {
            if let Some(m) = bound(s, "min_items") {
                if (items.len() as i64) < m {
                    errs.push((path, format!("fewer than {} items", m)));
                }
            }
            if let Some(sub) = get(s, "items") {
                let mut idx = 0;
                while idx < items.len() {
                    let np = format!("{}[{}]", path, idx);
                    errs = validate(items[idx], sub, np, errs);
                    idx += 1;
                }
            }
        }
        J::S(st) => {
            let n = st.chars().count() as i64;
            if let Some(m) = bound(s, "min_length") {
                if n < m {
                    errs.push((path, format!("shorter than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "max_length") {
                if n > m {
                    errs.push((path, format!("longer than {}", m)));
                    return errs;
                }
            }
            if let Some(J::Arr(en)) = get(s, "enum") {
                let mut found = false;
                for e in en {
                    if let J::S(x) = e {
                        if x == st {
                            found = true;
                        }
                    }
                }
                if !found {
                    errs.push((path, "not in enum".to_string()));
                }
            }
        }
        J::Num(is_int, f, i) => {
            if let Some(m) = bound(s, "minimum") {
                if cmp_num(is_int, f, i, m) < 0 {
                    errs.push((path, format!("less than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "maximum") {
                if cmp_num(is_int, f, i, m) > 0 {
                    errs.push((path, format!("greater than {}", m)));
                    return errs;
                }
            }
        }
        _ => {}
    }
    errs
}

fn main(input: Dir) -> Result<Str, Error> {
    let schema_text = input.read_text("schema.json")?;
