enum J {
    Null,
    Bool(bool),
    Num(bool, f64, i64),
    S(Str),
    Arr(Vec<J>),
    Obj(Vec<(Str, J)>),
}

fn chr(cp: u32) -> Option<Str> {
    let ch = char::from_u32(cp)?;
    Some(ch.to_string())
}

fn ws(c: Vec<Str>, i0: usize) -> usize {
    let mut i = i0;
    while i < c.len() && (c[i] == " " || c[i] == "\t" || c[i] == "\n" || c[i] == "\r") {
        i += 1;
    }
    i
}

fn hex4(c: Vec<Str>, i0: usize) -> Option<(u32, usize)> {
    let mut i = i0;
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        if i >= c.len() {
            return None;
        }
        let low = c[i].to_lowercase();
        let d = "0123456789abcdef".find(low.as_str())?;
        v = v * 16 + (d as u32);
        i += 1;
        k += 1;
    }
    Some((v, i))
}

fn parse_str(c: Vec<Str>, i0: usize) -> Option<(Str, usize)> {
    let mut i = i0 + 1;
    let mut out = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        let ch = c[i].clone();
        i += 1;
        if ch == "\"" {
            return Some((out, i));
        }
        if ch.as_str() < " " {
            return None;
        }
        if ch != "\\" {
            out.push_str(ch.as_str());
            continue;
        }
        if i >= c.len() {
            return None;
        }
        let e = c[i].clone();
        i += 1;
        match e.as_str() {
            "\"" => out.push_str("\""),
            "\\" => out.push_str("\\"),
            "/" => out.push_str("/"),
            "b" => out.push_str(chr(8)?.as_str()),
            "f" => out.push_str(chr(12)?.as_str()),
            "n" => out.push_str("\n"),
            "r" => out.push_str("\r"),
            "t" => out.push_str("\t"),
            "u" => {
                let (a, j) = hex4(c, i)?;
                i = j;
                if a >= 0xD800 && a < 0xDC00 {
                    if i + 1 < c.len() && c[i] == "\\" && c[i + 1] == "u" {
                        let (b, j2) = hex4(c, i + 2)?;
                        i = j2;
                        if b >= 0xDC00 && b < 0xE000 {
                            let cp = 0x10000 + ((a - 0xD800) << 10) + (b - 0xDC00);
                            out.push_str(chr(cp)?.as_str());
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if a >= 0xDC00 && a < 0xE000 {
                    return None;
                } else {
                    out.push_str(chr(a)?.as_str());
                }
            }
            _ => return None,
        }
    }
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && "0123456789".contains(c.as_str())
}

fn parse_num(c: Vec<Str>, i0: usize) -> Option<(J, usize)> {
    let mut i = i0;
    let mut is_int = true;
    if i < c.len() && c[i] == "-" {
        i += 1;
    }
    if i >= c.len() {
        return None;
    }
    if c[i] == "0" {
        i += 1;
    } else if is_digit(c[i].clone()) {
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
    } else {
        return None;
    }
    if i < c.len() && c[i] == "." {
        is_int = false;
        i += 1;
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    if i < c.len() && (c[i] == "e" || c[i] == "E") {
        is_int = false;
        i += 1;
        if i < c.len() && (c[i] == "+" || c[i] == "-") {
            i += 1;
        }
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    let mut text = String::new();
    let mut k = i0;
    while k < i {
        text.push_str(c[k].as_str());
        k += 1;
    }
    let f: f64 = text.parse::<f64>().ok()?;
    let mut iv: i64 = 0;
    if is_int {
        match text.parse::<i64>() {
            Ok(v) => {
                iv = v;
            }
            Err(_) => {
                iv = if f < 0.0 { i64::MIN } else { i64::MAX };
            }
        }
    }
    Some((J::Num(is_int, f, iv), i))
}

fn lit(c: Vec<Str>, i0: usize, w: Str) -> Option<usize> {
    let mut i = i0;
    for ch in w.chars() {
        if i >= c.len() || c[i] != ch {
            return None;
        }
        i += 1;
    }
    Some(i)
}

fn parse_val(c: Vec<Str>, i0: usize, depth: usize) -> Option<(J, usize)> {
    if depth > 200 {
        return None;
    }
    let mut i = ws(c, i0);
    if i >= c.len() {
        return None;
    }
    let ch = c[i].clone();
    if ch == "{" {
        i += 1;
        let mut items: Vec<(Str, J)> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "}" {
            return Some((J::Obj(items), i + 1));
        }
        loop {
            i = ws(c, i);
            if i >= c.len() || c[i] != "\"" {
                return None;
            }
            let (k, j) = parse_str(c, i)?;
            i = ws(c, j);
            if i >= c.len() || c[i] != ":" {
                return None;
            }
            i += 1;
            let (v, j2) = parse_val(c, i, depth + 1)?;
            i = j2;
            let mut found = false;
            let mut idx = 0;
            while idx < items.len() {
                if items[idx].0 == k {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                items[idx] = (k, v);
            } else {
                items.push((k, v));
            }
            i = ws(c, i);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "}" {
                return Some((J::Obj(items), i + 1));
            }
            return None;
        }
    }
    if ch == "[" {
        i += 1;
        let mut items: Vec<J> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "]" {
            return Some((J::Arr(items), i + 1));
        }
        loop {
            let (v, j) = parse_val(c, i, depth + 1)?;
            items.push(v);
            i = ws(c, j);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "]" {
                return Some((J::Arr(items), i + 1));
            }
            return None;
        }
    }
    if ch == "\"" {
        let (s, j) = parse_str(c, i)?;
        return Some((J::S(s), j));
    }
    if ch == "t" {
        let j = lit(c, i, "true".to_string())?;
        return Some((J::Bool(true), j));
    }
    if ch == "f" {
        let j = lit(c, i, "false".to_string())?;
        return Some((J::Bool(false), j));
    }
    if ch == "n" {
        let j = lit(c, i, "null".to_string())?;
        return Some((J::Null, j));
    }
    parse_num(c, i)
}

fn parse(text: Str) -> Option<J> {
    let c: Vec<Str> = text.chars().collect();
    let (v, i) = parse_val(c, 0, 0)?;
    let j = ws(c, i);
    if j != c.len() {
        return None;
    }
    Some(v)
}

