                        if b >= 0xDC00 && b < 0xE000 {
                            let cp = 0x10000 + ((a - 0xD800) << 10) + (b - 0xDC00);
                            out.push_str(chr(cp)?.as_str());
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if a >= 0xDC00 && a < 0xE000 {
                    return None;
                } else {
                    out.push_str(chr(a)?.as_str());
                }
            }
            _ => return None,
        }
    }
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && "0123456789".contains(c.as_str())
}

fn parse_num(c: Vec<Str>, i0: usize) -> Option<(J, usize)> {
    let mut i = i0;
    let mut is_int = true;
    if i < c.len() && c[i] == "-" {
        i += 1;
    }
    if i >= c.len() {
        return None;
    }
    if c[i] == "0" {
        i += 1;
    } else if is_digit(c[i].clone()) {
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
    } else {
        return None;
    }
    if i < c.len() && c[i] == "." {
        is_int = false;
        i += 1;
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    if i < c.len() && (c[i] == "e" || c[i] == "E") {
        is_int = false;
        i += 1;
        if i < c.len() && (c[i] == "+" || c[i] == "-") {
            i += 1;
        }
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    let mut text = String::new();
    let mut k = i0;
    while k < i {
        text.push_str(c[k].as_str());
        k += 1;
    }
    let f: f64 = text.parse::<f64>().ok()?;
    let mut iv: i64 = 0;
    if is_int {
        match text.parse::<i64>() {
            Ok(v) => {
                iv = v;
            }
            Err(_) => {
                iv = if f < 0.0 { i64::MIN } else { i64::MAX };
            }
        }
    }
    Some((J::Num(is_int, f, iv), i))
}

fn lit(c: Vec<Str>, i0: usize, w: Str) -> Option<usize> {
    let mut i = i0;
    for ch in w.chars() {
        if i >= c.len() || c[i] != ch {
            return None;
        }
        i += 1;
    }
    Some(i)
}

fn parse_val(c: Vec<Str>, i0: usize, depth: usize) -> Option<(J, usize)> {
    if depth > 200 {
        return None;
    }
    let mut i = ws(c, i0);
    if i >= c.len() {
        return None;
    }
    let ch = c[i].clone();
    if ch == "{" {
        i += 1;
        let mut items: Vec<(Str, J)> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "}" {
            return Some((J::Obj(items), i + 1));
        }
        loop {
            i = ws(c, i);
            if i >= c.len() || c[i] != "\"" {
                return None;
            }
            let (k, j) = parse_str(c, i)?;
            i = ws(c, j);
            if i >= c.len() || c[i] != ":" {
                return None;
            }
            i += 1;
            let (v, j2) = parse_val(c, i, depth + 1)?;
            i = j2;
            let mut found = false;
            let mut idx = 0;
            while idx < items.len() {
                if items[idx].0 == k {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                items[idx] = (k, v);
            } else {
                items.push((k, v));
            }
            i = ws(c, i);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "}" {
                return Some((J::Obj(items), i + 1));
            }
            return None;
        }
    }
    if ch == "[" {
        i += 1;
        let mut items: Vec<J> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "]" {
            return Some((J::Arr(items), i + 1));
        }
        loop {
            let (v, j) = parse_val(c, i, depth + 1)?;
            items.push(v);
            i = ws(c, j);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "]" {
                return Some((J::Arr(items), i + 1));
            }
            return None;
        }
    }
    if ch == "\"" {
        let (s, j) = parse_str(c, i)?;
        return Some((J::S(s), j));
    }
    if ch == "t" {
        let j = lit(c, i, "true".to_string())?;
        return Some((J::Bool(true), j));
    }
    if ch == "f" {
        let j = lit(c, i, "false".to_string())?;
        return Some((J::Bool(false), j));
    }
    if ch == "n" {
        let j = lit(c, i, "null".to_string())?;
        return Some((J::Null, j));
    }
    parse_num(c, i)
}

fn parse(text: Str) -> Option<J> {
    let c: Vec<Str> = text.chars().collect();
    let (v, i) = parse_val(c, 0, 0)?;
    let j = ws(c, i);
    if j != c.len() {
        return None;
    }
    Some(v)
}

fn get(o: J, key: Str) -> Option<J> {
    if let J::Obj(items) = o {
        for (k, v) in items {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

fn bound(s: J, key: Str) -> Option<i64> {
    match get(s, key) {
        Some(J::Num(_, _, i)) => Some(i),
        _ => None,
    }
}

fn cmp_num(is_int: bool, f: f64, i: i64, b: i64) -> i32 {
    if is_int && i != i64::MAX && i != i64::MIN {
        if i < b {
            return -1;
        }
        if i > b {
            return 1;
        }
        return 0;
    }
    let bf = b as f64;
    if f < bf {
        return -1;
    }
    if f > bf {
        return 1;
    }
    0
}

fn validate(v: J, s: J, path: Str, errs0: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut errs = errs0;
    let t = match get(s, "type".to_string()) {
        Some(J::S(t)) => t,
        _ => return errs,
    };
    let ok = match (t.as_str(), v) {
        ("object", J::Obj(_)) => true,
        ("array", J::Arr(_)) => true,
        ("string", J::S(_)) => true,
        ("integer", J::Num(true, _, _)) => true,
        ("number", J::Num(_, _, _)) => true,
        ("boolean", J::Bool(_)) => true,
        ("null", J::Null) => true,
        _ => false,
    };
    if !ok {
        errs.push((path, format!("expected {}", t)));
        return errs;
    }
    match v {
        J::Obj(fields) => {
            let props = get(s, "properties".to_string());
            if let Some(J::Obj(ps)) = props {
                for (k, sub) in ps {
                    if let Some(fv) = get(v, k.clone()) {
                        let np = format!("{}.{}", path, k);
                        errs = validate(fv, sub, np, errs);
                    }
                }
            }
            if let Some(J::Arr(req)) = get(s, "required".to_string()) {
                for r in req {
                    if let J::S(name) = r {
                        if get(v, name.clone()).is_none() {
                            errs.push((format!("{}.{}", path, name), "missing required field".to_string()));
                        }
                    }
                }
            }
            if let Some(J::Bool(false)) = get(s, "additional".to_string()) {
                for (k, _) in fields {
                    let mut inp = false;
                    if let Some(J::Obj(ps)) = props {
                        for (pk, _) in ps {
                            if pk == k {
                                inp = true;
                            }
                        }
                    }
                    if !inp {
                        errs.push((format!("{}.{}", path, k), "unexpected field".to_string()));
                    }
                }
            }
        }
        J::Arr(items) => {
            if let Some(m) = bound(s, "min_items".to_string()) {
                if (items.len() as i64) < m {
                    errs.push((path.clone(), format!("fewer than {} items", m)));
                }
            }
            if let Some(sub) = get(s, "items".to_string()) {
                let mut idx = 0;
                while idx < items.len() {
                    let np = format!("{}[{}]", path, idx);
                    errs = validate(items[idx], sub, np, errs);
                    idx += 1;
                }
            }
        }
        J::S(st) => {
            let n = st.chars().count() as i64;
            if let Some(m) = bound(s, "min_length".to_string()) {
                if n < m {
                    errs.push((path, format!("shorter than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "max_length".to_string()) {
                if n > m {
                    errs.push((path, format!("longer than {}", m)));
                    return errs;
                }
            }
            if let Some(J::Arr(en)) = get(s, "enum".to_string()) {
                let mut found = false;
                for e in en {
                    if let J::S(x) = e {
                        if x == st {
                            found = true;
                        }
                    }
                }
                if !found {
                    errs.push((path, "not in enum".to_string()));
                }
            }
        }
        J::Num(is_int, f, i) => {
            if let Some(m) = bound(s, "minimum".to_string()) {
                if cmp_num(is_int, f, i, m) < 0 {
                    errs.push((path, format!("less than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "maximum".to_string()) {
                if cmp_num(is_int, f, i, m) > 0 {
                    errs.push((path, format!("greater than {}", m)));
                    return errs;
                }
            }
        }
        _ => {}
    }
    errs
}

fn main(input: Dir) -> Result<Str, Error> {
    let schema_text = input.read_text("schema.json")?;
    let records = input.read_text("records.jsonl")?;
    let schema = match parse(schema_text) {
        Some(s) => s,
        None => J::Null,
    };
    let mut out = String::new();
    let mut total = 0;
    let mut valid = 0;
    let mut n = 0;
    for line in records.split("\n") {
        n += 1;
        if line.trim().is_empty() {
            continue;
        }
        total += 1;
        match parse(line.to_string()) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", n).as_str());
            }
            Some(v) => {
                let mut errs: Vec<(Str, Str)> = Vec::new();
                errs = validate(v, schema, "$".to_string(), errs);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", n).as_str());
                } else {
                    errs.sort();
                    for (p, m) in errs {
                        out.push_str(format!("line {}: {}: {}\n", n, p, m).as_str());
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}\n", valid, total).as_str());
    Ok(out)
}

enum J {
    Null,
    Bool(bool),
    Num(Num),
    S(Str),
    Arr(Vec<J>),
    Obj(Vec<Field>),
}

struct Num {
    is_int: bool,
    f: f64,
    i: i64,
}

struct Field {
    key: Str,
    val: J,
}

struct PS {
    s: Str,
    i: usize,
}

struct PH {
    v: u32,
    i: usize,
}

struct PJ {
    v: J,
    i: usize,
}

struct E {
    path: Str,
    msg: Str,
}

fn chr(cp: u32) -> Option<Str> {
    let ch = char::from_u32(cp)?;
    Some(ch.to_string())
}

fn ws(c: Vec<Str>, i0: usize) -> usize {
    let mut i = i0;
    while i < c.len() && (c[i] == " " || c[i] == "\t" || c[i] == "\n" || c[i] == "\r") {
        i += 1;
    }
    i
}

fn hex4(c: Vec<Str>, i0: usize) -> Option<PH> {
    let mut i = i0;
    let mut v: u32 = 0;
    let mut k = 0;
    while k < 4 {
        if i >= c.len() {
            return None;
        }
        let low = c[i].to_lowercase();
        let d = "0123456789abcdef".find(low.as_str())?;
        v = v * 16 + (d as u32);
        i += 1;
        k += 1;
    }
    Some(PH { v: v, i: i })
}

fn parse_str(c: Vec<Str>, i0: usize) -> Option<PS> {
    let mut i = i0 + 1;
    let mut out = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        let ch = c[i].clone();
        i += 1;
        if ch == "\"" {
            return Some(PS { s: out, i: i });
        }
        if ch.as_str() < " " {
            return None;
        }
        if ch != "\\" {
            out.push_str(ch.as_str());
            continue;
        }
        if i >= c.len() {
            return None;
        }
        let e = c[i].clone();
        i += 1;
        match e.as_str() {
            "\"" => out.push_str("\""),
            "\\" => out.push_str("\\"),
            "/" => out.push_str("/"),
            "b" => out.push_str(chr(8)?.as_str()),
            "f" => out.push_str(chr(12)?.as_str()),
            "n" => out.push_str("\n"),
            "r" => out.push_str("\r"),
            "t" => out.push_str("\t"),
            "u" => {
                let h = hex4(c, i)?;
                let a = h.v;
                i = h.i;
                if a >= 0xD800 && a < 0xDC00 {
                    if i + 1 < c.len() && c[i] == "\\" && c[i + 1] == "u" {
                        let h2 = hex4(c, i + 2)?;
                        let b = h2.v;
                        i = h2.i;
                        if b >= 0xDC00 && b < 0xE000 {
                            let cp = 0x10000 + ((a - 0xD800) << 10) + (b - 0xDC00);
                            out.push_str(chr(cp)?.as_str());
                        } else {
                            return None;
                        }
                    } else {
                        return None;
                    }
                } else if a >= 0xDC00 && a < 0xE000 {
                    return None;
                } else {
                    out.push_str(chr(a)?.as_str());
                }
            }
            _ => return None,
        }
    }
}

fn is_digit(c: Str) -> bool {
    c.len() == 1 && "0123456789".contains(c.as_str())
}

fn parse_num(c: Vec<Str>, i0: usize) -> Option<PJ> {
    let mut i = i0;
    let mut is_int = true;
    if i < c.len() && c[i] == "-" {
        i += 1;
    }
    if i >= c.len() {
        return None;
    }
    if c[i] == "0" {
        i += 1;
    } else if is_digit(c[i].clone()) {
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
    } else {
        return None;
    }
    if i < c.len() && c[i] == "." {
        is_int = false;
        i += 1;
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    if i < c.len() && (c[i] == "e" || c[i] == "E") {
        is_int = false;
        i += 1;
        if i < c.len() && (c[i] == "+" || c[i] == "-") {
            i += 1;
        }
        let s = i;
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
        if i == s {
            return None;
        }
    }
    let mut text = String::new();
    let mut k = i0;
    while k < i {
        text.push_str(c[k].as_str());
        k += 1;
    }
    let f: f64 = text.parse::<f64>().ok()?;
    let mut iv: i64 = 0;
    if is_int {
        match text.parse::<i64>() {
            Ok(v) => {
                iv = v;
            }
            Err(_) => {
                iv = if f < 0.0 { i64::MIN } else { i64::MAX };
            }
        }
    }
    Some(PJ { v: J::Num(Num { is_int: is_int, f: f, i: iv }), i: i })
}

fn lit(c: Vec<Str>, i0: usize, w: Str) -> Option<usize> {
    let mut i = i0;
    for ch in w.chars() {
        if i >= c.len() || c[i] != ch {
            return None;
        }
        i += 1;
    }
    Some(i)
}

fn parse_val(c: Vec<Str>, i0: usize, depth: usize) -> Option<PJ> {
    if depth > 200 {
        return None;
    }
    let mut i = ws(c, i0);
    if i >= c.len() {
        return None;
    }
    let ch = c[i].clone();
    if ch == "{" {
        i += 1;
        let mut items: Vec<Field> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "}" {
            return Some(PJ { v: J::Obj(items), i: i + 1 });
        }
        loop {
            i = ws(c, i);
            if i >= c.len() || c[i] != "\"" {
                return None;
            }
            let ks = parse_str(c, i)?;
            let k = ks.s;
            i = ws(c, ks.i);
            if i >= c.len() || c[i] != ":" {
                return None;
            }
            i += 1;
            let pv = parse_val(c, i, depth + 1)?;
            i = pv.i;
            let v = pv.v;
            let mut found = false;
            let mut idx = 0;
            while idx < items.len() {
                if items[idx].key == k {
                    found = true;
                    break;
                }
                idx += 1;
            }
            if found {
                items[idx] = Field { key: k, val: v };
            } else {
                items.push(Field { key: k, val: v });
            }
            i = ws(c, i);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "}" {
                return Some(PJ { v: J::Obj(items), i: i + 1 });
            }
            return None;
        }
    }
    if ch == "[" {
        i += 1;
        let mut items: Vec<J> = Vec::new();
        i = ws(c, i);
        if i < c.len() && c[i] == "]" {
            return Some(PJ { v: J::Arr(items), i: i + 1 });
        }
        loop {
            let pv = parse_val(c, i, depth + 1)?;
            items.push(pv.v);
            i = ws(c, pv.i);
            if i >= c.len() {
                return None;
            }
            if c[i] == "," {
                i += 1;
                continue;
            }
            if c[i] == "]" {
                return Some(PJ { v: J::Arr(items), i: i + 1 });
            }
            return None;
        }
    }
    if ch == "\"" {
        let ps = parse_str(c, i)?;
        return Some(PJ { v: J::S(ps.s), i: ps.i });
    }
    if ch == "t" {
        let j = lit(c, i, "true".to_string())?;
        return Some(PJ { v: J::Bool(true), i: j });
    }
    if ch == "f" {
        let j = lit(c, i, "false".to_string())?;
        return Some(PJ { v: J::Bool(false), i: j });
    }
    if ch == "n" {
        let j = lit(c, i, "null".to_string())?;
        return Some(PJ { v: J::Null, i: j });
    }
    parse_num(c, i)
}

fn parse(text: Str) -> Option<J> {
    let c: Vec<Str> = text.chars().collect();
    let r = parse_val(c, 0, 0)?;
    let j = ws(c, r.i);
    if j != c.len() {
        return None;
    }
    Some(r.v)
}

fn get(o: J, key: Str) -> Option<J> {
    if let J::Obj(items) = o {
        for f in items {
            if f.key == key {
                return Some(f.val);
            }
        }
    }
    None
}

fn bound(s: J, key: Str) -> Option<i64> {
    match get(s, key) {
        Some(J::Num(n)) => Some(n.i),
        _ => None,
    }
}

fn cmp_num(n: Num, b: i64) -> i32 {
    if n.is_int && n.i != i64::MAX && n.i != i64::MIN {
        if n.i < b {
            return -1;
        }
        if n.i > b {
            return 1;
        }
        return 0;
    }
    let bf = b as f64;
    if n.f < bf {
        return -1;
    }
    if n.f > bf {
        return 1;
    }
    0
}

fn type_ok(t: Str, v: J) -> bool {
    match v {
        J::Obj(_) => t == "object",
        J::Arr(_) => t == "array",
        J::S(_) => t == "string",
        J::Num(n) => t == "number" || (t == "integer" && n.is_int),
        J::Bool(_) => t == "boolean",
        J::Null => t == "null",
    }
}

fn mk(path: Str, msg: Str) -> E {
    E { path: path, msg: msg }
}

fn validate(v: J, s: J, path: Str, errs0: Vec<E>) -> Vec<E> {
    let mut errs = errs0;
    let t = match get(s, "type".to_string()) {
        Some(J::S(t)) => t,
        _ => return errs,
    };
    if !type_ok(t.clone(), v) {
        errs.push(mk(path, format!("expected {}", t)));
        return errs;
    }
    match v {
        J::Obj(fields) => {
            let props = get(s, "properties".to_string());
            if let Some(J::Obj(ps)) = props {
                for p in ps {
                    if let Some(fv) = get(v, p.key.clone()) {
                        let np = format!("{}.{}", path, p.key);
                        errs = validate(fv, p.val, np, errs);
                    }
                }
            }
            if let Some(J::Arr(req)) = get(s, "required".to_string()) {
                for r in req {
                    if let J::S(name) = r {
                        if get(v, name.clone()).is_none() {
                            errs.push(mk(format!("{}.{}", path, name), "missing required field".to_string()));
                        }
                    }
                }
            }
            if let Some(J::Bool(false)) = get(s, "additional".to_string()) {
                for f in fields {
                    let mut inp = false;
                    if let Some(J::Obj(ps)) = props {
                        for p in ps {
                            if p.key == f.key {
                                inp = true;
                            }
                        }
                    }
                    if !inp {
                        errs.push(mk(format!("{}.{}", path, f.key), "unexpected field".to_string()));
                    }
                }
            }
        }
        J::Arr(items) => {
            if let Some(m) = bound(s, "min_items".to_string()) {
                if (items.len() as i64) < m {
                    errs.push(mk(path.clone(), format!("fewer than {} items", m)));
                }
            }
            if let Some(sub) = get(s, "items".to_string()) {
                let mut idx = 0;
                while idx < items.len() {
                    let np = format!("{}[{}]", path, idx);
                    errs = validate(items[idx], sub, np, errs);
                    idx += 1;
                }
            }
        }
        J::S(st) => {
            let n = st.chars().count() as i64;
            if let Some(m) = bound(s, "min_length".to_string()) {
                if n < m {
                    errs.push(mk(path, format!("shorter than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "max_length".to_string()) {
                if n > m {
                    errs.push(mk(path, format!("longer than {}", m)));
                    return errs;
                }
            }
            if let Some(J::Arr(en)) = get(s, "enum".to_string()) {
                let mut found = false;
                for e in en {
                    if let J::S(x) = e {
                        if x == st {
                            found = true;
                        }
                    }
                }
                if !found {
                    errs.push(mk(path, "not in enum".to_string()));
                }
            }
        }
        J::Num(num) => {
            if let Some(m) = bound(s, "minimum".to_string()) {
                if cmp_num(num, m) < 0 {
                    errs.push(mk(path, format!("less than {}", m)));
                    return errs;
                }
            }
            if let Some(m) = bound(s, "maximum".to_string()) {
                if cmp_num(num, m) > 0 {
                    errs.push(mk(path, format!("greater than {}", m)));
                    return errs;
                }
            }
        }
        _ => {}
    }
    errs
}

fn gt(a: E, b: E) -> bool {
    if a.path.as_str() > b.path.as_str() {
        return true;
    }
    if a.path.as_str() < b.path.as_str() {
        return false;
    }
    a.msg.as_str() > b.msg.as_str()
}

fn sort_errs(e0: Vec<E>) -> Vec<E> {
    let mut errs = e0;
    let n = errs.len();
    let mut i = 0;
    while i < n {
        let mut j = 0;
        while j + 1 < n - i {
            let a = mk(errs[j].path.clone(), errs[j].msg.clone());
            let b = mk(errs[j + 1].path.clone(), errs[j + 1].msg.clone());
            if gt(mk(a.path.clone(), a.msg.clone()), mk(b.path.clone(), b.msg.clone())) {
                errs[j] = b;
                errs[j + 1] = a;
            }
            j += 1;
        }
        i += 1;
    }
    errs
}

fn main(input: Dir) -> Result<Str, Error> {
    let schema_text = input.read_text("schema.json")?;
    let records = input.read_text("records.jsonl")?;
    let schema = match parse(schema_text) {
        Some(s) => s,
        None => J::Null,
    };
    let mut out = String::new();
    let mut total = 0;
    let mut valid = 0;
    let mut n = 0;
    for line in records.split("\n") {
        n += 1;
        if line.trim().is_empty() {
            continue;
        }
        total += 1;
        match parse(line.to_string()) {
            None => {
                out.push_str(format!("line {}: invalid JSON\n", n).as_str());
            }
            Some(v) => {
                let mut errs: Vec<E> = Vec::new();
                errs = validate(v, schema, "$".to_string(), errs);
                if errs.is_empty() {
                    valid += 1;
                    out.push_str(format!("line {}: ok\n", n).as_str());
                } else {
                    errs = sort_errs(errs);
                    for e in errs {
                        out.push_str(format!("line {}: {}: {}\n", n, e.path, e.msg).as_str());
                    }
                }
            }
        }
    }
    out.push_str(format!("valid {} of {}\n", valid, total).as_str());
    Ok(out)
}

