fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
    let text = input.read_to_string("records.jsonl")?;
    let mut out: Vec<Str> = Vec::new();
    let mut recs: BTreeMap<Str, (i64, Str)> = BTreeMap::new();

    let mut n: i64 = 0;
    for line in text.split("\n") {
        n += 1;
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        let mut ok = false;
        match json::parse(t) {
            Ok(v) => {
                if let (Some(id), Some(ver)) = (v.get("id").and_then(|x| x.as_str()), v.get("version").and_then(|x| x.as_i64())) {
                    recs.insert(id.to_string(), (ver, t.to_string()));
                    ok = true;
                }
            }
            Err(_) => {}
        }
        if !ok {
            out.push(format!("line {} invalid", n));
        }
    }

    let mut synced: i64 = 0;
    let mut unchanged: i64 = 0;
    let mut rejected: i64 = 0;
    let mut failed: i64 = 0;

    for (id, (ver, body)) in recs.iter() {
        let key = format!("v:{}", id);
        let mut push = true;
        if let Some(s) = state.get(&key)? {
            if let Ok(last) = s.parse::<i64>() {
                if *ver <= last {
                    push = false;
                }
            }
        }
        if !push {
            unchanged += 1;
            out.push(format!("{} unchanged", id));
            continue;
        }
        let mut attempts = 0;
        let mut result = String::new();
        while attempts < 3 {
            attempts += 1;
            let path = format!("/records/{}", id);
            match api.put(&path, &[("content-type", "application/json")], body) {
                Ok(resp) => {
                    let st = resp.status;
                    if st >= 200 && st < 300 {
                        state.set(&key, &ver.to_string())?;
                        result = format!("{} synced", id);
                        synced += 1;
                        break;
                    } else if st >= 400 && st < 500 {
                        result = format!("{} rejected {}", id, st);
                        rejected += 1;
                        break;
                    }
                }
                Err(_) => {}
            }
        }
        if result.is_empty() {
            result = format!("{} failed", id);
            failed += 1;
        }
        out.push(result);
    }

    out.push(format!(
        "synced {} unchanged {} rejected {} failed {}",
        synced, unchanged, rejected, failed
    ));
    Ok(out.join("\n"))
}

