fn fmt_time(secs: i64) -> Str {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let yr = if m <= 2 { y + 1 } else { y };
    let hh = rem / 3600;
    let mm = (rem % 3600) / 60;
    let ss = rem % 60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", yr, m, d, hh, mm, ss)
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
    db.execute("CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last INTEGER NOT NULL, closed INTEGER NOT NULL)", &[])?;
    db.execute("CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", &[])?;

    let now = clock.now_millis() / 1000;
    let ts = fmt_time(now);
    let text = input.read_to_string("ops.txt")?;

    let mut ok: i64 = 0;
    let mut failed: i64 = 0;
    let mut dup: i64 = 0;
    let mut n: i64 = 0;

    for line in text.split("\n") {
        n += 1;
        let line = line.trim_end_matches("\r");
        if line.trim().is_empty() {
            continue;
        }
        let words: Vec<Str> = line.split(" ").collect();
        let mut err: Str = "".to_string();
        let mut is_dup = false;

        let op = words[0].as_str();
        if op == "open" && words.len() == 3 {
            match words[2].parse::<i64>() {
                Err(_) => { err = "malformed".to_string(); }
                Ok(c) => {
                    let name = words[1].clone();
                    if c < 0 {
                        err = "bad amount".to_string();
                    } else {
                        let rows = db.query("SELECT name FROM accounts WHERE name = ?", &[name.clone()])?;
                        if rows.len() > 0 {
                            err = "account exists".to_string();
                        } else {
                            db.execute("INSERT INTO accounts (name, balance, last, closed) VALUES (?, ?, ?, 0)", &[name, c, now])?;
                        }
                    }
                }
            }
        } else if op == "close" && words.len() == 2 {
            let name = words[1].clone();
            let rows = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", &[name.clone()])?;
            if rows.len() == 0 {
                err = format!("no account {}", name);
            } else if rows[0].get_i64(0) != 0 {
                err = "balance not zero".to_string();
            } else {
                db.execute("UPDATE accounts SET closed = 1, last = ? WHERE name = ?", &[now, name])?;
            }
        } else if op == "transfer" && words.len() == 5 {
            match words[4].parse::<i64>() {
                Err(_) => { err = "malformed".to_string(); }
                Ok(c) => {
                    let id = words[1].clone();
                    let from = words[2].clone();
                    let to = words[3].clone();
                    let prev = db.query("SELECT src, dst, cents FROM transfers WHERE id = ?", &[id.clone()])?;
                    if prev.len() > 0 {
                        if prev[0].get_str(0) == from && prev[0].get_str(1) == to && prev[0].get_i64(2) == c {
                            is_dup = true;
                        } else {
                            err = "id reused".to_string();
                        }
                    }
                    if !is_dup && err.is_empty() {
                        if c <= 0 {
                            err = "bad amount".to_string();
                        } else if from == to {
                            err = "same account".to_string();
                        } else {
                            let fr = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", &[from.clone()])?;
                            if fr.len() == 0 {
                                err = format!("no account {}", from);
                            } else {
                                let tr = db.query("SELECT balance FROM accounts WHERE name = ? AND closed = 0", &[to.clone()])?;
                                if tr.len() == 0 {
                                    err = format!("no account {}", to);
                                } else {
                                    let fb = fr[0].get_i64(0);
                                    let tb = tr[0].get_i64(0);
                                    if fb < c {
                                        err = "insufficient funds".to_string();
                                    } else if tb > 9223372036854775807 - c {
                                        err = "overflow".to_string();
                                    } else {
                                        db.execute("UPDATE accounts SET balance = ?, last = ? WHERE name = ?", &[fb - c, now, from.clone()])?;
                                        db.execute("UPDATE accounts SET balance = ?, last = ? WHERE name = ?", &[tb + c, now, to.clone()])?;
                                        db.execute("INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)", &[id, from, to, c])?;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            err = "malformed".to_string();
        }

        if is_dup {
            dup += 1;
        } else if err.is_empty() {
            ok += 1;
        } else {
            failed += 1;
            log.append(&format!("{} line {}: {}", ts, n, err))?;
        }
    }

    let mut out = format!("ok {} failed {} duplicate {}", ok, failed, dup);
    let rows = db.query("SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY name", &[])?;
    for r in rows {
        out.push_str(&format!("\n{} {} last {}", r.get_str(0), r.get_i64(1), fmt_time(r.get_i64(2))));
    }
    Ok(out)
}

