fn json_str_field(body: &Str, key: &Str) -> Option<Str> {
    let pat = format("\"{}\"", key);
    let idx = body.find(&pat)?;
    let rest = body.slice_from(idx + pat.len());
    let rest = rest.trim_start();
    if !rest.starts_with(":") { return None; }
    let rest = rest.slice_from(1).trim_start();
    if !rest.starts_with("\"") { return None; }
    let mut out = String::new();
    let mut esc = false;
    let chars = rest.slice_from(1).chars();
