        if t.is_none() { return err(res, 401, "unauthorized"); }
        let t = t.unwrap();
        let name = session_name(store, clock, t.clone(), false);
        if name.is_none() { return err(res, 401, "unauthorized"); }
        store.delete("s:" + t);
        return reply(res, 204, "");
    }

    err(res, 404, "not found")
}

fn tail(s: Str, i: Int) -> Str {
    s.slice(i, s.len())
}

fn json_str_field(body: Str, key: Str) -> Option<Str> {
    let pat = "\"" + key + "\"";
    let idx = body.find(pat)?;
    let rest = tail(body, idx + pat.len());
    let rest = rest.trim();
    if !rest.starts_with(":") { return None; }
    let rest = tail(rest, 1).trim();
    if !rest.starts_with("\"") { return None; }
    let mut out = "";
    let mut esc = false;
    let chars = tail(rest, 1).chars();
    for c in chars {
        if esc {
            if c == "n" { out = out + "\n"; } else { out = out + c; }
            esc = false;
        } else if c == "\\" {
            esc = true;
        } else if c == "\"" {
            return Some(out);
        } else {
            out = out + c;
        }
    }
    None
}

fn valid_name(n: Str) -> Bool {
    let len = n.chars().len();
    if len < 3 || len > 20 { return false; }
    let allowed = "abcdefghijklmnopqrstuvwxyz0123456789_";
    for c in n.chars() {
        if !allowed.contains(c) { return false; }
    }
    true
}

fn reply(res: Outgoing, status: Int, body: Str) -> Str {
    if status == 204 {
        res.send(status, "");
        return "";
    }
    res.send(status, body);
    ""
}

fn err(res: Outgoing, status: Int, msg: Str) -> Str {
    reply(res, status, "{\"error\": \"" + msg + "\"}")
}

fn bearer(req: Incoming) -> Option<Str> {
    let names = req.header_names();
    let values = req.header_values();
    let mut i = 0;
    let n = names.len();
    while i < n {
        if names[i].to_lowercase() == "authorization" {
            let h = values[i];
            if !h.starts_with("Bearer ") { return None; }
            let t = tail(h, 7);
            if t.len() == 0 { return None; }
            return Some(t);
        }
        i += 1;
    }
    None
}

// user record: hash|fails|locked_until|logins
fn parse_rec(s: Str) -> List<Str> {
    s.split("|")
}

// session record: name|expiry
fn session_name(store: Kv, clock: Clock, token: Str, touch: Bool) -> Option<Str> {
    let key = "s:" + token;
    let v = store.get(key)?;
    let parts: List<Str> = v.split("|");
    let name = parts[0];
    let exp: Int = parts[1].parse_int()?;
    let now = clock.now();
    if now >= exp {
        store.delete(key);
        return None;
    }
    if touch {
        store.set(key, name + "|" + (now + 1800000).to_string());
    }
    Some(name)
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
    let method = req.method();
    let target = req.target();
    let path = match target.find("?") {
        Some(i) => target.slice(0, i),
        None => target,
    };

    if method == "POST" && path == "/users" {
        let body = req.body();
        let name = json_str_field(body, "name");
        let pw = json_str_field(body, "password");
        if name.is_none() || pw.is_none() { return err(res, 400, "invalid"); }
        let name = name.unwrap();
        let pw = pw.unwrap();
        if !valid_name(name) || pw.len() < 8 { return err(res, 400, "invalid"); }
        let key = "u:" + name;
        if store.get(key).is_some() { return err(res, 409, "name taken"); }
        let h = sha256_hex(pw);
        store.set(key, h + "|0|0|0");
        return reply(res, 201, "{\"name\": \"" + name + "\"}");
    }

    if method == "POST" && path == "/login" {
        let body = req.body();
        let name = json_str_field(body, "name");
        let pw = json_str_field(body, "password");
        if name.is_none() || pw.is_none() { return err(res, 401, "bad credentials"); }
        let name = name.unwrap();
        let pw = pw.unwrap();
        let key = "u:" + name;
        let rec = store.get(key);
        if rec.is_none() { return err(res, 401, "bad credentials"); }
        let p = parse_rec(rec.unwrap());
        let hash = p[0];
        let mut fails: Int = p[1].parse_int().unwrap_or(0);
        let locked: Int = p[2].parse_int().unwrap_or(0);
        let mut logins: Int = p[3].parse_int().unwrap_or(0);
        let now = clock.now();
        if now < locked { return err(res, 429, "locked"); }
        if sha256_hex(pw) != hash {
            fails += 1;
            let mut lock_until = locked;
            if fails >= 3 {
                lock_until = now + 900000;
                fails = 0;
            }
            store.set(key, hash + "|" + fails.to_string() + "|" + lock_until.to_string() + "|" + logins.to_string());
            return err(res, 401, "bad credentials");
        }
        logins += 1;
        store.set(key, hash + "|0|" + locked.to_string() + "|" + logins.to_string());
        let bytes = rng.bytes(16);
        let token = hex_encode(bytes);
        store.set("s:" + token, name + "|" + (now + 1800000).to_string());
        return reply(res, 200, "{\"token\": \"" + token + "\", \"expires_in\": 1800}");
    }

    if method == "GET" && path == "/me" {
        let t = bearer(req);
        if t.is_none() { return err(res, 401, "unauthorized"); }
        let name = session_name(store, clock, t.unwrap(), true);
        if name.is_none() { return err(res, 401, "unauthorized"); }
        let name = name.unwrap();
        let rec = store.get("u:" + name);
        if rec.is_none() { return err(res, 401, "unauthorized"); }
        let p = parse_rec(rec.unwrap());
        let logins: Int = p[3].parse_int().unwrap_or(0);
        return reply(res, 200, "{\"name\": \"" + name + "\", \"logins\": " + logins.to_string() + "}");
    }

    if method == "POST" && path == "/logout" {
        let t = bearer(req);
        if t.is_none() { return err(res, 401, "unauthorized"); }
        let t = t.unwrap();
        let name = session_name(store, clock, t, false);
        if name.is_none() { return err(res, 401, "unauthorized"); }
        store.delete("s:" + t);
        return reply(res, 204, "");
    }

    err(res, 404, "not found")
}

