        ("id", json::str("pay_" + row.get_int(0).to_string())),
        ("account", json::str(row.get_str(1))),
        ("cents", json::int(row.get_int(2))),
        ("currency", json::str(row.get_str(3))),
        ("status", json::str(row.get_str(4))),
        ("refunded", json::int(row.get_int(5)))
    ])
}

fn load(db: Db, id: i64) -> Option<Row> {
    let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = ?", [id]);
    rows.first()
}

fn parse_id(s: Str) -> Option<i64> {
    if s.len() == 0 { return None; }
    for c in s.chars() {
        if !c.is_ascii_digit() { return None; }
    }
    s.parse_int()
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
    db.execute("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", []);
    db.execute("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", []);

    let method = req.method();
    let path = req.path();
    let parts: Vec<Str> = path.split("/").filter(|p| p.len() > 0).collect();
    let n = parts.len();

    if n == 0 || parts[0] != "payments" {
        return err(res, 404, "not found");
    }

    // GET routes
    if method == "GET" {
        if n == 1 {
            let account = req.query("account").unwrap_or("");
            let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY id ASC", [account]);
            let items: Vec<Json> = rows.iter().map(|r| pay_json(r)).collect();
            return respond(res, 200, json::stringify(json::array(items)));
        }
        if n == 2 {
            let id = parse_id(parts[1]);
            if id.is_none() { return err(res, 404, "not found"); }
            return match load(db, id.unwrap()) {
                Some(r) => respond(res, 200, json::stringify(pay_json(r))),
                None => err(res, 404, "not found"),
            };
        }
        return err(res, 404, "not found");
    }

    if method != "POST" { return err(res, 404, "not found"); }

    // Determine route
    let mut kind = 0; // 1 create, 2 capture, 3 cancel, 4 refund
    let mut id: i64 = 0;
    if n == 1 {
        kind = 1;
    } else if n == 3 {
        let pid = parse_id(parts[1]);
        if pid.is_none() { return err(res, 404, "not found"); }
        id = pid.unwrap();
        if parts[2] == "capture" { kind = 2; }
        else if parts[2] == "cancel" { kind = 3; }
        else if parts[2] == "refund" { kind = 4; }
    }
    if kind == 0 { return err(res, 404, "not found"); }

    let needs_key = kind == 1 || kind == 4;
    let key = req.header("idempotency-key");
    if needs_key && (key.is_none() || key.unwrap().len() == 0) {
        return err(res, 400, "missing idempotency key");
    }

    if kind != 1 {
        if load(db, id).is_none() { return err(res, 404, "not found"); }
    }

    let raw = req.body();
    let parsed = json::parse(raw);
    let canon = match parsed {
        Ok(v) => json::stringify(v),
        Err(_) => "",
    };

    if needs_key {
        let k = key.unwrap();
        let prev = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [k]);
        if prev.len() > 0 {
            let p = prev[0];
            if p.get_str(0) == method && p.get_str(1) == path && p.get_str(2) == canon && parsed.is_ok() {
                return respond(res, p.get_int(3), p.get_str(4));
            }
            return err(res, 409, "key reused");
        }
    }

    let mut status: i64 = 0;
    let mut out: Str = "";

    if kind == 1 {
        let mut ok = false;
        let mut account = "";
        let mut cents: i64 = 0;
        let mut currency = "";
        if let Ok(v) = parsed {
            if v.is_object() && v.keys().len() == 3 {
                let a = v.get("account");
                let c = v.get("cents");
                let cu = v.get("currency");
                if a.is_some() && c.is_some() && cu.is_some() {
                    let a = a.unwrap();
                    let c = c.unwrap();
                    let cu = cu.unwrap();
                    if a.is_str() && a.as_str().len() > 0 && c.is_int() && c.as_int() > 0
                        && cu.is_str() && (cu.as_str() == "EUR" || cu.as_str() == "USD") {
                        ok = true;
                        account = a.as_str();
                        cents = c.as_int();
                        currency = cu.as_str();
                    }
                }
            }
        }
        if !ok { return err(res, 422, "invalid payment"); }
        db.execute("INSERT INTO payments (account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0)", [account, cents, currency]);
        let nid = db.last_insert_id();
        status = 201;
        out = json::stringify(pay_json(load(db, nid).unwrap()));
    } else if kind == 2 {
        let row = load(db, id).unwrap();
        let st = row.get_str(4);
        if st == "pending" {
            db.execute("UPDATE payments SET status = 'captured' WHERE id = ?", [id]);
        } else if st != "captured" {
            return err(res, 409, "invalid transition");
        }
        status = 200;
        out = json::stringify(pay_json(load(db, id).unwrap()));
    } else if kind == 3 {
        let row = load(db, id).unwrap();
        if row.get_str(4) != "pending" { return err(res, 409, "invalid transition"); }
        db.execute("UPDATE payments SET status = 'canceled' WHERE id = ?", [id]);
        status = 200;
        out = json::stringify(pay_json(load(db, id).unwrap()));
    } else {
        let mut amount: i64 = 0;
        let mut ok = false;
        if let Ok(v) = parsed {
            if v.is_object() && v.keys().len() == 1 {
                let c = v.get("cents");
                if c.is_some() && c.unwrap().is_int() && c.unwrap().as_int() > 0 {
                    ok = true;
                    amount = c.unwrap().as_int();
                }
            }
        }
        if !ok { return err(res, 422, "invalid refund"); }
        let row = load(db, id).unwrap();
        if row.get_str(4) != "captured" { return err(res, 409, "invalid transition"); }
        let total = row.get_int(2);
        let refunded = row.get_int(5);
        if refunded + amount > total { return err(res, 409, "exceeds captured"); }
        let nr = refunded + amount;
        if nr == total {
            db.execute("UPDATE payments SET refunded = ?, status = 'refunded' WHERE id = ?", [nr, id]);
        } else {
            db.execute("UPDATE payments SET refunded = ? WHERE id = ?", [nr, id]);
        }
        status = 200;
        out = json::stringify(pay_json(load(db, id).unwrap()));
    }

    if needs_key {
        db.execute("INSERT INTO idem (key, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)",
            [key.unwrap(), method, path, canon, status, out]);
    }
    respond(res, status, out)
}

