        for (p, c) in page_counts.iter() {
            pv.push((p.clone(), *c));
        }
        pv.sort_by(|a, b| {
            if a.1 != b.1 {
                b.1.cmp(&a.1)
            } else {
                a.0.cmp(&b.0)
            }
        });
        let mut parts: Vec<String> = Vec::new();
        let mut k = 0;
        while k < pv.len() && k < 3 {
            parts.push(format!("{} ({})", pv[k].0, pv[k].1));
            k += 1;
        }
        out.push_str(&format!("top: {}\n", parts.join(", ")));
    }

    out.push_str(&format!("malformed {} duplicates {}", malformed, dups));
    Ok(out)
}

