        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let yy = if m <= 2 { y - 1 } else { y };
    let era = if yy >= 0 { yy / 400 } else { (yy - 399) / 400 };
    let yoe = yy - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn to_i(x: u8) -> i64 {
    i64::from(x)
}

fn num(b: Vec<u8>, s: usize, e: usize) -> i64 {
    let mut v: i64 = 0;
    let mut i = s;
    while i < e {
        v = v * 10 + (to_i(b[i]) - 48);
        i += 1;
    }
    v
}

fn parse_time(t: Str) -> Option<i64> {
    let b = t.as_bytes();
    if b.len() != 20 {
        return None;
    }
    let mut i = 0;
    while i < 20 {
        let c = to_i(b[i]);
        let ok = if i == 4 || i == 7 {
            c == 45
        } else if i == 10 {
            c == 84
        } else if i == 13 || i == 16 {
            c == 58
        } else if i == 19 {
            c == 90
        } else {
            c >= 48 && c <= 57
        };
        if !ok {
            return None;
        }
        i += 1;
    }
    let y = num(b.clone(), 0, 4);
    let mo = num(b.clone(), 5, 7);
    let d = num(b.clone(), 8, 10);
    let h = num(b.clone(), 11, 13);
    let mi = num(b.clone(), 14, 16);
    let s = num(b.clone(), 17, 19);
    if mo < 1 || mo > 12 {
        return None;
    }
    if d < 1 || d > days_in_month(y, mo) {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }
    Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s)
}

fn fmt_dur(d: i64) -> Str {
    format!("{:02}:{:02}:{:02}", d / 3600, (d % 3600) / 60, d % 60)
}

fn main(input: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("events.log")?;
    let mut seen: std::collections::HashSet<Str> = std::collections::HashSet::new();
    let mut times: std::collections::BTreeMap<Str, Vec<i64>> = std::collections::BTreeMap::new();
    let mut pages: std::collections::BTreeMap<Str, std::collections::HashSet<Str>> = std::collections::BTreeMap::new();
    let mut page_counts: std::collections::BTreeMap<Str, i64> = std::collections::BTreeMap::new();
    let mut malformed: i64 = 0;
    let mut dups: i64 = 0;

    for line in text.split("\n") {
        if line.is_empty() {
            continue;
        }
        let fields: Vec<Str> = line.split(" ").collect();
        if fields.len() != 3 {
            malformed += 1;
            continue;
        }
        let t = match parse_time(fields[0].clone()) {
            Some(v) => v,
            None => {
                malformed += 1;
                continue;
            }
        };
        if seen.contains(line.clone()) {
            dups += 1;
            continue;
        }
        seen.insert(line.clone());
        let user = fields[1].clone();
        let page = fields[2].clone();
        times.entry(user.clone()).or_insert_with(Vec::new).push(t);
        pages.entry(user).or_insert_with(std::collections::HashSet::new).insert(page.clone());
        let cur = match page_counts.get(page.clone()) {
            Some(v) => v,
            None => 0,
        };
        page_counts.insert(page, cur + 1);
    }

    let mut out = String::new();
    let mut all_durs: Vec<i64> = Vec::new();

    for (user, ts0) in times.iter() {
        let mut ts = ts0.clone();
        ts.sort();
        let mut sessions: i64 = 0;
        let mut longest: i64 = 0;
        let mut start = ts[0];
        let mut prev = ts[0];
        sessions += 1;
        let mut i = 1;
        while i < ts.len() {
            let t = ts[i];
            if t - prev > 1800 {
                let d = prev - start;
                all_durs.push(d);
                if d > longest {
                    longest = d;
                }
                sessions += 1;
                start = t;
            }
            prev = t;
            i += 1;
        }
        let d = prev - start;
        all_durs.push(d);
        if d > longest {
            longest = d;
        }
        let pc = match pages.get(user.clone()) {
            Some(s) => s.len(),
            None => 0,
        };
        out.push_str(format!(
            "{} sessions {} events {} longest {} pages {}\n",
            user,
            sessions,
            ts.len(),
            fmt_dur(longest),
            pc
        ));
    }

    if !all_durs.is_empty() {
        all_durs.sort();
        let med = all_durs[(all_durs.len() - 1) / 2];
        out.push_str(format!("median {}\n", med));
        let mut pv: Vec<(Str, i64)> = Vec::new();
        for (p, c) in page_counts.iter() {
            pv.push((p.clone(), c));
        }
        pv.sort_by(|a, b| {
            if a.1 != b.1 {
                b.1.cmp(a.1)
            } else {
                a.0.cmp(b.0)
            }
        });
        let mut parts: Vec<Str> = Vec::new();
        let mut k = 0;
        while k < pv.len() && k < 3 {
            parts.push(format!("{} ({})", pv[k].0, pv[k].1));
            k += 1;
        }
        out.push_str(format!("top: {}\n", parts.join(", ")));
    }

    out.push_str(format!("malformed {} duplicates {}", malformed, dups));
    Ok(out)
}

fn push_field(out: &mut String, f: &String) {
    let mut need = false;
    for c in f.chars() {
        if c == ',' || c == '"' || c == '\r' || c == '\n' {
            need = true;
        }
    }
    if need {
        out.push('"');
        for c in f.chars() {
            if c == '"' {
                out.push('"');
            }
            out.push(c);
        }
        out.push('"');
    } else {
        out.push_str(f.as_str());
    }
}

fn parse_qty(s: &String) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut neg = false;
    if cs.len() > 0 && cs[0] == '-' {
        neg = true;
        i = 1;
    }
    if i >= cs.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < cs.len() {
        let c = cs[i];
        if c < '0' || c > '9' {
            return None;
        }
        v = v * 10 + ((c as i64) - ('0' as i64));
        i += 1;
    }
    if neg {
        Some(0 - v)
    } else {
        Some(v)
    }
}

fn parse_price(s: &String) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut whole: i64 = 0;
    while i < cs.len() && cs[i] >= '0' && cs[i] <= '9' {
        whole = whole * 10 + ((cs[i] as i64) - ('0' as i64));
        i += 1;
    }
    if i == 0 {
        return None;
    }
    if i == cs.len() {
        return Some(whole * 100);
    }
    if cs[i] != '.' {
        return None;
    }
    i += 1;
    let nd = cs.len() - i;
    if nd < 1 || nd > 2 {
        return None;
    }
    let mut frac: i64 = 0;
    while i < cs.len() {
        if cs[i] < '0' || cs[i] > '9' {
            return None;
        }
        frac = frac * 10 + ((cs[i] as i64) - ('0' as i64));
        i += 1;
    }
    if nd == 1 {
        frac = frac * 10;
    }
    Some(whole * 100 + frac)
}

fn money(v: i64) -> String {
    let mut s = String::new();
    let mut a = v;
    if v < 0 {
        s.push('-');
        a = 0 - v;
    }
    let w = a / 100;
    let f = a % 100;
    s.push_str(w.to_string().as_str());
    s.push('.');
    if f < 10 {
        s.push('0');
    }
    s.push_str(f.to_string().as_str());
    s
}

struct Region {
    name: String,
    items: i64,
    prods: Vec<(String, i64)>,
}

fn main(input: Dir, out: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("sales.csv")?;
    let cs: Vec<char> = text.chars().collect();
    let n = cs.len();
    let mut records: Vec<(Vec<String>, bool)> = Vec::new();
    let mut i = 0;
    while i < n {
        if cs[i] == '\n' {
            i += 1;
            continue;
        }
        if cs[i] == '\r' && i + 1 < n && cs[i + 1] == '\n' {
            i += 2;
            continue;
        }
        let mut fields: Vec<String> = Vec::new();
        let mut cur = String::new();
        let mut bad = false;
        // parse one record
        loop {
            // field start
            let mut ended = false; // record ended after this field
            if i < n && cs[i] == '"' {
                i += 1;
                let mut closed = false;
                while i < n {
                    if cs[i] == '"' {
                        if i + 1 < n && cs[i + 1] == '"' {
                            cur.push('"');
                            i += 2;
                        } else {
                            i += 1;
                            closed = true;
                            break;
                        }
                    } else {
                        cur.push(cs[i]);
                        i += 1;
                    }
                }
                if !closed {
                    bad = true;
                    ended = true;
                } else if i >= n {
                    ended = true;
                } else if cs[i] == ',' {
                    i += 1;
                } else if cs[i] == '\n' {
                    i += 1;
                    ended = true;
                } else if cs[i] == '\r' && i + 1 < n && cs[i + 1] == '\n' {
                    i += 2;
                    ended = true;
                } else {
                    bad = true;
                    while i < n && cs[i] != '\n' {
                        i += 1;
                    }
                    if i < n {
                        i += 1;
                    }
                    ended = true;
                }
            } else {
                let mut done = false;
                while !done {
                    if i >= n {
                        ended = true;
                        done = true;
                    } else if cs[i] == ',' {
                        i += 1;
                        done = true;
                    } else if cs[i] == '\n' {
                        i += 1;
                        ended = true;
                        done = true;
                    } else if cs[i] == '\r' && i + 1 < n && cs[i + 1] == '\n' {
                        i += 2;
                        ended = true;
                        done = true;
                    } else if cs[i] == '"' {
                        bad = true;
                        cur.push('"');
                        i += 1;
                    } else {
                        cur.push(cs[i]);
                        i += 1;
                    }
                }
            }
            fields.push(cur.clone());
            cur = String::new();
            if ended {
                break;
            }
        }
        records.push((fields, bad));
    }

    let mut clean = String::new();
    clean.push_str("region,product,qty,price,note\n");
    let mut regions: Vec<Region> = Vec::new();
    let mut bads: Vec<usize> = Vec::new();
    let mut count: usize = 0;
    let mut r = 1;
    while r < records.len() {
        count += 1;
        let fields = &records[r].0;
        let mut ok = !records[r].1;
        let mut qty: i64 = 0;
        let mut cents: i64 = 0;
        if ok {
            if fields.len() != 5 {
                ok = false;
            }
        }
        if ok {
            if fields[0].len() == 0 || fields[1].len() == 0 {
                ok = false;
            }
        }
        if ok {
            match parse_qty(&fields[2]) {
                Some(q) => {
                    qty = q;
                }
                None => {
                    ok = false;
                }
            }
        }
        if ok {
            match parse_price(&fields[3]) {
                Some(p) => {
                    cents = p;
                }
                None => {
                    ok = false;
                }
            }
        }
        if !ok {
            bads.push(count);
            r += 1;
            continue;
        }
        push_field(&mut clean, &fields[0]);
        clean.push(',');
        push_field(&mut clean, &fields[1]);
        clean.push(',');
        push_field(&mut clean, &fields[2]);
        clean.push(',');
        clean.push_str(money(cents).as_str());
        clean.push(',');
        push_field(&mut clean, &fields[4]);
        clean.push('\n');

        let rev = qty * cents;
        let mut ri = regions.len();
        let mut k = 0;
        while k < regions.len() {
            if regions[k].name == fields[0] {
                ri = k;
            }
            k += 1;
        }
        if ri == regions.len() {
            regions.push(Region {
                name: fields[0].clone(),
                items: 0,
                prods: Vec::new(),
            });
        }
        regions[ri].items += qty;
        let mut pi = regions[ri].prods.len();
        let mut j = 0;
        while j < regions[ri].prods.len() {
            if regions[ri].prods[j].0 == fields[1] {
                pi = j;
            }
            j += 1;
        }
        if pi == regions[ri].prods.len() {
            regions[ri].prods.push((fields[1].clone(), 0));
        }
        regions[ri].prods[pi].1 += rev;
        r += 1;
    }

    out.write("clean.csv", clean)?;

    // sort regions by name (selection sort)
    let mut a = 0;
    while a < regions.len() {
        let mut m = a;
        let mut b = a + 1;
        while b < regions.len() {
            if regions[b].name < regions[m].name {
                m = b;
            }
            b += 1;
        }
        if m != a {
            regions.swap(a, m);
        }
        a += 1;
    }

    let mut res = String::new();
    for reg in regions.iter() {
        let mut total: i64 = 0;
        let mut best = 0;
        let mut p = 0;
        while p < reg.prods.len() {
            total += reg.prods[p].1;
            if reg.prods[p].1 > reg.prods[best].1
                || (reg.prods[p].1 == reg.prods[best].1 && reg.prods[p].0 < reg.prods[best].0)
            {
                best = p;
            }
            p += 1;
        }
        res.push_str(reg.name.as_str());
        res.push_str(" revenue ");
        res.push_str(money(total).as_str());
        res.push_str(" items ");
        res.push_str(reg.items.to_string().as_str());
        res.push_str(" top ");
        res.push_str(reg.prods[best].0.as_str());
        res.push('\n');
    }
    res.push_str("records ");
    res.push_str(count.to_string().as_str());
    res.push_str(" bad ");
    res.push_str(bads.len().to_string().as_str());
    if bads.len() > 0 {
        res.push_str(": ");
        let mut q = 0;
        while q < bads.len() {
            if q > 0 {
                res.push_str(", ");
            }
            res.push_str(bads[q].to_string().as_str());
            q += 1;
        }
    }
    res.push('\n');
    Ok(res)
}

