fn push_field(out0: Str, f: Str) -> Str {
    let mut out = out0;
    let bs = f.as_bytes();
    let mut need = false;
    let mut i = 0;
    while i < bs.len() {
        let c = bs[i];
        if c == 44 || c == 34 || c == 13 || c == 10 {
            need = true;
        }
        i += 1;
    }
    if need {
        out.push_str("\"");
        let mut start = 0;
        let mut k = 0;
        while k < bs.len() {
            if bs[k] == 34 {
                out.push_str(&f[start..k]);
                out.push_str("\"\"");
                start = k + 1;
            }
            k += 1;
        }
        out.push_str(&f[start..bs.len()]);
        out.push_str("\"");
    } else {
