fn parse_qty(s: Str) -> Option<i64> {
    let cs = s.as_bytes();
    let mut i = 0;
    let mut neg = false;
    if cs.len() > 0 && cs[0] == 45 {
        neg = true;
        i = 1;
    }
    if i >= cs.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < cs.len() {
        let c = cs[i];
        if c < 48 || c > 57 {
            return None;
        }
        v = v * 10 + ((c as i64) - 48);
        i += 1;
    }
    if neg {
        Some(0 - v)
    } else {
