fn parse_price(s: Str) -> Option<i64> {
    let cs = s.as_bytes();
    let mut i = 0;
    let mut whole: i64 = 0;
    while i < cs.len() && cs[i] >= 48 && cs[i] <= 57 {
        whole = whole * 10 + ((cs[i] as i64) - 48);
        i += 1;
    }
    if i == 0 {
        return None;
    }
    if i == cs.len() {
        return Some(whole * 100);
    }
    if cs[i] != 46 {
        return None;
    }
    i += 1;
    let nd = cs.len() - i;
    if nd < 1 || nd > 2 {
        return None;
    }
    let mut frac: i64 = 0;
    while i < cs.len() {
        if cs[i] < 48 || cs[i] > 57 {
            return None;
        }
        frac = frac * 10 + ((cs[i] as i64) - 48);
        i += 1;
    }
    if nd == 1 {
        frac = frac * 10;
    }
    Some(whole * 100 + frac)
}

