    if i == cs.len() {
        return Some(whole * 100);
    }
    if cs[i] != 46 {
        return None;
    }
    i += 1;
    let nd = cs.len() - i;
    if nd < 1 || nd > 2 {
        return None;
    }
    let mut frac: i64 = 0;
    while i < cs.len() {
        if cs[i] < 48 || cs[i] > 57 {
            return None;
        }
        frac = frac * 10 + ((cs[i] as i64) - 48);
        i += 1;
    }
    if nd == 1 {
        frac = frac * 10;
    }
    Some(whole * 100 + frac)
}

fn money(v: i64) -> Str {
    let mut s = String::new();
    let mut a = v;
    if v < 0 {
        s.push_str("-");
        a = 0 - v;
    }
    let w = a / 100;
    let f = a % 100;
    s.push_str(w.to_string());
    s.push_str(".");
    if f < 10 {
        s.push_str("0");
    }
    s.push_str(f.to_string());
    s
}

struct Region {
    name: Str,
    items: i64,
    prods: Vec<(Str, i64)>,
}

fn main(input: Dir, out: Dir) -> Result<Str, Error> {
    let text = input.read_to_string("sales.csv")?;
    let cs = text.as_bytes();
    let n = cs.len();
    let mut records: Vec<(Vec<Str>, bool)> = Vec::new();
    let mut i = 0;
    while i < n {
        if cs[i] == 10 {
            i += 1;
            continue;
        }
        if cs[i] == 13 && i + 1 < n && cs[i + 1] == 10 {
            i += 2;
            continue;
        }
        let mut fields: Vec<Str> = Vec::new();
        let mut bad = false;
        loop {
            let mut cur = String::new();
            let mut ended = false;
            if i < n && cs[i] == 34 {
                i += 1;
                let mut st = i;
                let mut closed = false;
                while i < n {
                    if cs[i] == 34 {
                        if i + 1 < n && cs[i + 1] == 34 {
                            cur.push_str(sub(text.clone(), st, i + 1));
                            i += 2;
                            st = i;
                        } else {
                            cur.push_str(sub(text.clone(), st, i));
                            i += 1;
                            closed = true;
                            break;
                        }
                    } else {
                        i += 1;
                    }
                }
                if !closed {
                    cur.push_str(sub(text.clone(), st, n));
                    bad = true;
                    ended = true;
                } else if i >= n {
                    ended = true;
                } else if cs[i] == 44 {
                    i += 1;
                } else if cs[i] == 10 {
                    i += 1;
                    ended = true;
                } else if cs[i] == 13 && i + 1 < n && cs[i + 1] == 10 {
                    i += 2;
                    ended = true;
                } else {
                    bad = true;
                    while i < n && cs[i] != 10 {
                        i += 1;
                    }
                    if i < n {
                        i += 1;
                    }
                    ended = true;
                }
            } else {
                let st = i;
                let mut done = false;
                let mut en = i;
                while !done {
                    if i >= n {
                        en = i;
                        ended = true;
                        done = true;
                    } else if cs[i] == 44 {
                        en = i;
                        i += 1;
                        done = true;
                    } else if cs[i] == 10 {
                        en = i;
                        i += 1;
                        ended = true;
                        done = true;
                    } else if cs[i] == 13 && i + 1 < n && cs[i + 1] == 10 {
                        en = i;
                        i += 2;
                        ended = true;
                        done = true;
                    } else if cs[i] == 34 {
                        bad = true;
                        i += 1;
                    } else {
                        i += 1;
                    }
                }
                cur.push_str(sub(text.clone(), st, en));
            }
            fields.push(cur);
            if ended {
                break;
            }
        }
        records.push((fields, bad));
    }

    let mut clean = String::new();
    clean.push_str("region,product,qty,price,note\n");
    let mut regions: Vec<Region> = Vec::new();
    let mut bads: Vec<usize> = Vec::new();
    let mut count: usize = 0;
    let mut r = 1;
    while r < records.len() {
        count += 1;
        let fields = records[r].0.clone();
        let mut ok = !records[r].1;
        let mut qty: i64 = 0;
        let mut cents: i64 = 0;
        if ok {
            if fields.len() != 5 {
                ok = false;
            }
        }
        if ok {
            if fields[0].len() == 0 || fields[1].len() == 0 {
                ok = false;
            }
        }
        if ok {
            match parse_qty(fields[2].clone()) {
                Some(q) => {
                    qty = q;
                }
                None => {
                    ok = false;
                }
            }
        }
        if ok {
            match parse_price(fields[3].clone()) {
                Some(p) => {
                    cents = p;
                }
                None => {
                    ok = false;
                }
            }
        }
        if !ok {
            bads.push(count);
            r += 1;
            continue;
        }
        clean = push_field(clean, fields[0].clone());
        clean.push_str(",");
        clean = push_field(clean, fields[1].clone());
        clean.push_str(",");
        clean = push_field(clean, fields[2].clone());
        clean.push_str(",");
        clean.push_str(money(cents));
        clean.push_str(",");
        clean = push_field(clean, fields[4].clone());
        clean.push_str("\n");

        let rev = qty * cents;
        let mut ri = regions.len();
        let mut k = 0;
        while k < regions.len() {
            if regions[k].name == fields[0] {
                ri = k;
            }
            k += 1;
        }
        if ri == regions.len() {
            regions.push(Region {
                name: fields[0].clone(),
                items: 0,
                prods: Vec::new(),
            });
        }
        regions[ri].items += qty;
        let mut pi = regions[ri].prods.len();
        let mut j = 0;
        while j < regions[ri].prods.len() {
            if regions[ri].prods[j].0 == fields[1] {
                pi = j;
            }
            j += 1;
        }
        if pi == regions[ri].prods.len() {
            regions[ri].prods.push((fields[1].clone(), 0));
        }
        regions[ri].prods[pi].1 += rev;
        r += 1;
    }

    out.write("clean.csv", clean)?;

    let mut a = 0;
    while a < regions.len() {
        let mut m = a;
        let mut b = a + 1;
        while b < regions.len() {
            if regions[b].name < regions[m].name {
                m = b;
            }
            b += 1;
        }
        if m != a {
            regions.swap(a, m);
        }
        a += 1;
    }

    let mut res = String::new();
    let mut x = 0;
    while x < regions.len() {
        let mut total: i64 = 0;
        let mut best = 0;
        let mut p = 0;
        while p < regions[x].prods.len() {
            total += regions[x].prods[p].1;
            if regions[x].prods[p].1 > regions[x].prods[best].1
                || (regions[x].prods[p].1 == regions[x].prods[best].1
                    && regions[x].prods[p].0 < regions[x].prods[best].0)
            {
                best = p;
            }
            p += 1;
        }
        res.push_str(regions[x].name.clone());
        res.push_str(" revenue ");
        res.push_str(money(total));
        res.push_str(" items ");
        res.push_str(regions[x].items.to_string());
        res.push_str(" top ");
        res.push_str(regions[x].prods[best].0.clone());
        res.push_str("\n");
        x += 1;
    }
    res.push_str("records ");
    res.push_str(count.to_string());
    res.push_str(" bad ");
    res.push_str(bads.len().to_string());
    if bads.len() > 0 {
        res.push_str(": ");
        let mut q = 0;
        while q < bads.len() {
            if q > 0 {
                res.push_str(", ");
            }
            res.push_str(bads[q].to_string());
            q += 1;
        }
    }
    res.push_str("\n");
    Ok(res)
}

fn is_word_char(c: char) -> bool {
