}

fn words_of(text: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    for c in text.chars() {
        if is_word_char(c) {
            cur.push(c);
        } else if !cur.is_empty() {
            out.push(cur.to_lowercase());
            cur = String::new();
        }
    }
    if !cur.is_empty() {
        out.push(cur.to_lowercase());
    }
    out.sort();
    out.dedup();
    out
}

