fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
    let mut out = String::new();
    let mut current: Vec<String> = docs.files()?;
    current.sort();
    let old: Vec<String> = get_list(&index, "files");
    let mut unchanged = 0;

    // removed and changed/added
    let mut events: Vec<String> = Vec::new();
    for p in old.iter() {
        if !current.contains(p) {
            events.push(format!("removed {}", p));
        }
    }
    for p in current.iter() {
        let text = docs.read(p)?;
        let key = format!("c:{}", p);
        let prev = index.get(&key);
        let kind = match prev {
            None => "added",
            Some(ref t) => {
                if *t == text { "same" } else { "changed" }
            }
        };
        if kind == "same" {
            unchanged += 1;
        } else {
            events.push(format!("{} {}", kind, p));
        }
    }
    // events sorted by path: build by path order
    let mut lines: Vec<(String, String)> = Vec::new();
    for e in events.iter() {
        let sp = e.find(" ").unwrap();
        let path = e[sp + 1..].to_string();
        lines.push((path, e.clone()));
    }
    lines.sort();
    for (_, e) in lines.iter() {
        out.push_str(e);
        out.push('\n');
    }
    out.push_str(&format!("unchanged {}\n", unchanged));

    // update index
    for p in old.iter() {
        if !current.contains(p) {
            let ws = get_list(&index, &format!("w:{}", p));
            for w in ws.iter() {
                let k = format!("i:{}", w);
                let mut l = get_list(&index, &k);
                l.retain(|x| x != p);
                put_list(&index, &k, &l);
            }
            index.delete(&format!("w:{}", p));
            index.delete(&format!("c:{}", p));
        }
    }
    for p in current.iter() {
        let text = docs.read(p)?;
        let key = format!("c:{}", p);
        let same = match index.get(&key) {
            Some(t) => t == text,
            None => false,
        };
        if same {
            continue;
        }
        let ws_old = get_list(&index, &format!("w:{}", p));
        for w in ws_old.iter() {
            let k = format!("i:{}", w);
            let mut l = get_list(&index, &k);
            l.retain(|x| x != p);
            put_list(&index, &k, &l);
        }
        let ws = words_of(&text);
        for w in ws.iter() {
            let k = format!("i:{}", w);
            let mut l = get_list(&index, &k);
            l.push(p.clone());
            put_list(&index, &k, &l);
        }
        put_list(&index, &format!("w:{}", p), &ws);
        index.set(&key, &text);
    }
    put_list(&index, "files", &current);

    // queries
    let qtext = queries.read("queries.txt")?;
    for line in qtext.split("\n") {
        let line = line.trim_end_matches("\r");
        if line.trim().is_empty() {
            continue;
        }
        let ws = words_of(line);
        let mut result: Vec<String> = Vec::new();
        let mut first = true;
        for w in ws.iter() {
            let l = get_list(&index, &format!("i:{}", w));
            if first {
                result = l;
                first = false;
            } else {
                result.retain(|x| l.contains(x));
            }
        }
        result.sort();
        if result.is_empty() {
            out.push_str(&format!("{}: none\n", line));
        } else {
            out.push_str(&format!("{}: {}\n", line, result.join(", ")));
        }
    }
    Ok(out)
}

