    for p in old.iter() {
        all.push(p.clone());
    }
    for p in current.iter() {
        if !old.contains(p) {
            all.push(p.clone());
        }
    }
    all.sort();
    for p in all.iter() {
        if !current.contains(p) {
            out.push_str(format!("removed {}\n", p));
        } else {
            let text = docs.read(p)?;
            let key = format!("c:{}", p);
            let prev = index.get(key);
            match prev {
                None => {
                    out.push_str(format!("added {}\n", p));
                }
                Some(t) => {
                    if t == text {
                        unchanged += 1;
                    } else {
                        out.push_str(format!("changed {}\n", p));
                    }
                }
            }
        }
    }
    out.push_str(format!("unchanged {}\n", unchanged));

    for p in old.iter() {
        if !current.contains(p) {
            let ws = get_list(index, format!("w:{}", p));
            for w in ws.iter() {
                let k = format!("i:{}", w);
                let mut l = get_list(index, k);
                l.retain(|x| x != p);
                put_list(index, k, l);
            }
            index.delete(format!("w:{}", p));
            index.delete(format!("c:{}", p));
        }
    }
    for p in current.iter() {
        let text = docs.read(p)?;
        let key = format!("c:{}", p);
        let same = match index.get(key) {
            Some(t) => t == text,
            None => false,
        };
        if same {
            continue;
        }
        let ws_old = get_list(index, format!("w:{}", p));
        for w in ws_old.iter() {
            let k = format!("i:{}", w);
            let mut l = get_list(index, k);
            l.retain(|x| x != p);
            put_list(index, k, l);
        }
        let ws = words_of(text);
        for w in ws.iter() {
            let k = format!("i:{}", w);
            let mut l = get_list(index, k);
            l.push(p.clone());
            put_list(index, k, l);
        }
        put_list(index, format!("w:{}", p), ws);
        index.set(key, text);
    }
    put_list(index, "files", current);

    let qtext = queries.read("queries.txt")?;
    for line in qtext.split("\n") {
        let line = line.trim_end_matches("\r");
        if line.trim().is_empty() {
            continue;
        }
        let ws = words_of(line);
        let mut result: Vec<String> = Vec::new();
        let mut first = true;
        for w in ws.iter() {
            let l = get_list(index, format!("i:{}", w));
            if first {
                result = l;
                first = false;
            } else {
                result.retain(|x| l.contains(x));
            }
        }
        result.sort();
        if result.is_empty() {
            out.push_str(format!("{}: none\n", line));
        } else {
            out.push_str(format!("{}: {}\n", line, result.join(", ")));
        }
    }
    Ok(out)
}

fn words_of(text: Str) -> Vec<String> {
    let seps = "! \" # $ % & ' ( ) * + , - . / : ; < = > ? @ [ \\ ] ^ _ ` { | } ~ \n \r \t";
    let mut t = text.to_string();
    for sp in seps.split(" ") {
        if !sp.is_empty() {
            t = t.replace(sp, " ");
        }
    }
    let mut out: Vec<String> = Vec::new();
    for w in t.split(" ") {
        if !w.is_empty() {
            out.push(w.to_lowercase());
        }
    }
    out.sort();
    out.dedup();
    out
}

fn split_lines(s: Str) -> Vec<String> {
    let mut v: Vec<String> = Vec::new();
    for l in s.split("\n") {
        if !l.is_empty() {
            v.push(l.to_string());
        }
    }
    v
}

fn get_list(index: Kv, key: Str) -> Vec<String> {
    match index.get(key) {
        Some(s) => split_lines(s),
        None => Vec::new(),
    }
}

fn put_list(index: Kv, key: Str, v: Vec<String>) {
    if v.is_empty() {
        index.delete(key);
    } else {
        index.set(key, v.join("\n"));
    }
}

