fn main(api: Http, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)")?;
    db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)")?;
    db.exec("CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL)")?;

    let mut cursor: Str = "0";
    let saved = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
    if saved.len() > 0 {
        cursor = saved[0].get_str(0)?;
    }

    let mut pages = 0;
    let mut applied = 0;
    let mut stale = 0;
    let mut invalid = 0;
    let mut status_line = "complete";

    loop {
        let path = "/changes?cursor=" + cursor;
        let resp = match api.get(path) {
            Ok(r) => r,
            Err(_) => {
                status_line = "stopped at " + cursor + " (no response)";
                break;
            }
        };
        if resp.status != 200 {
            status_line = "stopped at " + cursor + " (status " + resp.status.to_string() + ")";
            break;
        }
        let parsed = json::parse(resp.body);
        let doc = match parsed {
            Ok(d) => d,
            Err(_) => {
                status_line = "stopped at " + cursor + " (invalid page)";
                break;
            }
        };
        if !doc.is_object() || !doc.get("changes").is_array() {
            status_line = "stopped at " + cursor + " (invalid page)";
            break;
        }
        let changes = doc.get("changes").as_array();
        let next = doc.get("next");

        let mut pa = 0;
        let mut ps = 0;
        let mut pi = 0;

        db.exec("BEGIN")?;
        for ch in changes {
            if !ch.is_object() {
                pi += 1;
                continue;
            }
            let op = ch.get("op");
            let sku = ch.get("sku");
            let ver = ch.get("version");
            if !op.is_string() || !sku.is_string() || !ver.is_int() {
                pi += 1;
                continue;
            }
            let opname = op.as_str();
            let skus = sku.as_str();
            let v = ver.as_int();
            let is_upsert = opname == "upsert";
            let is_delete = opname == "delete";
            if !is_upsert && !is_delete {
                pi += 1;
                continue;
            }
            if is_upsert {
                if !ch.get("name").is_string() || !ch.get("qty").is_int() {
                    pi += 1;
                    continue;
                }
            }
            let cur = db.query("SELECT version FROM versions WHERE sku = ?", [skus])?;
            if cur.len() > 0 {
                if v <= cur[0].get_int(0)? {
                    ps += 1;
                    continue;
                }
            }
            if is_upsert {
                let name = ch.get("name").as_str();
                let qty = ch.get("qty").as_int();
                db.exec("INSERT INTO items (sku, name, qty) VALUES (?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty", [skus, name, qty])?;
            } else {
                db.exec("DELETE FROM items WHERE sku = ?", [skus])?;
            }
            db.exec("INSERT INTO versions (sku, version) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version", [skus, v])?;
            pa += 1;
        }
        let mut newcur = cursor;
        if next.is_string() {
            newcur = next.as_str();
        } else if next.is_int() {
            newcur = next.as_int().to_string();
        }
        db.exec("INSERT INTO meta (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v", [newcur])?;
        db.exec("COMMIT")?;

        pages += 1;
        applied += pa;
        stale += ps;
        invalid += pi;

        if next.is_null() {
            break;
        }
        cursor = newcur;
    }

    let mut out = "pages " + pages.to_string() + " applied " + applied.to_string()
        + " stale " + stale.to_string() + " invalid " + invalid.to_string() + "\n";
    out = out + status_line + "\n";
    let rows = db.query("SELECT sku, qty, name FROM items ORDER BY sku", [])?;
    for r in rows {
        out = out + r.get_str(0)? + " " + r.get_int(1)?.to_string() + " " + r.get_str(2)? + "\n";
    }
    Ok(out)
}

