            let cur = db.query("SELECT version FROM versions WHERE sku = ?", [skus]).map_err(|_| "db error")?;
            if cur.len() > 0 {
                if v <= sv_int(cur[0][0]) {
                    ps += 1;
                    continue;
                }
            }
            if is_upsert {
                let name = ch.get("name").as_str();
                let qty = ch.get("qty").as_int();
                db.exec("INSERT INTO items (sku, name, qty) VALUES (?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty", [skus, name, qty]).map_err(|_| "db error")?;
            } else {
                db.exec("DELETE FROM items WHERE sku = ?", [skus]).map_err(|_| "db error")?;
            }
            db.exec("INSERT INTO versions (sku, version) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version", [skus, v]).map_err(|_| "db error")?;
            pa += 1;
        }
        let mut newcur = cursor;
        if next.is_string() {
            newcur = next.as_str();
        } else if next.is_int() {
            newcur = next.as_int().to_string();
        }
        db.exec("INSERT INTO meta (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v", [newcur]).map_err(|_| "db error")?;
        db.exec("COMMIT", []).map_err(|_| "db error")?;

        pages += 1;
        applied += pa;
        stale += ps;
        invalid += pi;

        if next.is_null() {
            break;
        }
        cursor = newcur;
    }

    let mut out = "pages " + pages.to_string() + " applied " + applied.to_string()
        + " stale " + stale.to_string() + " invalid " + invalid.to_string() + "\n";
    out = out + status_line + "\n";
    let rows = db.query("SELECT sku, qty, name FROM items ORDER BY sku", []).map_err(|_| "db error")?;
    for r in rows {
        let s = sv_str(r[0]);
        let q = sv_int(r[1]);
        let n = sv_str(r[2]);
        out = out + s + " " + q.to_string() + " " + n + "\n";
    }
    Ok(out)
}

fn sv_str(v: SqlValue) -> Str {
    match v {
        SqlValue::Text(s) => s,
