fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    // Enqueue
    let text = input.read("enqueue.jsonl")?;
    let mut n: i64 = 0;
    for line in text.lines() {
        n += 1;
        if line.trim() == "" {
            continue;
        }
        let v = match json::parse(line) {
            Ok(v) => v,
            Err(_) => {
                out.push(format("invalid line {}", n));
                continue;
            }
        };
        let id = v.get("id").as_str();
        let pr = v.get("priority").as_int();
        if id.is_none() || pr.is_none() {
            out.push(format("invalid line {}", n));
            continue;
        }
        let id = id.unwrap();
        let pr = pr.unwrap();
        let key = format("j:{}", id);
        if queue.get(key.clone()).is_some() {
            out.push("duplicate ID");
            continue;
        }
        let rec: Vec<i64> = vec![pr, now, 0, 0];
        queue.set(key, fmt_rec(&rec));
    }

    // Script
    let script = match json::parse(input.read("script.json")?) {
        Ok(v) => v,
        Err(_) => return Err("bad script"),
    };

    // Collect due jobs
    let mut jobs: Vec<(i64, i64, Str)> = Vec::new();
    for key in queue.keys() {
        if !key.starts_with("j:") {
            continue;
        }
        let id = key.slice(2, key.len());
        let rec = parse_rec(&queue.get(key.clone()).unwrap());
        if rec[3] == 0 && rec[1] <= now {
            jobs.push((0 - rec[0], rec[1], id));
        }
    }
    jobs.sort();

    let mut ran: i64 = 0;
    for j in jobs {
        if ran >= 5 {
            break;
        }
        ran += 1;
        let id = j.2;
        let key = format("j:{}", id);
        let mut rec = parse_rec(&queue.get(key.clone()).unwrap());
        let attempt = rec[2]; // 0-based index of this attempt
        let mut outcome = "ok";
        let list = script.get(id.clone());
        if list.is_some() {
            let arr = list.unwrap().as_array();
            if arr.len() > 0 {
                let mut idx = attempt;
                if idx >= arr.len() {
                    idx = arr.len() - 1;
                }
                outcome = arr[idx].as_str().unwrap_or("ok");
            }
        }
        rec[2] = attempt + 1;
        if outcome == "ok" {
            rec[3] = 1;
            out.push(format("done {}", id));
        } else if attempt + 1 >= 4 {
            rec[3] = 2;
            out.push(format("dead {}", id));
        } else {
            let mut secs: i64 = 60;
            for _ in 0..attempt {
                secs = secs * 2;
            }
            rec[1] = now + secs * 1000;
            out.push(format("retry {} in {}", id, secs));
        }
        queue.set(key, fmt_rec(&rec));
    }

    // Totals
    let mut p: i64 = 0;
    let mut d: i64 = 0;
    let mut x: i64 = 0;
    for key in queue.keys() {
        if !key.starts_with("j:") {
            continue;
        }
        let rec = parse_rec(&queue.get(key).unwrap());
        if rec[3] == 0 {
            p += 1;
        } else if rec[3] == 1 {
            d += 1;
        } else {
            x += 1;
        }
    }
    out.push(format("pending {} done {} dead {}", p, d, x));
    Ok(out.join("\n"))
}

