        if queue.get(key.clone()).is_some() {
            out.push("duplicate ID");
            continue;
        }
        let rec: Vec<i64> = [pr, now, 0, 0];
        queue.set(key, fmt_rec(rec));
    }

    // Script
    let script = match json::parse(input.read("script.json")?) {
        Ok(v) => v,
        Err(_) => return Err("bad script"),
    };

    // Collect due jobs (parallel vectors)
    let mut prios: Vec<i64> = Vec::new();
    let mut dues: Vec<i64> = Vec::new();
    let mut ids: Vec<Str> = Vec::new();
    let mut used: Vec<bool> = Vec::new();
    for key in queue.keys() {
        if !key.starts_with("j:") {
            continue;
        }
        let id = key.slice(2, key.len());
        let rec = parse_rec(queue.get(key.clone()).unwrap());
        if rec[3] == 0 && rec[1] <= now {
            prios.push(rec[0]);
            dues.push(rec[1]);
            ids.push(id);
            used.push(false);
        }
    }

    let total = ids.len();
    for _ in 0..5 {
        let mut best: i64 = 0 - 1;
        for i in 0..total {
            if used[i] {
                continue;
            }
            if best < 0 {
                best = i;
                continue;
            }
            let b = best;
            let mut better = false;
            if prios[i] > prios[b] {
                better = true;
            } else if prios[i] == prios[b] {
                if dues[i] < dues[b] {
                    better = true;
                } else if dues[i] == dues[b] {
                    if ids[i] < ids[b] {
                        better = true;
                    }
                }
            }
            if better {
                best = i;
            }
        }
        if best < 0 {
            break;
        }
        used[best] = true;
        let id = ids[best].clone();
        let key = format("j:{}", id);
        let mut rec = parse_rec(queue.get(key.clone()).unwrap());
