    // Enqueue
    let text = input.read("enqueue.jsonl")?;
    let mut n: Int = 0;
    for line in text.lines() {
        n += 1;
        if line.trim() == "" {
            continue;
        }
        let v = match json::parse(line) {
            Ok(v) => v,
            Err(_) => {
                out.push(format("invalid line {}", n));
                continue;
            }
        };
        let id = v.get("id").as_str();
        let pr = v.get("priority").as_int();
        if id.is_none() || pr.is_none() {
            out.push(format("invalid line {}", n));
            continue;
        }
        let id = id.unwrap();
        let pr = pr.unwrap();
        let key = format("j:{}", id);
        if queue.get(key.clone()).is_some() {
            out.push("duplicate ID");
            continue;
        }
        let rec: List<Int> = [pr, now, 0, 0];
        queue.set(key, fmt_rec(rec));
    }

    // Script
    let script = match json::parse(input.read("script.json")?) {
        Ok(v) => v,
        Err(_) => return Err("bad script"),
    };

    // Collect due jobs (parallel lists)
    let mut prios: List<Int> = List::new();
    let mut dues: List<Int> = List::new();
    let mut ids: List<Str> = List::new();
    let mut used: List<Bool> = List::new();
    for key in queue.keys() {
        if !key.starts_with("j:") {
            continue;
        }
        let id = key.slice(2, key.len());
        let rec = parse_rec(queue.get(key.clone()).unwrap());
        if rec[3] == 0 && rec[1] <= now {
            prios.push(rec[0]);
            dues.push(rec[1]);
            ids.push(id);
            used.push(false);
        }
    }

    let total = ids.len();
    for _ in 0..5 {
        let mut best: Int = 0 - 1;
        for i in 0..total {
            if used[i] {
                continue;
            }
            if best < 0 {
                best = i;
                continue;
            }
            let b = best;
            let mut better = false;
            if prios[i] > prios[b] {
                better = true;
            } else if prios[i] == prios[b] {
                if dues[i] < dues[b] {
                    better = true;
                } else if dues[i] == dues[b] {
                    if ids[i] < ids[b] {
                        better = true;
                    }
                }
            }
            if better {
                best = i;
            }
        }
        if best < 0 {
            break;
        }
        used[best] = true;
        let id = ids[best].clone();
        let key = format("j:{}", id);
        let mut rec = parse_rec(queue.get(key.clone()).unwrap());
        let attempt = rec[2];
        let mut outcome = "ok";
        let list = script.get(id.clone());
        if list.is_some() {
            let arr = list.unwrap().as_array();
            if arr.len() > 0 {
                let mut idx = attempt;
                if idx >= arr.len() {
                    idx = arr.len() - 1;
                }
                outcome = arr[idx].as_str().unwrap_or("ok");
            }
        }
        rec[2] = attempt + 1;
        if outcome == "ok" {
            rec[3] = 1;
            out.push(format("done {}", id));
        } else if attempt + 1 >= 4 {
            rec[3] = 2;
            out.push(format("dead {}", id));
        } else {
            let mut secs: Int = 60;
            for _ in 0..attempt {
                secs = secs * 2;
            }
            rec[1] = now + secs * 1000;
            out.push(format("retry {} in {}", id, secs));
        }
        queue.set(key, fmt_rec(rec));
    }

    // Totals
    let mut p: Int = 0;
    let mut d: Int = 0;
    let mut x: Int = 0;
    for key in queue.keys() {
        if !key.starts_with("j:") {
            continue;
        }
        let rec = parse_rec(queue.get(key).unwrap());
        if rec[3] == 0 {
            p += 1;
        } else if rec[3] == 1 {
            d += 1;
        } else {
            x += 1;
        }
    }
    out.push(format("pending {} done {} dead {}", p, d, x));
    Ok(out.join("\n"))
}

enum Tok {
    Int(String),
    Name(String),
    Op(u8),
}

enum Node {
    Num(i64, bool),
    Var(String),
    Neg(Box<Node>),
    Bin(u8, Box<Node>, Box<Node>),
    Call(String, Vec<Node>),
}

fn tokenize(line: &str) -> Option<Vec<Tok>> {
    let b = line.as_bytes();
    let mut toks: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' {
            i += 1;
        } else if c >= b'0' && c <= b'9' {
            let mut s = String::new();
            while i < b.len() && b[i] >= b'0' && b[i] <= b'9' {
                s.push(b[i] as char);
                i += 1;
            }
            toks.push(Tok::Int(s));
        } else if (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || c == b'_' {
            let mut s = String::new();
            while i < b.len()
                && ((b[i] >= b'a' && b[i] <= b'z')
                    || (b[i] >= b'A' && b[i] <= b'Z')
                    || b[i] == b'_'
                    || (b[i] >= b'0' && b[i] <= b'9'))
            {
                s.push(b[i] as char);
                i += 1;
            }
            toks.push(Tok::Name(s));
        } else if c == b'+' || c == b'-' || c == b'*' || c == b'/' || c == b'%' || c == b'^'
            || c == b'(' || c == b')' || c == b',' || c == b'='
        {
            toks.push(Tok::Op(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn is_op(toks: &Vec<Tok>, pos: usize, op: u8) -> bool {
    if pos < toks.len() {
        match &toks[pos] {
            Tok::Op(c) => *c == op,
            _ => false,
        }
    } else {
        false
    }
}

fn parse_expr(toks: &Vec<Tok>, pos: &mut usize) -> Option<Node> {
    let mut left = parse_term(toks, pos)?;
    loop {
        if is_op(toks, *pos, b'+') || is_op(toks, *pos, b'-') {
            let op = match &toks[*pos] {
                Tok::Op(c) => *c,
                _ => 0,
            };
            *pos += 1;
            let right = parse_term(toks, pos)?;
            left = Node::Bin(op, Box::new(left), Box::new(right));
        } else {
            break;
        }
    }
    Some(left)
}

fn parse_term(toks: &Vec<Tok>, pos: &mut usize) -> Option<Node> {
    let mut left = parse_factor(toks, pos)?;
    loop {
        if is_op(toks, *pos, b'*') || is_op(toks, *pos, b'/') || is_op(toks, *pos, b'%') {
            let op = match &toks[*pos] {
                Tok::Op(c) => *c,
                _ => 0,
            };
            *pos += 1;
            let right = parse_factor(toks, pos)?;
            left = Node::Bin(op, Box::new(left), Box::new(right));
        } else {
            break;
        }
    }
    Some(left)
}

fn parse_factor(toks: &Vec<Tok>, pos: &mut usize) -> Option<Node> {
    if is_op(toks, *pos, b'-') {
        *pos += 1;
        let f = parse_factor(toks, pos)?;
        return Some(Node::Neg(Box::new(f)));
    }
    let base = parse_atom(toks, pos)?;
    if is_op(toks, *pos, b'^') {
        *pos += 1;
        let e = parse_factor(toks, pos)?;
        return Some(Node::Bin(b'^', Box::new(base), Box::new(e)));
    }
    Some(base)
}

fn parse_atom(toks: &Vec<Tok>, pos: &mut usize) -> Option<Node> {
    if *pos >= toks.len() {
        return None;
    }
    match &toks[*pos] {
        Tok::Int(s) => {
            *pos += 1;
            let mut v: i64 = 0;
            let mut ok = true;
            for ch in s.as_bytes() {
                let d = (*ch - b'0') as i64;
                match v.checked_mul(10) {
                    Some(x) => match x.checked_add(d) {
                        Some(y) => {
                            v = y;
                        }
                        None => {
                            ok = false;
                            break;
                        }
                    },
                    None => {
                        ok = false;
                        break;
                    }
                }
            }
            Some(Node::Num(v, ok))
        }
        Tok::Name(name) => {
            *pos += 1;
            if is_op(toks, *pos, b'(') {
                *pos += 1;
                let mut args: Vec<Node> = Vec::new();
                let first = parse_expr(toks, pos)?;
                args.push(first);
                while is_op(toks, *pos, b',') {
                    *pos += 1;
                    let a = parse_expr(toks, pos)?;
                    args.push(a);
                }
                if is_op(toks, *pos, b')') {
                    *pos += 1;
                    Some(Node::Call(name.clone(), args))
                } else {
                    None
                }
            } else {
                Some(Node::Var(name.clone()))
            }
        }
        Tok::Op(c) => {
            if *c == b'(' {
                *pos += 1;
                let e = parse_expr(toks, pos)?;
                if is_op(toks, *pos, b')') {
                    *pos += 1;
                    Some(e)
                } else {
                    None
                }
            } else {
                None
            }
        }
    }
}

fn power(base: i64, exp: i64) -> Result<i64, String> {
    if base == 0 {
        if exp == 0 {
            return Ok(1);
        }
        return Ok(0);
    }
    if base == 1 {
        return Ok(1);
    }
    if base == -1 {
        if exp % 2 == 0 {
            return Ok(1);
        }
        return Ok(-1);
    }
    let mut result: i64 = 1;
    let mut i: i64 = 0;
    while i < exp {
        match result.checked_mul(base) {
            Some(r) => {
                result = r;
            }
            None => {
                return Err(String::from("overflow"));
            }
        }
        i += 1;
    }
    Ok(result)
}

fn eval(n: &Node, vars: &Vec<(String, i64)>) -> Result<i64, String> {
    match n {
        Node::Num(v, ok) => {
            if *ok {
                Ok(*v)
            } else {
                Err(String::from("overflow"))
            }
        }
        Node::Var(name) => {
            let mut i = vars.len();
            while i > 0 {
                i -= 1;
                if vars[i].0 == *name {
                    return Ok(vars[i].1);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(e) => {
            let v = eval(e, vars)?;
            match v.checked_neg() {
                Some(r) => Ok(r),
                None => Err(String::from("overflow")),
            }
        }
        Node::Bin(op, l, r) => {
            let a = eval(l, vars)?;
            let b = eval(r, vars)?;
            let op = *op;
            if op == b'+' {
                match a.checked_add(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'-' {
                match a.checked_sub(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'*' {
                match a.checked_mul(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'/' {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                match a.checked_div(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'%' {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                if b == -1 {
                    return Ok(0);
                }
                match a.checked_rem(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                if b < 0 {
                    return Err(String::from("negative exponent"));
                }
                power(a, b)
            }
        }
        Node::Call(name, args) => {
            let expected: usize = if name == "min" || name == "max" {
                2
            } else if name == "abs" {
                1
            } else {
                return Err(format!("unknown function {}", name));
            };
            if args.len() != expected {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let a = eval(&args[0], vars)?;
            if expected == 1 {
                match a.checked_abs() {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                let b = eval(&args[1], vars)?;
                if name == "min" {
                    Ok(if a < b { a } else { b })
                } else {
                    Ok(if a > b { a } else { b })
                }
            }
        }
    }
}

fn process(line: &str, vars: &mut Vec<(String, i64)>) -> String {
    let toks = match tokenize(line) {
        Some(t) => t,
        None => return String::from("error: syntax error"),
    };
    let mut is_let = false;
    if toks.len() > 0 {
        match &toks[0] {
            Tok::Name(s) => {
                if s == "let" {
                    is_let = true;
                }
            }
            _ => {}
        }
    }
    let mut pos: usize = 0;
    let mut let_name = String::new();
    if is_let {
        if toks.len() < 3 {
            return String::from("error: syntax error");
        }
        match &toks[1] {
            Tok::Name(s) => {
                let_name = s.clone();
            }
            _ => return String::from("error: syntax error"),
        }
        if !is_op(&toks, 2, b'=') {
            return String::from("error: syntax error");
        }
        pos = 3;
    }
    let node = match parse_expr(&toks, &mut pos) {
        Some(n) => n,
        None => return String::from("error: syntax error"),
    };
    if pos != toks.len() {
        return String::from("error: syntax error");
    }
    match eval(&node, vars) {
        Ok(v) => {
            if is_let {
                vars.push((let_name.clone(), v));
                format!("{} = {}", let_name, v)
            } else {
                format!("{}", v)
            }
        }
        Err(m) => format!("error: {}", m),
    }
}

fn main(input: Dir) -> Str {
    let text = input.read_to_string("program.txt");
    let mut out = String::new();
    let mut vars: Vec<(String, i64)> = Vec::new();
    let mut n: usize = 0;
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue;
        }
        n += 1;
        let r = process(line, &mut vars);
        out.push_str(&format!("{}: {}\n", n, r));
    }
    out
}

enum Tok {
    Int(String),
    Name(String),
    Op(u8),
}

enum Node {
    Num(i64, bool),
    Var(String),
    Neg(Box<Node>),
    Bin(u8, Box<Node>, Box<Node>),
    Call(String, Vec<Node>),
}

fn tokenize(line: Str) -> Option<Vec<Tok>> {
    let b = line.as_bytes();
    let mut toks: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
