fn tokenize(line: Str) -> Option<Vec<Tok>> {
    let b = line.as_bytes();
    let mut toks: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == b' ' || c == b'\t' || c == b'\r' {
            i += 1;
        } else if c >= b'0' && c <= b'9' {
            let mut s = String::new();
            while i < b.len() && b[i] >= b'0' && b[i] <= b'9' {
                s.push_str(ch(b[i]));
                i += 1;
            }
            toks.push(Tok::Int(s));
        } else if (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || c == b'_' {
            let mut s = String::new();
            while i < b.len()
                && ((b[i] >= b'a' && b[i] <= b'z')
                    || (b[i] >= b'A' && b[i] <= b'Z')
                    || b[i] == b'_'
                    || (b[i] >= b'0' && b[i] <= b'9'))
            {
                s.push_str(ch(b[i]));
                i += 1;
            }
            toks.push(Tok::Name(s));
        } else if c == b'+' || c == b'-' || c == b'*' || c == b'/' || c == b'%' || c == b'^'
            || c == b'(' || c == b')' || c == b',' || c == b'='
        {
            toks.push(Tok::Op(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn is_op(toks: Vec<Tok>, pos: usize, op: u8) -> bool {
    if pos < toks.len() {
        match toks[pos] {
            Tok::Op(c) => c == op,
            _ => false,
        }
    } else {
        false
    }
}

fn op_at(toks: Vec<Tok>, pos: usize) -> u8 {
    match toks[pos] {
        Tok::Op(c) => c,
        _ => 0,
    }
}

fn parse_expr(toks: Vec<Tok>, pos: usize) -> Option<(Node, usize)> {
    let r = parse_term(toks, pos)?;
    let mut left = r.0;
    let mut p = r.1;
    loop {
        if is_op(toks, p, b'+') || is_op(toks, p, b'-') {
            let op = op_at(toks, p);
            let r2 = parse_term(toks, p + 1)?;
            left = Node::Bin(op, Box::new(left), Box::new(r2.0));
            p = r2.1;
        } else {
            break;
        }
    }
    Some((left, p))
}

fn parse_term(toks: Vec<Tok>, pos: usize) -> Option<(Node, usize)> {
    let r = parse_factor(toks, pos)?;
    let mut left = r.0;
    let mut p = r.1;
    loop {
        if is_op(toks, p, b'*') || is_op(toks, p, b'/') || is_op(toks, p, b'%') {
            let op = op_at(toks, p);
            let r2 = parse_factor(toks, p + 1)?;
            left = Node::Bin(op, Box::new(left), Box::new(r2.0));
            p = r2.1;
        } else {
            break;
        }
    }
    Some((left, p))
}

fn parse_factor(toks: Vec<Tok>, pos: usize) -> Option<(Node, usize)> {
    if is_op(toks, pos, b'-') {
        let r = parse_factor(toks, pos + 1)?;
        return Some((Node::Neg(Box::new(r.0)), r.1));
    }
    let r = parse_atom(toks, pos)?;
    let base = r.0;
    let p = r.1;
    if is_op(toks, p, b'^') {
        let r2 = parse_factor(toks, p + 1)?;
        return Some((Node::Bin(b'^', Box::new(base), Box::new(r2.0)), r2.1));
    }
    Some((base, p))
}

fn parse_int(s: String) -> Node {
    let bytes = s.as_bytes();
    let mut v: i64 = 0;
    let mut ok = true;
    let mut i: usize = 0;
    while i < bytes.len() {
        let d = (bytes[i] - b'0') as i64;
        match v.checked_mul(10) {
            Some(x) => match x.checked_add(d) {
                Some(y) => {
                    v = y;
                }
                None => {
                    ok = false;
                    break;
                }
            },
            None => {
                ok = false;
                break;
            }
        }
        i += 1;
    }
    Node::Num(v, ok)
}

fn parse_atom(toks: Vec<Tok>, pos: usize) -> Option<(Node, usize)> {
    if pos >= toks.len() {
        return None;
    }
    match toks[pos] {
        Tok::Int(s) => Some((parse_int(s), pos + 1)),
        Tok::Name(name) => {
            if is_op(toks, pos + 1, b'(') {
                let mut args: Vec<Node> = Vec::new();
                let r = parse_expr(toks, pos + 2)?;
                args.push(r.0);
                let mut p = r.1;
                while is_op(toks, p, b',') {
                    let r2 = parse_expr(toks, p + 1)?;
                    args.push(r2.0);
                    p = r2.1;
                }
                if is_op(toks, p, b')') {
                    Some((Node::Call(name, args), p + 1))
                } else {
                    None
                }
            } else {
                Some((Node::Var(name), pos + 1))
            }
        }
        Tok::Op(c) => {
            if c == b'(' {
                let r = parse_expr(toks, pos + 1)?;
                if is_op(toks, r.1, b')') {
                    Some((r.0, r.1 + 1))
                } else {
                    None
                }
            } else {
                None
            }
        }
    }
}

fn power(base: i64, exp: i64) -> Result<i64, String> {
    if base == 0 {
        if exp == 0 {
            return Ok(1);
        }
        return Ok(0);
    }
    if base == 1 {
        return Ok(1);
    }
    if base == -1 {
        if exp % 2 == 0 {
            return Ok(1);
        }
        return Ok(-1);
    }
    let mut result: i64 = 1;
    let mut i: i64 = 0;
    while i < exp {
        match result.checked_mul(base) {
            Some(r) => {
                result = r;
            }
            None => {
                return Err(String::from("overflow"));
            }
        }
        i += 1;
    }
    Ok(result)
}

fn eval(n: Node, vars: Vec<(String, i64)>) -> Result<i64, String> {
    match n {
        Node::Num(v, ok) => {
            if ok {
                Ok(v)
            } else {
                Err(String::from("overflow"))
            }
        }
        Node::Var(name) => {
            let mut i = vars.len();
            while i > 0 {
                i -= 1;
                if vars[i].0 == name {
                    return Ok(vars[i].1);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(e) => {
            let v = eval(*e, vars)?;
            match v.checked_neg() {
                Some(r) => Ok(r),
                None => Err(String::from("overflow")),
            }
        }
        Node::Bin(op, l, r) => {
            let a = eval(*l, vars)?;
            let b = eval(*r, vars)?;
            if op == b'+' {
                match a.checked_add(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'-' {
                match a.checked_sub(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'*' {
                match a.checked_mul(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'/' {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                match a.checked_div(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == b'%' {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                if b == -1 {
                    return Ok(0);
                }
                match a.checked_rem(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                if b < 0 {
                    return Err(String::from("negative exponent"));
                }
                power(a, b)
            }
        }
        Node::Call(name, args) => {
            let expected: usize = if name == "min" || name == "max" {
                2
            } else if name == "abs" {
                1
            } else {
                return Err(format!("unknown function {}", name));
            };
            if args.len() != expected {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let a = eval(args[0], vars)?;
            if expected == 1 {
                match a.checked_abs() {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                let b = eval(args[1], vars)?;
                if name == "min" {
                    Ok(if a < b { a } else { b })
                } else {
                    Ok(if a > b { a } else { b })
                }
            }
        }
    }
}

