            }
        }
        Node::Var(name) => {
            let mut i = vars.len();
            while i > 0 {
                i -= 1;
                if vars[i].0 == name {
                    return Ok(vars[i].1);
                }
            }
            Err(format!("unknown variable {}", name))
        }
        Node::Neg(e) => {
            let v = eval(*e, vars)?;
            match v.checked_neg() {
                Some(r) => Ok(r),
                None => Err(String::from("overflow")),
            }
        }
        Node::Bin(op, l, r) => {
            let a = eval(*l, vars)?;
            let b = eval(*r, vars)?;
            if op == 43 {
                match a.checked_add(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == 45 {
                match a.checked_sub(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == 42 {
                match a.checked_mul(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == 47 {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                match a.checked_div(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else if op == 37 {
                if b == 0 {
                    return Err(String::from("division by zero"));
                }
                if b == -1 {
                    return Ok(0);
                }
                match a.checked_rem(b) {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                if b < 0 {
                    return Err(String::from("negative exponent"));
                }
                power(a, b)
            }
        }
        Node::Call(name, args) => {
            let expected: usize = if name == "min" || name == "max" {
                2
            } else if name == "abs" {
                1
            } else {
                return Err(format!("unknown function {}", name));
            };
            if args.len() != expected {
                return Err(format!("wrong number of arguments to {}", name));
            }
            let a = eval(args[0], vars)?;
            if expected == 1 {
                match a.checked_abs() {
                    Some(x) => Ok(x),
                    None => Err(String::from("overflow")),
                }
            } else {
                let b = eval(args[1], vars)?;
                if name == "min" {
                    Ok(if a < b { a } else { b })
                } else {
                    Ok(if a > b { a } else { b })
                }
            }
        }
    }
}

fn process(line: Str, vars: Vec<(String, i64)>) -> (String, Vec<(String, i64)>) {
    let syn = String::from("error: syntax error");
    let toks = match tokenize(line) {
        Some(t) => t,
        None => return (syn, vars),
    };
    let mut is_let = false;
    if toks.len() > 0 {
        match toks[0] {
            Tok::Name(s) => {
                if s == "let" {
                    is_let = true;
                }
            }
            _ => {}
        }
    }
    let mut pos: usize = 0;
    let mut let_name = String::new();
    if is_let {
        if toks.len() < 3 {
            return (syn, vars);
        }
        match toks[1] {
            Tok::Name(s) => {
                let_name = s;
            }
            _ => return (syn, vars),
        }
        if !is_op(toks, 2, 61) {
            return (syn, vars);
        }
        pos = 3;
    }
    let r = match parse_expr(toks, pos) {
        Some(x) => x,
        None => return (syn, vars),
    };
    if r.1 != toks.len() {
        return (syn, vars);
    }
    let mut vs = vars;
    match eval(r.0, vs) {
        Ok(v) => {
            if is_let {
                vs.push((let_name, v));
                (format!("{} = {}", let_name, v), vs)
            } else {
                (format!("{}", v), vs)
            }
        }
        Err(m) => (format!("error: {}", m), vs),
    }
}

