enum Tok {
    Int(String),
    Name(String),
    Op(u8),
}

enum Node {
    Num(i64, bool),
    Var(String),
    Neg(Box<Node>),
    Bin(u8, Box<Node>, Box<Node>),
    Call(String, Vec<Node>),
}

struct PR {
    node: Node,
    pos: usize,
}

struct VarB {
    name: String,
    val: i64,
}

struct Out {
    text: String,
    vars: Vec<VarB>,
}

