fn tokenize(line: Str) -> Option<Vec<Tok>> {
    let b = line.as_bytes();
    let mut toks: Vec<Tok> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == 32 || c == 9 || c == 13 {
            i += 1;
        } else if c >= 48 && c <= 57 {
            let mut s = String::new();
            while i < b.len() && b[i] >= 48 && b[i] <= 57 {
                s.push_str(ch(b[i]));
                i += 1;
            }
            toks.push(Tok::Int(s));
        } else if (c >= 97 && c <= 122) || (c >= 65 && c <= 90) || c == 95 {
            let mut s = String::new();
            while i < b.len()
                && ((b[i] >= 97 && b[i] <= 122)
                    || (b[i] >= 65 && b[i] <= 90)
                    || b[i] == 95
                    || (b[i] >= 48 && b[i] <= 57))
            {
                s.push_str(ch(b[i]));
                i += 1;
            }
            toks.push(Tok::Name(s));
        } else if c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94
            || c == 40 || c == 41 || c == 44 || c == 61
        {
            toks.push(Tok::Op(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn is_op(toks: Vec<Tok>, pos: usize, op: u8) -> bool {
    if pos < toks.len() {
        match toks[pos] {
            Tok::Op(c) => c == op,
            _ => false,
        }
    } else {
        false
    }
}

fn op_at(toks: Vec<Tok>, pos: usize) -> u8 {
    match toks[pos] {
        Tok::Op(c) => c,
        _ => 0,
    }
}

fn parse_expr(toks: Vec<Tok>, pos: usize) -> Option<PR> {
    let r = parse_term(toks, pos)?;
    let mut left = r.node;
    let mut p = r.pos;
    loop {
        if is_op(toks, p, 43) || is_op(toks, p, 45) {
            let op = op_at(toks, p);
            let r2 = parse_term(toks, p + 1)?;
            left = Node::Bin(op, Box::new(left), Box::new(r2.node));
            p = r2.pos;
        } else {
            break;
        }
    }
    Some(PR { node: left, pos: p })
}

fn parse_term(toks: Vec<Tok>, pos: usize) -> Option<PR> {
    let r = parse_factor(toks, pos)?;
    let mut left = r.node;
    let mut p = r.pos;
    loop {
        if is_op(toks, p, 42) || is_op(toks, p, 47) || is_op(toks, p, 37) {
            let op = op_at(toks, p);
            let r2 = parse_factor(toks, p + 1)?;
            left = Node::Bin(op, Box::new(left), Box::new(r2.node));
            p = r2.pos;
        } else {
            break;
        }
    }
    Some(PR { node: left, pos: p })
}

fn parse_factor(toks: Vec<Tok>, pos: usize) -> Option<PR> {
    if is_op(toks, pos, 45) {
        let r = parse_factor(toks, pos + 1)?;
        return Some(PR { node: Node::Neg(Box::new(r.node)), pos: r.pos });
    }
    let r = parse_atom(toks, pos)?;
    let base = r.node;
    let p = r.pos;
    if is_op(toks, p, 94) {
        let r2 = parse_factor(toks, p + 1)?;
        return Some(PR {
            node: Node::Bin(94, Box::new(base), Box::new(r2.node)),
            pos: r2.pos,
        });
    }
    Some(PR { node: base, pos: p })
}

fn parse_int(s: String) -> Node {
    let bytes = s.as_bytes();
    let mut v: i64 = 0;
    let mut ok = true;
    let mut i: usize = 0;
    while i < bytes.len() {
        let d = (bytes[i] - 48) as i64;
        match v.checked_mul(10) {
            Some(x) => match x.checked_add(d) {
                Some(y) => {
                    v = y;
                }
                None => {
                    ok = false;
                    break;
                }
            },
            None => {
                ok = false;
                break;
            }
        }
        i += 1;
    }
    Node::Num(v, ok)
}

fn parse_atom(toks: Vec<Tok>, pos: usize) -> Option<PR> {
    if pos >= toks.len() {
        return None;
    }
    match toks[pos] {
        Tok::Int(s) => Some(PR { node: parse_int(s), pos: pos + 1 }),
        Tok::Name(name) => {
            if is_op(toks, pos + 1, 40) {
                let mut args: Vec<Node> = Vec::new();
                let r = parse_expr(toks, pos + 2)?;
                args.push(r.node);
                let mut p = r.pos;
                while is_op(toks, p, 44) {
                    let r2 = parse_expr(toks, p + 1)?;
                    args.push(r2.node);
                    p = r2.pos;
                }
                if is_op(toks, p, 41) {
                    Some(PR { node: Node::Call(name, args), pos: p + 1 })
                } else {
                    None
                }
            } else {
                Some(PR { node: Node::Var(name), pos: pos + 1 })
            }
        }
        Tok::Op(c) => {
            if c == 40 {
                let r = parse_expr(toks, pos + 1)?;
                if is_op(toks, r.pos, 41) {
                    Some(PR { node: r.node, pos: r.pos + 1 })
                } else {
                    None
                }
            } else {
                None
            }
        }
    }
}

fn power(base: i64, exp: i64) -> Result<i64, String> {
    if base == 0 {
        if exp == 0 {
            return Ok(1);
        }
        return Ok(0);
    }
    if base == 1 {
        return Ok(1);
    }
    if base == -1 {
        if exp % 2 == 0 {
            return Ok(1);
        }
        return Ok(-1);
    }
    let mut result: i64 = 1;
    let mut i: i64 = 0;
    while i < exp {
        match result.checked_mul(base) {
            Some(r) => {
                result = r;
            }
            None => {
                return Err(String::from("overflow"));
            }
        }
        i += 1;
    }
    Ok(result)
}

