                }
            } else {
                let b = eval(args[1], vars)?;
                if name == "min" {
                    Ok(if a < b { a } else { b })
                } else {
                    Ok(if a > b { a } else { b })
                }
            }
        }
    }
}

fn process(line: Str, vars: Vec<VarB>) -> Out {
    let syn = String::from("error: syntax error");
    let toks = match tokenize(line) {
        Some(t) => t,
        None => return Out { text: syn, vars: vars },
    };
    let mut is_let = false;
    if toks.len() > 0 {
        match toks[0] {
            Tok::Name(s) => {
                if s == "let" {
                    is_let = true;
                }
            }
            _ => {}
        }
    }
    let mut pos: usize = 0;
    let mut let_name = String::new();
    if is_let {
        if toks.len() < 3 {
            return Out { text: syn, vars: vars };
        }
        match toks[1] {
            Tok::Name(s) => {
                let_name = s;
            }
            _ => return Out { text: syn, vars: vars },
        }
        if !is_op(toks, 2, 61) {
            return Out { text: syn, vars: vars };
        }
        pos = 3;
    }
    let r = match parse_expr(toks, pos) {
        Some(x) => x,
        None => return Out { text: syn, vars: vars },
    };
    if r.pos != toks.len() {
        return Out { text: syn, vars: vars };
    }
    let mut vs = vars;
    match eval(r.node, vs) {
        Ok(v) => {
            if is_let {
                vs.push(VarB { name: let_name, val: v });
                Out { text: format!("{} = {}", let_name, v), vars: vs }
            } else {
                Out { text: format!("{}", v), vars: vs }
            }
        }
        Err(m) => Out { text: format!("error: {}", m), vars: vs },
    }
}

