fn respond(res: Outgoing, code: Int, body: Str) -> Str {
    res.status(code);
    res.header("content-type", "application/json");
    res.send(body);
    body
}

fn next_state(t: Str, from: Str) -> Str {
    if t == "subscription.created" && from == "none" {
        return "created";
    }
    if t == "subscription.activated" && (from == "created" || from == "past_due") {
        return "active";
    }
    if t == "payment.failed" && from == "active" {
        return "past_due";
    }
    if t == "subscription.canceled" && (from == "created" || from == "active" || from == "past_due") {
        return "canceled";
    }
    ""
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Str> {
    db.execute("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY)", [])?;
    db.execute("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL)", [])?;
    db.execute("CREATE TABLE IF NOT EXISTS hist (sub TEXT NOT NULL, n INTEGER NOT NULL, state TEXT NOT NULL, PRIMARY KEY (sub, n))", [])?;
    db.execute("CREATE TABLE IF NOT EXISTS pending (sub TEXT NOT NULL, seq INTEGER NOT NULL, id TEXT NOT NULL, type TEXT NOT NULL, PRIMARY KEY (sub, seq))", [])?;

    let method = req.method();
    let path = req.path();

    if method == "POST" && path == "/webhooks" {
        let body = req.body();
        let secret = secrets.read("webhook.key")?;
        let secret = secret.trim_end_matches("\n");
        let expected = "sha256=" + hex(sha256(secret.bytes() + ".".bytes() + body));
        let given = req.header("x-signature");
        let ok = match given {
            Some(g) => constant_time_eq(g.bytes(), expected.bytes()),
            None => false,
        };
        if !ok {
            log.write("rejected signature");
            return Ok(respond(res, 401, "{\"error\": \"bad signature\"}"));
        }

        let invalid = "{\"error\": \"invalid event\"}";
        let parsed = json_parse(body);
        let v = match parsed {
            Ok(v) => v,
            Err(_) => return Ok(respond(res, 400, invalid)),
        };
        if !v.is_object() {
            return Ok(respond(res, 400, invalid));
        }
        let id = v.get("id");
        let ty = v.get("type");
        let sub = v.get("subscription");
        let seqv = v.get("seq");
        if !id.is_string() || !ty.is_string() || !sub.is_string() || !seqv.is_int() {
            return Ok(respond(res, 400, invalid));
        }
        let id = id.as_str();
        let ty = ty.as_str();
        let sub = sub.as_str();
        let seq = seqv.as_int();
        if seq < 1 {
            return Ok(respond(res, 400, invalid));
        }
        if !(ty == "subscription.created" || ty == "subscription.activated" || ty == "payment.failed" || ty == "subscription.canceled") {
            return Ok(respond(res, 400, invalid));
        }

        let seen = db.query("SELECT id FROM events WHERE id = ?", [id])?;
        if seen.len() > 0 {
            return Ok(respond(res, 200, "{\"status\": \"duplicate\"}"));
        }
        db.execute("INSERT INTO events (id) VALUES (?)", [id])?;

        let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [sub])?;
        let mut state = "none";
        let mut last = 0;
        if rows.len() > 0 {
            state = rows[0].get_str("state");
            last = rows[0].get_int("seq");
        }

        if seq <= last {
            return Ok(respond(res, 200, "{\"status\": \"stale\"}"));
        }
        if seq > last + 1 {
            db.execute("INSERT OR IGNORE INTO pending (sub, seq, id, type) VALUES (?, ?, ?, ?)", [sub, seq, id, ty])?;
            return Ok(respond(res, 202, "{\"status\": \"queued\"}"));
        }

        let mut applied = 0;
        let mut cur_id = id;
        let mut cur_ty = ty;
        let mut hist_n = db.query("SELECT COUNT(*) AS c FROM hist WHERE sub = ?", [sub])?[0].get_int("c");
        let mut more = true;
        while more {
            let ns = next_state(cur_ty, state);
            if ns == "" {
                log.write("invalid transition " + cur_id);
            } else {
                state = ns;
                hist_n = hist_n + 1;
                db.execute("INSERT INTO hist (sub, n, state) VALUES (?, ?, ?)", [sub, hist_n, state])?;
            }
            last = last + 1;
            applied = applied + 1;
            let nxt = db.query("SELECT id, type FROM pending WHERE sub = ? AND seq = ?", [sub, last + 1])?;
            if nxt.len() > 0 {
                cur_id = nxt[0].get_str("id");
                cur_ty = nxt[0].get_str("type");
                db.execute("DELETE FROM pending WHERE sub = ? AND seq = ?", [sub, last + 1])?;
            } else {
                more = false;
            }
        }
        db.execute("INSERT INTO subs (id, state, seq) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq", [sub, state, last])?;
        return Ok(respond(res, 200, "{\"status\": \"applied\", \"applied\": " + applied.to_string() + "}"));
    }

    if method == "GET" && path.starts_with("/subscriptions/") {
        let sid = path.strip_prefix("/subscriptions/");
        if sid.len() > 0 && !sid.contains("/") {
            let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [sid])?;
            if rows.len() > 0 {
                let hs = db.query("SELECT state FROM hist WHERE sub = ? ORDER BY n", [sid])?;
                let mut items = "";
                let mut first = true;
                for h in hs {
                    if !first {
                        items = items + ", ";
                    }
                    first = false;
                    items = items + json_string(h.get_str("state"));
                }
                let out = "{\"id\": " + json_string(sid) + ", \"state\": " + json_string(rows[0].get_str("state")) + ", \"seq\": " + rows[0].get_int("seq").to_string() + ", \"history\": [" + items + "]}";
                return Ok(respond(res, 200, out));
            }
        }
    }

    Ok(respond(res, 404, "{\"error\": \"not found\"}"))
}

fn respond(res: Outgoing, code: Int, body: Str) -> Str {
    res.send(code, body);
    body
}

fn next_state(t: Str, from: Str) -> Str {
    if t == "subscription.created" && from == "none" {
        return "created";
    }
    if t == "subscription.activated" && (from == "created" || from == "past_due") {
        return "active";
