                cur_id = nxt[0].get_str("id");
                cur_ty = nxt[0].get_str("type");
                db.exec("DELETE FROM pending WHERE sub = ? AND seq = ?", [sub, last + 1]).map_err(dberr)?;
            } else {
                more = false;
            }
        }
        db.exec("INSERT INTO subs (id, state, seq) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq", [sub, state, last]).map_err(dberr)?;
        return Ok(respond(res, 200, "{\"status\": \"applied\", \"applied\": " + applied.to_string() + "}"));
    }

    if method == "GET" && path.starts_with("/subscriptions/") {
        let sid = path.strip_prefix("/subscriptions/");
        if sid.len() > 0 && !sid.contains("/") {
            let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [sid]).map_err(dberr)?;
            if rows.len() > 0 {
                let hs = db.query("SELECT state FROM hist WHERE sub = ? ORDER BY n", [sid]).map_err(dberr)?;
                let mut items = "";
                let mut first = true;
                for h in hs {
                    if !first {
                        items = items + ", ";
                    }
                    first = false;
                    items = items + "\"" + h.get_str("state") + "\"";
                }
                let out = "{\"id\": \"" + sid.replace("\\", "\\\\").replace("\"", "\\\"") + "\", \"state\": \"" + rows[0].get_str("state") + "\", \"seq\": " + rows[0].get_int("seq").to_string() + ", \"history\": [" + items + "]}";
                return Ok(respond(res, 200, out));
            }
        }
    }

    Ok(respond(res, 404, "{\"error\": \"not found\"}"))
}
